  ('col-object-as-dictionary', 'quiz', 2, 75, '{"en":"Objects as keys of a plain object","uk":"Об''єкти як ключі звичайного об''єкта"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const o = {};\nconst a = { x: 1 };\nconst b = { y: 2 };\no[a] = 1;\no[b] = 2;\nconsole.log(o[a], Object.keys(o));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`2 [ ''[object Object]'' ]`","uk":"`2 [ ''[object Object]'' ]`"}},{"id":"b","text":{"en":"`1 [ ''a'', ''b'' ]`","uk":"`1 [ ''a'', ''b'' ]`"}},{"id":"c","text":{"en":"`1 [ ''[object Object]'' ]`","uk":"`1 [ ''[object Object]'' ]`"}},{"id":"d","text":{"en":"A `TypeError`: object keys must be strings","uk":"`TypeError`: ключі об''єкта мають бути рядками"}}]}'::jsonb, null::jsonb),
  ('col-json-map', 'quiz', 2, 60, '{"en":"Serialising a Map","uk":"Серіалізація Map"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const m = new Map([[\"a\", 1]]);\nconsole.log(JSON.stringify(m), JSON.stringify(Object.fromEntries(m)), JSON.stringify([...m]));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`{} {\"a\":1} [[\"a\",1]]`","uk":"`{} {\"a\":1} [[\"a\",1]]`"}},{"id":"b","text":{"en":"`{\"a\":1} {\"a\":1} [[\"a\",1]]`","uk":"`{\"a\":1} {\"a\":1} [[\"a\",1]]`"}},{"id":"c","text":{"en":"`[[\"a\",1]] {\"a\":1} [[\"a\",1]]`","uk":"`[[\"a\",1]] {\"a\":1} [[\"a\",1]]`"}},{"id":"d","text":{"en":"A `TypeError`: Maps can''t be serialised","uk":"`TypeError`: Map не можна серіалізувати"}}]}'::jsonb, null::jsonb),
  ('col-key-order', 'quiz', 3, 90, '{"en":"Key order in Maps and objects","uk":"Порядок ключів у Map і об''єктах"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const m = new Map([[\"b\", 1], [\"a\", 2]]);\nm.set(\"b\", 3);\nm.delete(\"a\");\nm.set(\"a\", 4);\nconst o = { b: 1, 2: \"x\", a: 2, 1: \"y\" };\nconsole.log([...m.keys()], Object.keys(o));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''b'', ''a'' ] [ ''1'', ''2'', ''b'', ''a'' ]`","uk":"`[ ''b'', ''a'' ] [ ''1'', ''2'', ''b'', ''a'' ]`"}},{"id":"b","text":{"en":"`[ ''a'', ''b'' ] [ ''b'', ''2'', ''a'', ''1'' ]`","uk":"`[ ''a'', ''b'' ] [ ''b'', ''2'', ''a'', ''1'' ]`"}},{"id":"c","text":{"en":"`[ ''b'', ''a'' ] [ ''b'', ''2'', ''a'', ''1'' ]`","uk":"`[ ''b'', ''a'' ] [ ''b'', ''2'', ''a'', ''1'' ]`"}},{"id":"d","text":{"en":"`[ ''a'', ''b'' ] [ ''1'', ''2'', ''a'', ''b'' ]`","uk":"`[ ''a'', ''b'' ] [ ''1'', ''2'', ''a'', ''b'' ]`"}}]}'::jsonb, null::jsonb),
  ('col-live-iteration', 'quiz', 3, 90, '{"en":"Adding to a Set while iterating it","uk":"Додавання в Set під час перебору"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const s = new Set([1]);\nfor (const x of s) {\n  if (x < 4) s.add(x + 1);\n}\nconsole.log([...s]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 1, 2, 3, 4 ]`","uk":"`[ 1, 2, 3, 4 ]`"}},{"id":"b","text":{"en":"`[ 1, 2 ]`","uk":"`[ 1, 2 ]`"}},{"id":"c","text":{"en":"It loops forever","uk":"Нескінченний цикл"}},{"id":"d","text":{"en":"A `TypeError`: the Set was modified during iteration","uk":"`TypeError`: Set змінено під час перебору"}}]}'::jsonb, null::jsonb),
  ('col-weakmap-api', 'quiz', 3, 90, '{"en":"What a WeakMap can''t do","uk":"Чого не вміє WeakMap"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const wm = new WeakMap();\nconst out = [typeof wm.size, typeof wm[Symbol.iterator]];\ntry {\n  wm.set(\"key\", 1);\n  out.push(\"ok\");\n} catch (e) {\n  out.push(e.constructor.name);\n}\nconsole.log(out);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''undefined'', ''undefined'', ''TypeError'' ]`","uk":"`[ ''undefined'', ''undefined'', ''TypeError'' ]`"}},{"id":"b","text":{"en":"`[ ''number'', ''function'', ''TypeError'' ]`","uk":"`[ ''number'', ''function'', ''TypeError'' ]`"}},{"id":"c","text":{"en":"`[ ''number'', ''function'', ''ok'' ]`","uk":"`[ ''number'', ''function'', ''ok'' ]`"}},{"id":"d","text":{"en":"`[ ''undefined'', ''undefined'', ''ok'' ]`","uk":"`[ ''undefined'', ''undefined'', ''ok'' ]`"}}]}'::jsonb, null::jsonb),
  ('col-set-methods', 'quiz', 3, 90, '{"en":"Set algebra methods","uk":"Методи алгебри множин"}'::jsonb, '{"en":"This runs in a modern engine (ES2025). What does it print?","uk":"Код виконується в сучасному рушії (ES2025). Що він виведе?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const a = new Set([1, 2, 3]);\nconst b = new Set([2, 3, 4]);\nconsole.log([...a.intersection(b)], [...a.difference(b)], [...a.symmetricDifference(b)], a.isSubsetOf(new Set([1, 2, 3, 4])));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 2, 3 ] [ 1 ] [ 1, 4 ] true`","uk":"`[ 2, 3 ] [ 1 ] [ 1, 4 ] true`"}},{"id":"b","text":{"en":"`[ 2, 3 ] [ 1, 4 ] [ 1, 4 ] true`","uk":"`[ 2, 3 ] [ 1, 4 ] [ 1, 4 ] true`"}},{"id":"c","text":{"en":"`[ 1, 2, 3, 4 ] [ 1 ] [ 1, 4 ] false`","uk":"`[ 1, 2, 3, 4 ] [ 1 ] [ 1, 4 ] false`"}},{"id":"d","text":{"en":"`[ 2, 3 ] [ 4 ] [ 1, 4 ] true`","uk":"`[ 2, 3 ] [ 4 ] [ 1, 4 ] true`"}}]}'::jsonb, null::jsonb),
  ('col-typed-array-overflow', 'quiz', 3, 90, '{"en":"Typed array conversions","uk":"Перетворення в типізованих масивах"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const u8 = new Uint8Array([255, 256, -1, 3.7]);\nconst clamped = new Uint8ClampedArray([300, -5, 1.5]);\nconsole.log([...u8], [...clamped]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 255, 0, 255, 3 ] [ 255, 0, 2 ]`","uk":"`[ 255, 0, 255, 3 ] [ 255, 0, 2 ]`"}},{"id":"b","text":{"en":"`[ 255, 255, 0, 4 ] [ 255, 0, 2 ]`","uk":"`[ 255, 255, 0, 4 ] [ 255, 0, 2 ]`"}},{"id":"c","text":{"en":"`[ 255, 256, -1, 3.7 ] [ 300, -5, 1.5 ]`","uk":"`[ 255, 256, -1, 3.7 ] [ 300, -5, 1.5 ]`"}},{"id":"d","text":{"en":"`[ 255, 0, 255, 3 ] [ 44, 251, 1 ]`","uk":"`[ 255, 0, 255, 3 ] [ 44, 251, 1 ]`"}}]}'::jsonb, null::jsonb),
  ('col-subarray-vs-slice', 'quiz', 4, 120, '{"en":"`subarray` vs `slice`","uk":"`subarray` проти `slice`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-collections', '{"mode":"single","code":"const a = new Uint8Array([1, 2, 3, 4]);\nconst view = a.subarray(1, 3);\nconst copy = a.slice(1, 3);\na[1] = 9;\nconsole.log(view[0], copy[0], view.buffer === a.buffer, copy.buffer === a.buffer);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`9 2 true false`","uk":"`9 2 true false`"}},{"id":"b","text":{"en":"`2 2 false false`","uk":"`2 2 false false`"}},{"id":"c","text":{"en":"`9 9 true true`","uk":"`9 9 true true`"}},{"id":"d","text":{"en":"`2 9 false true`","uk":"`2 9 false true`"}}]}'::jsonb, null::jsonb),
  ('col-weakmap-use', 'quiz', 3, 90, '{"en":"Caching data per DOM node","uk":"Кешування даних для вузлів DOM"}'::jsonb, '{"en":"A UI library caches measurements per element: `const cache = new Map(); function measure(el) { if (!cache.has(el)) cache.set(el, el.getBoundingClientRect()); return cache.get(el); }`. Elements are created and removed all the time. What''s the problem, and the best fix?","uk":"Бібліотека інтерфейсу кешує виміри для кожного елемента: `const cache = new Map(); function measure(el) { if (!cache.has(el)) cache.set(el, el.getBoundingClientRect()); return cache.get(el); }`. Елементи постійно створюються й видаляються. У чому проблема і яке найкраще виправлення?"}'::jsonb, 'js-collections', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The Map keeps removed elements alive forever; use a `WeakMap`, so entries go away when an element is no longer referenced","uk":"Map тримає видалені елементи живими назавжди; використайте `WeakMap`, щоб записи зникали, коли на елемент більше ніщо не посилається"}},{"id":"b","text":{"en":"DOM elements can''t be Map keys; use `el.id` as the key","uk":"Елементи DOM не можуть бути ключами Map; використайте ключем `el.id`"}},{"id":"c","text":{"en":"Nothing is wrong: the browser removes Map entries when elements are removed","uk":"Усе гаразд: браузер видаляє записи Map, коли видаляються елементи"}},{"id":"d","text":{"en":"Use a `WeakSet`, because it''s faster than a Map","uk":"Використайте `WeakSet`, бо він швидший за Map"}}]}'::jsonb, null::jsonb),
  ('col-memoize-any-args', 'practice', 4, 1320, '{"en":"Memoize with any arguments","uk":"Мемоїзація з будь-якими аргументами"}'::jsonb, '{"en":"The starter `memoize` in `src/memoize.ts` keys its cache with `JSON.stringify(args)`, which treats `NaN` and `null` as the same, compares objects by value instead of identity, and can''t tell functions apart. Rewrite it so that:\n\n- It caches by **all** arguments, any number of them.\n- Primitives use Map semantics (`NaN` finds `NaN`; `1` and `\"1\"` differ).\n- Objects and functions are compared **by reference**, and the cache doesn''t keep them alive (they should be collectable once the caller drops them).\n- `f(1)` and `f(1, undefined)` are different calls.\n- `undefined` results are cached, and thrown errors aren''t.\n- `memoized.clear()` empties the cache.\n\nHint: a trie with one node per argument position, where each node holds a `Map` for primitives and a `WeakMap` for objects.","uk":"Початкова `memoize` у `src/memoize.ts` будує ключ кешу через `JSON.stringify(args)`, що вважає `NaN` і `null` однаковими, порівнює об''єкти за значенням замість ідентичності й не розрізняє функції. Перепишіть її так, щоб:\n\n- Вона кешувала за **всіма** аргументами, скільки б їх не було.\n- Примітиви мали семантику Map (`NaN` знаходить `NaN`; `1` і `\"1\"` різні).\n- Об''єкти й функції порівнювалися **за посиланням**, а кеш не тримав їх живими (їх мають могти прибрати, щойно той, хто викликає, їх відпустить).\n- `f(1)` і `f(1, undefined)` були різними викликами.\n- Результати `undefined` кешувалися, а кинуті помилки ні.\n- `memoized.clear()` очищувала кеш.\n\nПідказка: префіксне дерево (trie) з вузлом на кожну позицію аргументу, де кожен вузол містить `Map` для примітивів і `WeakMap` для об''єктів."}'::jsonb, 'js-collections', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/memoize.ts":"/**\n * Caches fn''s results by its arguments: any number of them, of any type.\n * memoized.clear() empties the cache.\n */\nexport function memoize<A extends unknown[], R>(fn: (...args: A) => R): ((...args: A) => R) & { clear(): void } {\n  // TODO: JSON.stringify confuses NaN with null, compares objects by value and can''t hold functions\n  let cache = new Map<string, R>();\n  const memoized = (...args: A): R => {\n    const key = JSON.stringify(args);\n    if (cache.has(key)) return cache.get(key)!;\n    const result = fn(...args);\n    cache.set(key, result);\n    return result;\n  };\n  return Object.assign(memoized, { clear: () => (cache = new Map()) });\n}\n","/index.ts":"import \"./styles.css\";\nimport { memoize } from \"./src/memoize\";\n\nlet calls = 0;\nconst describe = memoize((value: unknown, options?: object) => {\n  calls++;\n  return String(value) + (options ? \" with options\" : \"\");\n});\nconst opts = { verbose: true };\nconst results = [describe(NaN), describe(NaN), describe(null), describe(1, opts), describe(1, opts), describe(1, { verbose: true })];\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Memoize</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = results.join(\"\\n\") + \"\\n\\ncalls: \" + calls + \" (expected 4)\";\n"},"visibleFiles":["/src/memoize.ts","/index.ts"],"activeFile":"/src/memoize.ts","tests":"import { describe, it, expect, fn } from \"./test-kit\";\nimport { memoize } from \"../src/memoize\";\n\ndescribe(\"memoize\", () => {\n  it(\"caches by all arguments\", () => {\n    const add = fn((a, b) => a + b);\n    const m = memoize(add);\n    expect(m(1, 2)).toBe(3);\n    expect(m(1, 2)).toBe(3);\n    expect(m(2, 1)).toBe(3);\n    expect(add).toHaveBeenCalledTimes(2);\n  });\n  it(\"tells NaN, null and undefined apart, and finds NaN again\", () => {\n    const spy = fn((x) => String(x));\n    const m = memoize(spy);\n    expect(m(NaN)).toBe(\"NaN\");\n    expect(m(null)).toBe(\"null\");\n    expect(m(undefined)).toBe(\"undefined\");\n    m(NaN);\n    expect(spy).toHaveBeenCalledTimes(3);\n  });\n  it(\"tells strings and numbers apart\", () => {\n    const spy = fn((x) => typeof x);\n    const m = memoize(spy);\n    expect(m(1)).toBe(\"number\");\n    expect(m(\"1\")).toBe(\"string\");\n  });\n  it(\"compares objects and functions by reference\", () => {\n    const spy = fn((o) => Object.keys(o).length);\n    const m = memoize(spy);\n    const a = { x: 1 };\n    m(a);\n    m(a);\n    m({ x: 1 });\n    const cb = () => {};\n    m(cb);\n    m(cb);\n    expect(spy).toHaveBeenCalledTimes(3);\n  });\n  it(\"treats different argument counts as different calls\", () => {\n    const spy = fn((...args) => args.length);\n    const m = memoize(spy);\n    expect(m(1)).toBe(1);\n    expect(m(1, undefined)).toBe(2);\n    expect(m()).toBe(0);\n    expect(spy).toHaveBeenCalledTimes(3);\n  });\n  it(\"caches undefined results\", () => {\n    const spy = fn(() => undefined);\n    const m = memoize(spy);\n    m(\"a\");\n    m(\"a\");\n    expect(spy).toHaveBeenCalledTimes(1);\n  });\n  it(\"doesn''t cache errors\", () => {\n    let fail = true;\n    const m = memoize((x) => {\n      if (fail) throw new Error(\"boom\");\n      return x * 2;\n    });\n    expect(() => m(2)).toThrow(\"boom\");\n    fail = false;\n    expect(m(2)).toBe(4);\n  });\n  it(\"clear() empties the cache\", () => {\n    const spy = fn((x) => x);\n    const m = memoize(spy);\n    m(1);\n    m.clear();\n    m(1);\n    expect(spy).toHaveBeenCalledTimes(2);\n  });\n});\n","testCount":8}'::jsonb),
  ('col-tag-index', 'practice', 3, 1200, '{"en":"A tag index with Map and Set","uk":"Індекс тегів на Map і Set"}'::jsonb, '{"en":"Implement `TagIndex` in `src/tags.ts`, an inverted index from tags to item ids:\n\n- `add(id, tags)` adds tags to an item; adding the same item again merges its tags without duplicates.\n- `untag(id, tag)` and `remove(id)`: tags that no item uses anymore disappear.\n- `query({ all, any, none })` returns the ids that have **all** of `all`, **at least one** of `any` (when it''s non-empty) and **none** of `none`, in the order items were first added. An empty query returns every item.\n- `tags()` returns `[tag, count]` pairs, most used first, ties sorted by name.\n\nQueries must stay fast with tens of thousands of items: keep two maps of sets (`id → tags` and `tag → ids`) instead of scanning arrays.","uk":"Реалізуйте `TagIndex` у `src/tags.ts`, інвертований індекс від тегів до id елементів:\n\n- `add(id, tags)` додає теги елементу; повторне додавання того самого елемента зливає його теги без дублікатів.\n- `untag(id, tag)` і `remove(id)`: теги, якими більше не користується жоден елемент, зникають.\n- `query({ all, any, none })` повертає id, що мають **усі** теги з `all`, **хоча б один** з `any` (коли він непорожній) і **жодного** з `none`, у порядку першого додавання елементів. Порожній запит повертає всі елементи.\n- `tags()` повертає пари `[tag, count]`, найуживаніші першими, а за рівності впорядковані за назвою.\n\nЗапити мають лишатися швидкими з десятками тисяч елементів: тримайте дві мапи множин (`id → tags` і `tag → ids`) замість сканування масивів."}'::jsonb, 'js-collections', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/tags.ts":"export type Query = { all?: string[]; any?: string[]; none?: string[] };\n\n/** An inverted index from tags to item ids. */\nexport class TagIndex {\n  // TODO: an array scan is O(items × tags) per query, and most methods are missing\n  private items: { id: string; tags: string[] }[] = [];\n\n  add(id: string, tags: Iterable<string>): void {\n    this.items.push({ id, tags: [...tags] });\n  }\n  untag(id: string, tag: string): void {}\n  remove(id: string): void {}\n\n  /** Ids (in the order they were first added) that match the query. */\n  query({ all = [] }: Query = {}): string[] {\n    return this.items.filter((item) => all.every((t) => item.tags.includes(t))).map((item) => item.id);\n  }\n\n  /** [tag, count] pairs, most used first, ties by name. */\n  tags(): [string, number][] {\n    return [];\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { TagIndex } from \"./src/tags\";\n\nconst index = new TagIndex();\nindex.add(\"post-1\", [\"js\", \"react\"]);\nindex.add(\"post-2\", [\"js\", \"node\"]);\nindex.add(\"post-3\", [\"css\"]);\nconst lines = [\n  \"js: \" + index.query({ all: [\"js\"] }).join(\", \"),\n  \"js but not react: \" + index.query({ all: [\"js\"], none: [\"react\"] }).join(\", \"),\n  \"react or css: \" + index.query({ any: [\"react\", \"css\"] }).join(\", \"),\n  \"tags: \" + JSON.stringify(index.tags()),\n];\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Tag index</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/tags.ts","/index.ts"],"activeFile":"/src/tags.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { TagIndex } from \"../src/tags\";\n\nfunction sample() {\n  const index = new TagIndex();\n  index.add(\"a\", [\"js\", \"react\", \"frontend\"]);\n  index.add(\"b\", [\"js\", \"node\", \"backend\"]);\n  index.add(\"c\", [\"css\", \"frontend\"]);\n  index.add(\"d\", [\"js\", \"frontend\", \"vue\"]);\n  return index;\n}\n\ndescribe(\"TagIndex\", () => {\n  it(\"finds items with all of the tags, in insertion order\", () => {\n    expect(sample().query({ all: [\"js\", \"frontend\"] })).toEqual([\"a\", \"d\"]);\n  });\n  it(\"supports any and none\", () => {\n    const index = sample();\n    expect(index.query({ any: [\"react\", \"css\"] })).toEqual([\"a\", \"c\"]);\n    expect(index.query({ all: [\"js\"], none: [\"react\", \"vue\"] })).toEqual([\"b\"]);\n    expect(index.query({ none: [\"js\"] })).toEqual([\"c\"]);\n  });\n  it(\"returns everything for an empty query and nothing for unknown tags\", () => {\n    const index = sample();\n    expect(index.query()).toEqual([\"a\", \"b\", \"c\", \"d\"]);\n    expect(index.query({ all: [\"rust\"] })).toEqual([]);\n    expect(index.query({ any: [\"rust\"] })).toEqual([]);\n  });\n  it(\"merges tags when an item is added again, without duplicates\", () => {\n    const index = sample();\n    index.add(\"c\", [\"css\", \"tailwind\"]);\n    expect(index.query({ all: [\"tailwind\", \"frontend\"] })).toEqual([\"c\"]);\n    expect(index.tags().find(([t]) => t === \"css\")).toEqual([\"css\", 1]);\n  });\n  it(\"counts tags, most used first, ties by name\", () => {\n    expect(sample().tags()).toEqual([\n      [\"frontend\", 3],\n      [\"js\", 3],\n      [\"backend\", 1],\n      [\"css\", 1],\n      [\"node\", 1],\n      [\"react\", 1],\n      [\"vue\", 1],\n    ]);\n  });\n  it(\"untags and removes items, dropping tags nobody uses\", () => {\n    const index = sample();\n    index.untag(\"a\", \"react\");\n    expect(index.query({ any: [\"react\"] })).toEqual([]);\n    expect(index.tags().some(([t]) => t === \"react\")).toBe(false);\n    index.remove(\"b\");\n    expect(index.query({ all: [\"js\"] })).toEqual([\"a\", \"d\"]);\n    expect(index.tags().some(([t]) => t === \"node\")).toBe(false);\n    expect(index.query()).toEqual([\"a\", \"c\", \"d\"]);\n  });\n  it(\"handles many items quickly\", () => {\n    const index = new TagIndex();\n    for (let i = 0; i < 20000; i++) index.add(\"item-\" + i, [\"t\" + (i % 10), \"g\" + (i % 7)]);\n    const start = performance.now();\n    let found = 0;\n    for (let q = 0; q < 20; q++) found += index.query({ all: [\"t3\", \"g5\"] }).length;\n    expect(found).toBe(20 * 286);\n    expect(performance.now() - start).toBeLessThan(1500);\n  });\n});\n","testCount":7}'::jsonb),
  ('eng-jit-warmup', 'quiz', 1, 60, '{"en":"Why code gets faster as it runs","uk":"Чому код пришвидшується під час виконання"}'::jsonb, '{"en":"A function runs slowly the first few hundred times it''s called and much faster afterwards. What''s the most likely reason?","uk":"Функція працює повільно перші кілька сотень викликів, а потім значно швидше. Яка найімовірніша причина?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The engine first interprets it while collecting type feedback, then a JIT compiler turns the hot function into optimised machine code","uk":"Рушій спершу інтерпретує її, збираючи зворотний зв''язок про типи, а потім JIT-компілятор перетворює гарячу функцію на оптимізований машинний код"}},{"id":"b","text":{"en":"The browser caches its return values","uk":"Браузер кешує її результати"}},{"id":"c","text":{"en":"The garbage collector gets faster over time","uk":"Збирач сміття з часом пришвидшується"}},{"id":"d","text":{"en":"The CPU''s branch predictor learns the code, and the engine does nothing","uk":"Передбачувач розгалужень процесора вивчає код, а рушій нічого не робить"}}]}'::jsonb, null::jsonb),
  ('eng-deopt', 'quiz', 2, 75, '{"en":"Deoptimisation","uk":"Деоптимізація"}'::jsonb, '{"en":"`add(a, b)` has been called a million times with small integers and is optimised. Then it''s called once as `add(\"1\", \"2\")`. What happens?","uk":"`add(a, b)` викликали мільйон разів із малими цілими числами, і її оптимізовано. Потім її викликають один раз як `add(\"1\", \"2\")`. Що станеться?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The optimised code''s type assumption fails, so the engine deoptimises back to bytecode and returns the correct `\"12\"`; it may reoptimise later with more generic code","uk":"Припущення оптимізованого коду про типи не справджується, тож рушій деоптимізує функцію назад до байткоду й повертає правильне `\"12\"`; згодом він може переоптимізувати її з загальнішим кодом"}},{"id":"b","text":{"en":"It returns `3`, because the optimised code treats arguments as numbers","uk":"Вона повертає `3`, бо оптимізований код вважає аргументи числами"}},{"id":"c","text":{"en":"It throws a `TypeError`","uk":"Вона кидає `TypeError`"}},{"id":"d","text":{"en":"Nothing changes: optimised code handles every type equally fast","uk":"Нічого не змінюється: оптимізований код однаково швидко обробляє всі типи"}}]}'::jsonb, null::jsonb),
  ('eng-hidden-classes', 'quiz', 2, 75, '{"en":"Which objects share a shape?","uk":"Які об''єкти мають спільну форму?"}'::jsonb, '{"en":"In V8, which of these objects end up with the same hidden class?","uk":"Які з цих об''єктів у V8 отримають однаковий прихований клас?"}'::jsonb, 'js-engine-performance', '{"mode":"single","code":"const p1 = {};\np1.x = 1;\np1.y = 2;\n\nconst p2 = {};\np2.y = 2;\np2.x = 1;\n\nconst p3 = {};\np3.x = 5;\np3.y = 6;","codeLanguage":"js","options":[{"id":"a","text":{"en":"`p1` and `p3`","uk":"`p1` і `p3`"}},{"id":"b","text":{"en":"All three","uk":"Усі три"}},{"id":"c","text":{"en":"`p1` and `p2`","uk":"`p1` і `p2`"}},{"id":"d","text":{"en":"None of them","uk":"Жоден"}}]}'::jsonb, null::jsonb),
  ('eng-delete-property', 'quiz', 3, 90, '{"en":"`delete` in hot code","uk":"`delete` у гарячому коді"}'::jsonb, '{"en":"A reviewer suggests replacing `delete session.cache` with `session.cache = undefined` in a function that runs on every request. Why, and what''s the trade-off?","uk":"Рецензент пропонує замінити `delete session.cache` на `session.cache = undefined` у функції, що виконується на кожен запит. Чому, і який компроміс?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Deleting can push the object into a slow dictionary mode and changes its shape; assigning `undefined` keeps the shape, but the key still exists (`\"cache\" in session` is true, and it shows up in `Object.keys`)","uk":"Видалення може перевести об''єкт у повільний режим словника й змінює його форму; присвоєння `undefined` зберігає форму, але ключ лишається (`\"cache\" in session` дає true, і він з''являється в `Object.keys`)"}},{"id":"b","text":{"en":"`delete` is asynchronous, so the value can still be read for a while","uk":"`delete` асинхронний, тож значення ще деякий час можна прочитати"}},{"id":"c","text":{"en":"`delete` frees memory immediately, which pauses the program","uk":"`delete` негайно звільняє пам''ять, і це зупиняє програму"}},{"id":"d","text":{"en":"There''s no difference; both are compiled to the same code","uk":"Різниці немає; обидва компілюються в той самий код"}}]}'::jsonb, null::jsonb),
  ('eng-megamorphic', 'quiz', 3, 90, '{"en":"Mono-, poly- and megamorphic access","uk":"Моно-, полі- й мегаморфний доступ"}'::jsonb, '{"en":"`getId(item)` returns `item.id`. It''s called in a hot loop with objects built by 15 different factories, each adding properties in a different order. How does that affect the `item.id` access?","uk":"`getId(item)` повертає `item.id`. Її викликають у гарячому циклі з об''єктами від 15 різних фабрик, кожна з яких додає властивості в іншому порядку. Як це впливає на доступ `item.id`?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The inline cache sees too many shapes, becomes megamorphic and falls back to a slower generic lookup; giving the objects one consistent shape fixes it","uk":"Inline-кеш бачить забагато форм, стає мегаморфним і повертається до повільнішого загального пошуку; одна стала форма об''єктів це виправляє"}},{"id":"b","text":{"en":"Nothing: property access always costs the same","uk":"Нічого: доступ до властивості завжди коштує однаково"}},{"id":"c","text":{"en":"The engine throws after 4 shapes","uk":"Рушій кидає помилку після 4 форм"}},{"id":"d","text":{"en":"It gets faster, because the cache holds more shapes","uk":"Він пришвидшується, бо кеш тримає більше форм"}}]}'::jsonb, null::jsonb),
  ('eng-holey-arrays', 'quiz', 2, 75, '{"en":"Holey arrays","uk":"Діряві масиви"}'::jsonb, '{"en":"Which way of building an array of 1,000 numbers keeps the fastest element kind in V8?","uk":"Який спосіб побудувати масив із 1000 чисел зберігає у V8 найшвидший вид елементів?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Start with `[]` and `push` each number","uk":"Почати з `[]` і додавати кожне число через `push`"}},{"id":"b","text":{"en":"`const a = new Array(1000)` and then assign `a[i]` in a loop","uk":"`const a = new Array(1000)`, а потім присвоювати `a[i]` у циклі"}},{"id":"c","text":{"en":"`const a = []; a[999] = 0;` and then fill the rest","uk":"`const a = []; a[999] = 0;`, а потім заповнити решту"}},{"id":"d","text":{"en":"They''re all the same once the array is full","uk":"Усі однакові, щойно масив заповнено"}}]}'::jsonb, null::jsonb),
  ('eng-generational-gc', 'quiz', 2, 75, '{"en":"Why short-lived objects are cheap","uk":"Чому короткоживучі об''єкти дешеві"}'::jsonb, '{"en":"Why is creating lots of small, short-lived objects (for example in `map` callbacks) usually cheap in V8?","uk":"Чому створення багатьох малих короткоживучих об''єктів (наприклад, у колбеках `map`) у V8 зазвичай дешеве?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Most objects die young, and the young-generation collector only copies surviving objects, so its cost depends on what survives, not on how much garbage there is","uk":"Більшість об''єктів помирає молодими, а збирач молодого покоління копіює лише ті, що вижили, тож його вартість залежить від того, що вижило, а не від обсягу сміття"}},{"id":"b","text":{"en":"V8 reuses the same object every time, so nothing is allocated","uk":"V8 щоразу повторно використовує той самий об''єкт, тож нічого не виділяється"}},{"id":"c","text":{"en":"Garbage is never collected while the page is open","uk":"Сміття не прибирається, доки сторінка відкрита"}},{"id":"d","text":{"en":"Short-lived objects are stored on the CPU stack","uk":"Короткоживучі об''єкти зберігаються в стеку процесора"}}]}'::jsonb, null::jsonb),
  ('eng-listener-leak', 'quiz', 2, 75, '{"en":"A leaking component","uk":"Компонент із витоком"}'::jsonb, '{"en":"A widget calls `window.addEventListener(\"resize\", this.onResize)` and `setInterval(this.poll, 1000)` when it mounts, and nothing when it unmounts. Users open and close it many times. What happens?","uk":"Віджет викликає `window.addEventListener(\"resize\", this.onResize)` і `setInterval(this.poll, 1000)` під час монтування й нічого під час демонтування. Користувачі відкривають і закривають його багато разів. Що станеться?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Every closed widget stays in memory, kept alive by `window`''s listener list and the timer, and keeps doing work; remove both on unmount (for example with an `AbortController` and `clearInterval`)","uk":"Кожен закритий віджет лишається в пам''яті, утримуваний списком слухачів `window` і таймером, і продовжує працювати; видаляйте обидва під час демонтування (наприклад, через `AbortController` і `clearInterval`)"}},{"id":"b","text":{"en":"Nothing: the browser removes listeners when the element leaves the DOM","uk":"Нічого: браузер видаляє слухачів, коли елемент залишає DOM"}},{"id":"c","text":{"en":"The garbage collector collects the widget, and the interval stops automatically","uk":"Збирач сміття прибирає віджет, а інтервал зупиняється автоматично"}},{"id":"d","text":{"en":"Only the interval leaks; listeners on `window` are weak","uk":"Витікає лише інтервал; слухачі на `window` слабкі"}}]}'::jsonb, null::jsonb),
  ('eng-shared-closure-context', 'quiz', 5, 150, '{"en":"A closure that retains more than it uses","uk":"Замикання, що утримує більше, ніж використовує"}'::jsonb, '{"en":"`makeHandler()` is called once per row and the returned functions are stored. In V8, does each stored handler keep its `big` array alive?","uk":"`makeHandler()` викликають для кожного рядка, а повернені функції зберігають. Чи тримає у V8 кожен збережений обробник свій масив `big` живим?"}'::jsonb, 'js-engine-performance', '{"mode":"single","code":"function makeHandler(row) {\n  const big = new Array(1_000_000).fill(row.id);\n  const debug = () => console.log(big.length);\n  return () => row.id;\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"Yes: closures created in the same scope share one context object, and `big` is in it because `debug` uses it","uk":"Так: замикання, створені в одній області видимості, мають спільний об''єкт контексту, і `big` у ньому, бо його використовує `debug`"}},{"id":"b","text":{"en":"No: the returned function doesn''t mention `big`, so it can''t retain it","uk":"Ні: повернена функція не згадує `big`, тож не може його утримувати"}},{"id":"c","text":{"en":"No: `debug` is never called, so the engine deletes it and `big`","uk":"Ні: `debug` ніколи не викликається, тож рушій видаляє його й `big`"}},{"id":"d","text":{"en":"Only in strict mode","uk":"Лише в строгому режимі"}}]}'::jsonb, null::jsonb),
  ('eng-dead-code-benchmark', 'quiz', 3, 90, '{"en":"A suspiciously fast benchmark","uk":"Підозріло швидкий бенчмарк"}'::jsonb, '{"en":"This benchmark reports that 10 million square roots take about 5 ms, roughly what an empty loop takes. What''s the most likely explanation?","uk":"Цей бенчмарк показує, що 10 мільйонів квадратних коренів займають близько 5 мс, приблизно стільки ж, скільки порожній цикл. Яке найімовірніше пояснення?"}'::jsonb, 'js-engine-performance', '{"mode":"single","code":"const start = performance.now();\nfor (let i = 0; i < 10_000_000; i++) {\n  Math.sqrt(i);\n}\nconsole.log(performance.now() - start, \"ms\");","codeLanguage":"js","options":[{"id":"a","text":{"en":"The result is never used, so the optimiser can remove the `Math.sqrt` work as dead code; use the result (sum it and print or return it)","uk":"Результат ніколи не використовується, тож оптимізатор може видалити роботу `Math.sqrt` як мертвий код; використайте результат (підсумуйте й виведіть чи поверніть)"}},{"id":"b","text":{"en":"`Math.sqrt` is run on the GPU","uk":"`Math.sqrt` виконується на GPU"}},{"id":"c","text":{"en":"`performance.now()` stops while loops run","uk":"`performance.now()` зупиняється, поки виконуються цикли"}},{"id":"d","text":{"en":"Modern CPUs really compute 2 billion square roots per second, so the number is right","uk":"Сучасні процесори справді обчислюють 2 мільярди квадратних коренів за секунду, тож число правильне"}}]}'::jsonb, null::jsonb),
  ('eng-benchmark-order', 'quiz', 3, 90, '{"en":"Order effects in benchmarks","uk":"Вплив порядку в бенчмарках"}'::jsonb, '{"en":"A script times implementation A once, then implementation B once, in the same process. B is 40% faster. Swapping the order makes A 40% faster. What should you change?","uk":"Скрипт один раз вимірює реалізацію A, потім один раз реалізацію B в тому самому процесі. B на 40% швидша. Якщо поміняти порядок, на 40% швидшою стає A. Що варто змінити?"}'::jsonb, 'js-engine-performance', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Warm both up first, run each many times (interleaved or in separate processes), and compare medians with a margin of error","uk":"Спершу розігріти обидві, виконати кожну багато разів (почергово чи в окремих процесах) і порівнювати медіани з похибкою"}},{"id":"b","text":{"en":"Always run the slower one first","uk":"Завжди запускати повільнішу першою"}},{"id":"c","text":{"en":"Use `Date.now()` instead of `performance.now()`","uk":"Використовувати `Date.now()` замість `performance.now()`"}},{"id":"d","text":{"en":"Nothing: B is faster because it ran second, and that''s what users will see","uk":"Нічого: B швидша, бо виконувалася другою, і саме це побачать користувачі"}}]}'::jsonb, null::jsonb),
  ('eng-tail-calls', 'quiz', 3, 90, '{"en":"Tail calls in practice","uk":"Хвостові виклики на практиці"}'::jsonb, '{"en":"This runs in Node.js (V8). What does it print?","uk":"Код виконується в Node.js (V8). Що він виведе?"}'::jsonb, 'js-engine-performance', '{"mode":"single","code":"function sum(n, acc = 0) {\n  return n === 0 ? acc : sum(n - 1, acc + n);\n}\ntry {\n  console.log(sum(1_000_000));\n} catch (e) {\n  console.log(e.constructor.name);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`RangeError`","uk":"`RangeError`"}},{"id":"b","text":{"en":"`500000500000`","uk":"`500000500000`"}},{"id":"c","text":{"en":"`Infinity`","uk":"`Infinity`"}},{"id":"d","text":{"en":"`TypeError`","uk":"`TypeError`"}}]}'::jsonb, null::jsonb),
  ('eng-bench-stats', 'practice', 3, 1200, '{"en":"An honest micro-benchmark harness","uk":"Чесний інструмент для мікробенчмарків"}'::jsonb, '{"en":"Build the core of a benchmarking tool in `src/bench.ts`:\n\n- `summarize(samples)` returns `n`, `mean`, `median` (the average of the middle two for an even count), `min`, `max`, `stdDev` (sample, divided by `n − 1`; `0` for one sample), `p95` (nearest rank: the `⌈0.95·n⌉`-th smallest), `moe` (`1.96 × stdDev / √n`) and `rme` (`moe` as a percentage of the mean). It throws a `RangeError` for no samples and doesn''t mutate its input.\n- `compare(a, b)` returns `\"faster\"` or `\"slower\"` only when the 95% intervals (`mean ± moe`) of the two time samples don''t overlap, and `\"same\"` otherwise.\n- `measure(fn, { warmup, runs, batch, now })` calls `fn` `warmup` times without measuring, then for each run times `batch` calls and records the **per-call** time. Every result goes into `blackhole.value`, so the work can''t be optimised away. `now` defaults to `performance.now()` and is injectable for tests.","uk":"Побудуйте основу інструмента для бенчмарків у `src/bench.ts`:\n\n- `summarize(samples)` повертає `n`, `mean`, `median` (середнє двох середніх значень для парної кількості), `min`, `max`, `stdDev` (вибіркове, ділене на `n − 1`; `0` для одного виміру), `p95` (найближчий ранг: `⌈0.95·n⌉`-те найменше), `moe` (`1.96 × stdDev / √n`) і `rme` (`moe` у відсотках від середнього). Вона кидає `RangeError`, коли вимірів немає, і не змінює вхідні дані.\n- `compare(a, b)` повертає `\"faster\"` чи `\"slower\"`, лише коли 95% інтервали (`mean ± moe`) двох вибірок часу не перетинаються, а інакше `\"same\"`.\n- `measure(fn, { warmup, runs, batch, now })` викликає `fn` `warmup` разів без вимірювання, а потім для кожного запуску вимірює `batch` викликів і записує час **на один виклик**. Кожен результат потрапляє в `blackhole.value`, тож роботу не можна прибрати оптимізацією. `now` за замовчуванням дорівнює `performance.now()`, і його можна підмінити в тестах."}'::jsonb, 'js-engine-performance', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/bench.ts":"export type Summary = {\n  n: number;\n  mean: number;\n  median: number;\n  min: number;\n  max: number;\n  /** Sample standard deviation (divide by n - 1); 0 when n === 1. */\n  stdDev: number;\n  /** Nearest-rank 95th percentile. */\n  p95: number;\n  /** 95% margin of error of the mean: 1.96 × stdDev / √n. */\n  moe: number;\n  /** Relative margin of error, in percent of the mean. */\n  rme: number;\n};\n\nexport function summarize(samples: number[]): Summary {\n  // TODO: only the mean is computed\n  const mean = samples.reduce((a, b) => a + b, 0) / samples.length;\n  return { n: samples.length, mean, median: mean, min: 0, max: 0, stdDev: 0, p95: 0, moe: 0, rme: 0 };\n}\n\n/** \"faster\" if a''s times are reliably lower than b''s, \"slower\" if reliably higher, else \"same\". */\nexport function compare(a: number[], b: number[]): \"faster\" | \"slower\" | \"same\" {\n  // TODO: a raw comparison of means ignores noise\n  return summarize(a).mean < summarize(b).mean ? \"faster\" : \"slower\";\n}\n\n/** Results of measured calls are stored here so the engine can''t optimise the work away. */\nexport const blackhole: { value: unknown } = { value: undefined };\n\nexport type MeasureOptions = { warmup?: number; runs?: number; batch?: number; now?: () => number };\n\n/** Returns one sample per run: the average time of one call within a batch. */\nexport function measure(fn: () => unknown, { warmup = 5, runs = 20, batch = 1, now = () => performance.now() }: MeasureOptions = {}): number[] {\n  // TODO: no warm-up, no batching, results are thrown away\n  const samples: number[] = [];\n  for (let r = 0; r < runs; r++) {\n    const start = now();\n    fn();\n    samples.push(now() - start);\n  }\n  return samples;\n}\n","/index.ts":"import \"./styles.css\";\nimport { compare, measure, summarize } from \"./src/bench\";\n\nconst data = Array.from({ length: 2000 }, (_, i) => i);\nconst lines: string[] = [];\ntry {\n  const forLoop = measure(() => {\n    let s = 0;\n    for (let i = 0; i < data.length; i++) s += data[i];\n    return s;\n  }, { batch: 50 });\n  const reduce = measure(() => data.reduce((a, b) => a + b, 0), { batch: 50 });\n  const f = summarize(forLoop);\n  const r = summarize(reduce);\n  lines.push(\"for:    \" + f.median.toFixed(4) + \" ms ±\" + f.rme.toFixed(1) + \"%\");\n  lines.push(\"reduce: \" + r.median.toFixed(4) + \" ms ±\" + r.rme.toFixed(1) + \"%\");\n  lines.push(\"for is \" + compare(forLoop, reduce) + \" than reduce\");\n} catch (e) {\n  lines.push(\"error: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Benchmark</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/bench.ts","/index.ts"],"activeFile":"/src/bench.ts","tests":"import { describe, it, expect, fn } from \"./test-kit\";\nimport { blackhole, compare, measure, summarize } from \"../src/bench\";\n\ndescribe(\"summarize\", () => {\n  it(\"computes the basic statistics\", () => {\n    const s = summarize([10, 12, 11, 13, 9]);\n    expect(s.n).toBe(5);\n    expect(s.mean).toBe(11);\n    expect(s.median).toBe(11);\n    expect(s.min).toBe(9);\n    expect(s.max).toBe(13);\n    expect(s.stdDev).toBeCloseTo(1.5811, 3);\n    expect(s.p95).toBe(13);\n    expect(s.moe).toBeCloseTo(1.3859, 3);\n    expect(s.rme).toBeCloseTo(12.599, 2);\n  });\n  it(\"averages the middle values for an even count and doesn''t mutate the input\", () => {\n    const samples = [4, 1, 3, 2];\n    expect(summarize(samples).median).toBe(2.5);\n    expect(samples).toEqual([4, 1, 3, 2]);\n  });\n  it(\"handles a single sample and rejects none\", () => {\n    const s = summarize([5]);\n    expect(s.stdDev).toBe(0);\n    expect(s.moe).toBe(0);\n    expect(s.p95).toBe(5);\n    expect(() => summarize([])).toThrow(RangeError);\n  });\n  it(\"uses the nearest-rank 95th percentile\", () => {\n    const samples = Array.from({ length: 40 }, (_, i) => i + 1);\n    expect(summarize(samples).p95).toBe(38);\n  });\n});\n\ndescribe(\"compare\", () => {\n  const fast = [1, 1.1, 0.9, 1, 1];\n  const slow = [2, 2.1, 1.9, 2, 2];\n  const noisy = [0.5, 3, 1, 2.5, 1.5];\n  it(\"reports a difference only when the intervals don''t overlap\", () => {\n    expect(compare(fast, slow)).toBe(\"faster\");\n    expect(compare(slow, fast)).toBe(\"slower\");\n    expect(compare(noisy, slow)).toBe(\"same\");\n  });\n});\n\ndescribe(\"measure\", () => {\n  it(\"warms up, then records the per-call time of each batch\", () => {\n    let t = 0;\n    const work = fn(() => {\n      t += 2;\n      return 42;\n    });\n    const samples = measure(work, { warmup: 3, runs: 4, batch: 5, now: () => t });\n    expect(samples).toEqual([2, 2, 2, 2]);\n    expect(work).toHaveBeenCalledTimes(3 + 4 * 5);\n  });\n  it(\"keeps results so the work can''t be optimised away\", () => {\n    measure(() => \"result\", { warmup: 0, runs: 1 });\n    expect(blackhole.value).toBe(\"result\");\n  });\n  it(\"defaults to real time\", () => {\n    const samples = measure(() => Math.sqrt(2), { runs: 3 });\n    expect(samples.length).toBe(3);\n    expect(samples.every((s) => s >= 0)).toBe(true);\n  });\n});\n","testCount":8}'::jsonb),
  ('eng-disposer', 'practice', 3, 1080, '{"en":"Leak-proof cleanup with a disposer","uk":"Очищення без витоків через disposer"}'::jsonb, '{"en":"Most front-end leaks come from listeners, timers and subscriptions that outlive their component. Finish `Disposer` in `src/disposer.ts`, which collects cleanups and runs them on `dispose()`:\n\n- `add(cleanup)` registers a cleanup and returns it. `listen(target, type, handler)` and `interval(fn, ms)` set things up **and** register their removal.\n- `dispose()` runs cleanups in **reverse order** (last in, first out), each exactly once; calling it again does nothing, and `disposed` becomes `true`.\n- If a cleanup throws, the rest still run, and afterwards `dispose()` throws an `AggregateError` with all the errors.\n- Adding a cleanup **after** disposal runs it immediately (late async setup must not leak).\n- `child()` returns a nested disposer that''s disposed along with its parent; disposing the child early is allowed, and its cleanups never run twice.","uk":"Більшість витоків на фронтенді виникає через слухачів, таймери й підписки, що переживають свій компонент. Завершіть `Disposer` у `src/disposer.ts`, що збирає очищення й виконує їх у `dispose()`:\n\n- `add(cleanup)` реєструє очищення й повертає його. `listen(target, type, handler)` і `interval(fn, ms)` налаштовують ресурс **і** реєструють його видалення.\n- `dispose()` виконує очищення у **зворотному порядку** (останнім прийшов, першим вийшов), кожне рівно один раз; повторний виклик нічого не робить, а `disposed` стає `true`.\n- Якщо очищення кидає помилку, решта все одно виконується, а потім `dispose()` кидає `AggregateError` з усіма помилками.\n- Додавання очищення **після** звільнення виконує його одразу (пізнє асинхронне налаштування не повинно спричиняти витік).\n- `child()` повертає вкладений disposer, що звільняється разом із батьком; звільнити дочірній раніше можна, і його очищення ніколи не виконуються двічі."}'::jsonb, 'js-engine-performance', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/disposer.ts":"/**\n * Collects cleanups (listeners, timers, subscriptions) and runs them all on dispose(),\n * so components and services don''t leak.\n */\nexport class Disposer {\n  private cleanups: Array<() => void> = [];\n\n  /** Registers a cleanup and returns it. */\n  add(cleanup: () => void): () => void {\n    this.cleanups.push(cleanup);\n    return cleanup;\n  }\n\n  listen(target: EventTarget, type: string, handler: (event: Event) => void): void {\n    // TODO: this listener is never removed\n    target.addEventListener(type, handler);\n  }\n\n  interval(callback: () => void, ms: number): void {\n    // TODO: this interval is never cleared\n    setInterval(callback, ms);\n  }\n\n  /** A nested disposer that is disposed together with this one. */\n  child(): Disposer {\n    // TODO\n    return new Disposer();\n  }\n\n  get disposed(): boolean {\n    return false; // TODO\n  }\n\n  dispose(): void {\n    // TODO: reverse order, run once, keep going after errors\n    for (const cleanup of this.cleanups) cleanup();\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { Disposer } from \"./src/disposer\";\n\ndocument.getElementById(\"app\")!.innerHTML =\n  ''<h1>Disposer</h1><button id=\"toggle\">Stop</button><p>ticks: <span id=\"ticks\">0</span>, clicks: <span id=\"clicks\">0</span></p>'';\nlet ticks = 0;\nlet clicks = 0;\nconst d = new Disposer();\n// Practise what we preach: once the demo is no longer on the page, clean everything up.\nconst show = (id: string, value: number) => {\n  const el = document.getElementById(id);\n  if (el) el.textContent = String(value);\n  else d.dispose();\n};\nd.interval(() => show(\"ticks\", ++ticks), 500);\nd.listen(document, \"click\", () => show(\"clicks\", ++clicks));\ndocument.getElementById(\"toggle\")!.addEventListener(\"click\", () => d.dispose());\n"},"visibleFiles":["/src/disposer.ts","/index.ts"],"activeFile":"/src/disposer.ts","tests":"import { describe, it, expect, fn } from \"./test-kit\";\nimport { Disposer } from \"../src/disposer\";\n\nconst sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\ndescribe(\"Disposer\", () => {\n  it(\"removes event listeners on dispose\", () => {\n    const target = new EventTarget();\n    const handler = fn();\n    const d = new Disposer();\n    d.listen(target, \"ping\", handler);\n    target.dispatchEvent(new Event(\"ping\"));\n    d.dispose();\n    target.dispatchEvent(new Event(\"ping\"));\n    expect(handler).toHaveBeenCalledTimes(1);\n  });\n  it(\"clears intervals on dispose\", async () => {\n    const tick = fn();\n    const d = new Disposer();\n    d.interval(tick, 5);\n    await sleep(40);\n    d.dispose();\n    const count = tick.mock.calls.length;\n    expect(count).toBeGreaterThan(1);\n    await sleep(40);\n    expect(tick.mock.calls.length).toBe(count);\n  });\n  it(\"runs cleanups in reverse order, exactly once\", () => {\n    const log = [];\n    const d = new Disposer();\n    d.add(() => log.push(\"a\"));\n    d.add(() => log.push(\"b\"));\n    d.add(() => log.push(\"c\"));\n    d.dispose();\n    d.dispose();\n    expect(log).toEqual([\"c\", \"b\", \"a\"]);\n    expect(d.disposed).toBe(true);\n  });\n  it(\"keeps going when a cleanup throws, then reports every error\", () => {\n    const log = [];\n    const d = new Disposer();\n    d.add(() => log.push(\"a\"));\n    d.add(() => {\n      throw new Error(\"bad cleanup\");\n    });\n    d.add(() => log.push(\"c\"));\n    let error;\n    try {\n      d.dispose();\n    } catch (e) {\n      error = e;\n    }\n    expect(log).toEqual([\"c\", \"a\"]);\n    expect(error).toBeInstanceOf(AggregateError);\n    expect(error.errors.map((e) => e.message)).toEqual([\"bad cleanup\"]);\n  });\n  it(\"cleans up immediately when something is added after dispose\", () => {\n    const d = new Disposer();\n    d.dispose();\n    const late = fn();\n    d.add(late);\n    expect(late).toHaveBeenCalledTimes(1);\n  });\n  it(\"disposes children with their parent, and lets them go early\", () => {\n    const parent = new Disposer();\n    const a = parent.child();\n    const b = parent.child();\n    const cleanA = fn();\n    const cleanB = fn();\n    a.add(cleanA);\n    b.add(cleanB);\n    b.dispose();\n    expect(cleanB).toHaveBeenCalledTimes(1);\n    parent.dispose();\n    expect(cleanA).toHaveBeenCalledTimes(1);\n    expect(cleanB).toHaveBeenCalledTimes(1);\n    expect(a.disposed).toBe(true);\n  });\n});\n","testCount":6}'::jsonb),
  ('mp-symbol-unique', 'quiz', 1, 45, '{"en":"Symbol identity","uk":"Ідентичність символів"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"console.log(Symbol(\"id\") === Symbol(\"id\"), Symbol.for(\"id\") === Symbol.for(\"id\"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`false true`","uk":"`false true`"}},{"id":"b","text":{"en":"`true true`","uk":"`true true`"}},{"id":"c","text":{"en":"`false false`","uk":"`false false`"}},{"id":"d","text":{"en":"`true false`","uk":"`true false`"}}]}'::jsonb, null::jsonb),
  ('mp-symbol-keys-hidden', 'quiz', 2, 90, '{"en":"Symbol-keyed properties","uk":"Властивості з ключами-символами"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const meta = Symbol(\"meta\");\nconst obj = { a: 1, [meta]: 2 };\nconsole.log(JSON.stringify(obj), Object.keys(obj), Reflect.ownKeys(obj).length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`{\"a\":1} [ ''a'' ] 2`","uk":"`{\"a\":1} [ ''a'' ] 2`"}},{"id":"b","text":{"en":"`{\"a\":1,\"meta\":2} [ ''a'', ''meta'' ] 2`","uk":"`{\"a\":1,\"meta\":2} [ ''a'', ''meta'' ] 2`"}},{"id":"c","text":{"en":"`{\"a\":1} [ ''a'' ] 1`","uk":"`{\"a\":1} [ ''a'' ] 1`"}},{"id":"d","text":{"en":"A `TypeError`: symbols can''t be keys","uk":"`TypeError`: символи не можуть бути ключами"}}]}'::jsonb, null::jsonb),
  ('mp-freeze-shallow', 'quiz', 2, 90, '{"en":"How deep is `freeze`?","uk":"Наскільки глибокий `freeze`?"}'::jsonb, '{"en":"This runs as an ES module. What does it print?","uk":"Цей код виконується як ES-модуль. Що він виведе?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const cfg = Object.freeze({ api: { url: \"a\" }, retries: 3 });\ncfg.api.url = \"b\";\nlet error = \"none\";\ntry {\n  cfg.retries = 5;\n} catch (e) {\n  error = e.constructor.name;\n}\nconsole.log(cfg.api.url, cfg.retries, error);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`b 3 TypeError`","uk":"`b 3 TypeError`"}},{"id":"b","text":{"en":"`a 3 TypeError`","uk":"`a 3 TypeError`"}},{"id":"c","text":{"en":"`b 5 none`","uk":"`b 5 none`"}},{"id":"d","text":{"en":"`a 3 none`","uk":"`a 3 none`"}}]}'::jsonb, null::jsonb),
  ('mp-define-property-defaults', 'quiz', 3, 90, '{"en":"`defineProperty` defaults","uk":"Значення за замовчуванням у `defineProperty`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const o = {};\nObject.defineProperty(o, \"hidden\", { value: 42 });\nconsole.log(Object.keys(o), JSON.stringify(o), o.hidden, Object.getOwnPropertyDescriptor(o, \"hidden\").writable);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[] {} 42 false`","uk":"`[] {} 42 false`"}},{"id":"b","text":{"en":"`[ ''hidden'' ] {\"hidden\":42} 42 true`","uk":"`[ ''hidden'' ] {\"hidden\":42} 42 true`"}},{"id":"c","text":{"en":"`[] {} undefined false`","uk":"`[] {} undefined false`"}},{"id":"d","text":{"en":"`[ ''hidden'' ] {} 42 false`","uk":"`[ ''hidden'' ] {} 42 false`"}}]}'::jsonb, null::jsonb),
  ('mp-getter-setter', 'quiz', 3, 90, '{"en":"Getters and setters","uk":"Гетери й сетери"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const temp = {\n  _c: 0,\n  get f() { return (this._c * 9) / 5 + 32; },\n  set f(v) { this._c = ((v - 32) * 5) / 9; },\n};\ntemp.f = 212;\nconsole.log(temp._c, temp.f, Object.keys(temp));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`100 212 [ ''_c'', ''f'' ]`","uk":"`100 212 [ ''_c'', ''f'' ]`"}},{"id":"b","text":{"en":"`0 212 [ ''_c'', ''f'' ]`","uk":"`0 212 [ ''_c'', ''f'' ]`"}},{"id":"c","text":{"en":"`100 32 [ ''_c'' ]`","uk":"`100 32 [ ''_c'' ]`"}},{"id":"d","text":{"en":"`212 212 [ ''_c'', ''f'' ]`","uk":"`212 212 [ ''_c'', ''f'' ]`"}}]}'::jsonb, null::jsonb),
  ('mp-tostringtag', 'quiz', 3, 90, '{"en":"`Symbol.toStringTag`","uk":"`Symbol.toStringTag`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"class Money {\n  get [Symbol.toStringTag]() {\n    return \"Money\";\n  }\n}\nconsole.log(String(new Money()), Object.prototype.toString.call([]), Object.prototype.toString.call(null));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[object Money] [object Array] [object Null]`","uk":"`[object Money] [object Array] [object Null]`"}},{"id":"b","text":{"en":"`[object Object] [object Array] [object Object]`","uk":"`[object Object] [object Array] [object Object]`"}},{"id":"c","text":{"en":"`Money [object Array] null`","uk":"`Money [object Array] null`"}},{"id":"d","text":{"en":"`[object Money] [object Object] [object Null]`","uk":"`[object Money] [object Object] [object Null]`"}}]}'::jsonb, null::jsonb),
  ('mp-proxy-defaults', 'quiz', 4, 120, '{"en":"A `get` trap with defaults","uk":"Пастка `get` зі значеннями за замовчуванням"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const withDefault = (obj, fallback) =>\n  new Proxy(obj, {\n    get: (t, k, r) => (k in t ? Reflect.get(t, k, r) : fallback),\n  });\nconst scores = withDefault({ ada: 10 }, 0);\nconsole.log(scores.ada, scores.bob, \"bob\" in scores, Object.keys(scores));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`10 0 false [ ''ada'' ]`","uk":"`10 0 false [ ''ada'' ]`"}},{"id":"b","text":{"en":"`10 0 true [ ''ada'', ''bob'' ]`","uk":"`10 0 true [ ''ada'', ''bob'' ]`"}},{"id":"c","text":{"en":"`10 undefined false [ ''ada'' ]`","uk":"`10 undefined false [ ''ada'' ]`"}},{"id":"d","text":{"en":"`10 0 true [ ''ada'' ]`","uk":"`10 0 true [ ''ada'' ]`"}}]}'::jsonb, null::jsonb),
  ('mp-reflect-receiver', 'quiz', 4, 150, '{"en":"Why pass the receiver","uk":"Навіщо передавати receiver"}'::jsonb, '{"en":"Both proxies log property reads. What does this print?","uk":"Обидва проксі записують читання властивостей. Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const user = { first: \"Ada\", last: \"Lovelace\", get full() { return this.first + \" \" + this.last; } };\nconst reads = [];\nconst p1 = new Proxy(user, { get(t, k) { reads.push(k); return t[k]; } });\np1.full;\nconst withoutReceiver = reads.length;\nreads.length = 0;\nconst p2 = new Proxy(user, { get(t, k, r) { reads.push(k); return Reflect.get(t, k, r); } });\np2.full;\nconsole.log(withoutReceiver, reads.length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 3`","uk":"`1 3`"}},{"id":"b","text":{"en":"`3 3`","uk":"`3 3`"}},{"id":"c","text":{"en":"`1 1`","uk":"`1 1`"}},{"id":"d","text":{"en":"`3 1`","uk":"`3 1`"}}]}'::jsonb, null::jsonb),
  ('mp-proxy-invariant', 'quiz', 5, 150, '{"en":"Proxy invariants","uk":"Інваріанти Proxy"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-metaprogramming', '{"mode":"single","code":"const target = Object.freeze({ id: 1 });\nconst p = new Proxy(target, { get: () => 2 });\ntry {\n  console.log(p.id);\n} catch (e) {\n  console.log(e.constructor.name);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`TypeError`","uk":"`TypeError`"}},{"id":"b","text":{"en":"`2`","uk":"`2`"}},{"id":"c","text":{"en":"`1`","uk":"`1`"}},{"id":"d","text":{"en":"`undefined`","uk":"`undefined`"}}]}'::jsonb, null::jsonb),
  ('mp-observe', 'practice', 3, 1200, '{"en":"A deep observable with Proxy","uk":"Глибоке спостереження через Proxy"}'::jsonb, '{"en":"Implement `observe(target, onChange)` in `src/observe.ts`. It returns a proxy of `target` that reports changes as `{ type, path, oldValue, newValue }`:\n\n- `set`: assignments at **any depth** (`state.user.address.city = …` → `path: [\"user\", \"address\", \"city\"]`), including objects added later. New properties have `oldValue: undefined`.\n- **Skip** writes that don''t change the value (compare with `Object.is`, so `NaN` → `NaN` is no change).\n- `delete`: deleting an existing property reports `{ type: \"delete\", oldValue, newValue: undefined }`.\n- `state.items.push(x)` should produce **one** change (the new index), not a second one for `length`.\n- Writes reach the original object, and getters that use `this` keep working.\n\nUse `get`, `set` and `deleteProperty` traps and forward to `Reflect` with the receiver.","uk":"Реалізуйте `observe(target, onChange)` у `src/observe.ts`. Функція повертає проксі `target`, що повідомляє про зміни у формі `{ type, path, oldValue, newValue }`:\n\n- `set`: присвоєння **на будь-якій глибині** (`state.user.address.city = …` → `path: [\"user\", \"address\", \"city\"]`), зокрема в об''єктах, доданих пізніше. Нові властивості мають `oldValue: undefined`.\n- **Пропускайте** записи, що не змінюють значення (порівнюйте через `Object.is`, тож `NaN` → `NaN` не є зміною).\n- `delete`: видалення наявної властивості повідомляє `{ type: \"delete\", oldValue, newValue: undefined }`.\n- `state.items.push(x)` має дати **одну** зміну (новий індекс), а не ще одну для `length`.\n- Записи потрапляють у початковий об''єкт, а гетери, що використовують `this`, і далі працюють.\n\nВикористайте пастки `get`, `set` і `deleteProperty` і перенаправляйте до `Reflect` з receiver."}'::jsonb, 'js-metaprogramming', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/observe.ts":"export type Change = {\n  type: \"set\" | \"delete\";\n  /** Keys from the observed root to the changed property, e.g. [\"user\", \"name\"]. */\n  path: string[];\n  oldValue: unknown;\n  newValue: unknown;\n};\n\n/** Returns a proxy of target that reports every change, at any depth, to onChange. */\nexport function observe<T extends object>(target: T, onChange: (change: Change) => void): T {\n  // TODO: nested objects, deletes, and skipping writes that change nothing\n  return new Proxy(target, {\n    set(t: any, key, value) {\n      const oldValue = t[key];\n      t[key] = value;\n      onChange({ type: \"set\", path: [String(key)], oldValue, newValue: value });\n      return true;\n    },\n  });\n}\n","/index.ts":"import \"./styles.css\";\nimport { observe, type Change } from \"./src/observe\";\n\nconst log: string[] = [];\nconst state = observe({ user: { name: \"Ada\" }, todos: [] as string[] }, (c: Change) => {\n  log.push(c.type + \" \" + c.path.join(\".\") + \": \" + JSON.stringify(c.oldValue) + \" → \" + JSON.stringify(c.newValue));\n});\nstate.user.name = \"Ada L.\";\nstate.user.name = \"Ada L.\";\nstate.todos.push(\"write tests\");\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Change log</h1><pre id=\"log\"></pre>'';\ndocument.getElementById(\"log\")!.textContent = log.join(\"\\n\");\n"},"visibleFiles":["/src/observe.ts","/index.ts"],"activeFile":"/src/observe.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { observe } from \"../src/observe\";\n\nfunction setup(initial) {\n  const changes = [];\n  const raw = initial;\n  const state = observe(raw, (c) => changes.push(c));\n  return { state, changes, raw };\n}\n\ndescribe(\"observe\", () => {\n  it(\"reports nested changes with their path and values\", () => {\n    const { state, changes } = setup({ user: { name: \"Ada\", address: { city: \"Kyiv\" } } });\n    state.user.address.city = \"Lviv\";\n    expect(changes).toEqual([{ type: \"set\", path: [\"user\", \"address\", \"city\"], oldValue: \"Kyiv\", newValue: \"Lviv\" }]);\n  });\n  it(\"ignores writes that don''t change the value\", () => {\n    const { state, changes } = setup({ count: 1, nan: NaN });\n    state.count = 1;\n    state.nan = NaN;\n    expect(changes).toEqual([]);\n  });\n  it(\"reports new properties with an undefined old value\", () => {\n    const { state, changes } = setup({});\n    state.theme = \"dark\";\n    expect(changes).toEqual([{ type: \"set\", path: [\"theme\"], oldValue: undefined, newValue: \"dark\" }]);\n  });\n  it(\"reports deletes\", () => {\n    const { state, changes } = setup({ a: 1 });\n    delete state.a;\n    delete state.missing;\n    expect(changes).toEqual([{ type: \"delete\", path: [\"a\"], oldValue: 1, newValue: undefined }]);\n  });\n  it(\"reports one change for an array push\", () => {\n    const { state, changes } = setup({ items: [\"a\", \"b\"] });\n    state.items.push(\"c\");\n    expect(changes).toEqual([{ type: \"set\", path: [\"items\", \"2\"], oldValue: undefined, newValue: \"c\" }]);\n  });\n  it(\"writes through to the original object and keeps getters working\", () => {\n    const { state, raw } = setup({ first: \"Ada\", last: \"Lovelace\", get full() { return this.first + \" \" + this.last; } });\n    state.last = \"Byron\";\n    expect(raw.last).toBe(\"Byron\");\n    expect(state.full).toBe(\"Ada Byron\");\n  });\n  it(\"observes objects added later\", () => {\n    const { state, changes } = setup({});\n    state.settings = { lang: \"en\" };\n    state.settings.lang = \"uk\";\n    expect(changes[1]).toEqual({ type: \"set\", path: [\"settings\", \"lang\"], oldValue: \"en\", newValue: \"uk\" });\n  });\n});\n","testCount":7}'::jsonb),
  ('mp-typed-model', 'practice', 3, 1020, '{"en":"A sealed, type-checked model","uk":"Запечатана модель із перевіркою типів"}'::jsonb, '{"en":"Implement `defineModel(schema)` in `src/model.ts`, where `schema` maps field names to `\"string\"`, `\"number\"` or `\"boolean\"`. It returns `create(values)`, which builds a model object:\n\n- It has exactly the schema''s fields, in schema order, visible to `Object.keys` and `JSON.stringify`.\n- Values are type-checked on creation **and on every assignment** (`NaN` isn''t a valid number); bad values throw a `TypeError` and keep the old value.\n- `create` throws a `TypeError` for unknown or missing fields.\n- The object is **sealed**: adding or deleting properties fails (with a `TypeError` in strict code).\n- `Object.prototype.toString.call(model)` returns `\"[object Model]\"`, via a non-enumerable `Symbol.toStringTag`.\n\nHint: `Object.defineProperty` with accessor descriptors, plus `Object.seal`.","uk":"Реалізуйте `defineModel(schema)` у `src/model.ts`, де `schema` зіставляє назви полів з `\"string\"`, `\"number\"` чи `\"boolean\"`. Функція повертає `create(values)`, що будує об''єкт моделі:\n\n- Він має рівно поля схеми в порядку схеми, видимі для `Object.keys` і `JSON.stringify`.\n- Значення перевіряються за типом під час створення **і при кожному присвоєнні** (`NaN` не є допустимим числом); хибні значення кидають `TypeError` і зберігають старе значення.\n- `create` кидає `TypeError` для невідомих чи відсутніх полів.\n- Об''єкт **запечатаний**: додати чи видалити властивості не вийде (у строгому коді з `TypeError`).\n- `Object.prototype.toString.call(model)` повертає `\"[object Model]\"` через неперелічуваний `Symbol.toStringTag`.\n\nПідказка: `Object.defineProperty` з дескрипторами-аксесорами плюс `Object.seal`."}'::jsonb, 'js-metaprogramming', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/model.ts":"export type FieldType = \"string\" | \"number\" | \"boolean\";\n\n/**\n * defineModel({ name: \"string\", age: \"number\" }) returns create(values): a sealed object whose\n * fields are type-checked on creation and on every assignment.\n */\nexport function defineModel(schema: Record<string, FieldType>) {\n  // TODO: validation, sealing, a \"Model\" string tag\n  return function create(values: Record<string, unknown>): Record<string, unknown> {\n    return { ...values };\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { defineModel } from \"./src/model\";\n\nconst createUser = defineModel({ name: \"string\", age: \"number\", admin: \"boolean\" });\nconst lines: string[] = [];\nconst user = createUser({ name: \"Ada\", age: 36, admin: false });\nlines.push(JSON.stringify(user));\ntry {\n  user.age = \"old\" as unknown as number;\n  lines.push(\"age accepted a string!\");\n} catch (e) {\n  lines.push(\"rejected: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Typed model</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/model.ts","/index.ts"],"activeFile":"/src/model.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { defineModel } from \"../src/model\";\n\nconst createUser = defineModel({ name: \"string\", age: \"number\", admin: \"boolean\" });\n\ndescribe(\"defineModel\", () => {\n  it(\"creates objects with the schema''s fields, in order\", () => {\n    const user = createUser({ admin: false, age: 36, name: \"Ada\" });\n    expect(Object.keys(user)).toEqual([\"name\", \"age\", \"admin\"]);\n    expect(JSON.stringify(user)).toBe(''{\"name\":\"Ada\",\"age\":36,\"admin\":false}'');\n    expect(user.age).toBe(36);\n  });\n  it(\"type-checks on creation and on assignment\", () => {\n    expect(() => createUser({ name: \"Ada\", age: \"36\", admin: false })).toThrow(TypeError);\n    const user = createUser({ name: \"Ada\", age: 36, admin: false });\n    user.age = 37;\n    expect(user.age).toBe(37);\n    expect(() => { user.age = \"old\"; }).toThrow(TypeError);\n    expect(() => { user.age = NaN; }).toThrow(TypeError);\n    expect(user.age).toBe(37);\n  });\n  it(\"rejects unknown and missing fields\", () => {\n    expect(() => createUser({ name: \"Ada\", age: 1, admin: true, extra: 1 })).toThrow(\"Unknown field\");\n    expect(() => createUser({ name: \"Ada\", age: 1 })).toThrow(\"Missing field\");\n  });\n  it(\"can''t gain or lose properties\", () => {\n    const user = createUser({ name: \"Ada\", age: 36, admin: false });\n    expect(Object.isSealed(user)).toBe(true);\n    expect(() => { user.email = \"a@b.c\"; }).toThrow(TypeError);\n    expect(() => { delete user.name; }).toThrow(TypeError);\n  });\n  it(\"has a Model string tag that isn''t enumerable\", () => {\n    const user = createUser({ name: \"Ada\", age: 36, admin: false });\n    expect(Object.prototype.toString.call(user)).toBe(\"[object Model]\");\n    expect(Object.keys(user)).not.toContain(\"Symbol(Symbol.toStringTag)\");\n  });\n  it(\"keeps instances independent\", () => {\n    const a = createUser({ name: \"A\", age: 1, admin: false });\n    const b = createUser({ name: \"B\", age: 2, admin: true });\n    a.name = \"AA\";\n    expect(b.name).toBe(\"B\");\n  });\n});\n","testCount":6}'::jsonb),
