  ('vg-array-holes', 'quiz', 3, 120, '{"en":"Sparse arrays","uk":"Розріджені масиви"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-values-grammar', '{"mode":"single","code":"const a = [1, , 3];\na[10] = 11;\nconsole.log(\n  a.length,\n  a.indexOf(undefined),\n  a.map((x) => x * 2).filter(() => true).length,\n  1 in a,\n  a.includes(undefined),\n);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`11 -1 3 false true`","uk":"`11 -1 3 false true`"}},{"id":"b","text":{"en":"`11 1 11 true true`","uk":"`11 1 11 true true`"}},{"id":"c","text":{"en":"`4 -1 4 false false`","uk":"`4 -1 4 false false`"}},{"id":"d","text":{"en":"`11 1 3 false false`","uk":"`11 1 3 false false`"}}]}'::jsonb, null::jsonb),
  ('vg-precedence', 'quiz', 3, 90, '{"en":"Operator precedence","uk":"Пріоритет операторів"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'js-values-grammar', '{"mode":"single","code":"console.log(true || false && false, (true || false) && false, 1 + 2 + \"3\", \"1\" + 2 + 3, 2 ** -1);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`true false 33 123 0.5`","uk":"`true false 33 123 0.5`"}},{"id":"b","text":{"en":"`false false 33 33 0.5`","uk":"`false false 33 33 0.5`"}},{"id":"c","text":{"en":"`true true 123 123 -2`","uk":"`true true 123 123 -2`"}},{"id":"d","text":{"en":"`false false 6 123 0.5`","uk":"`false false 6 123 0.5`"}}]}'::jsonb, null::jsonb),
