  ('json-replacer-order', 'quiz', 3, 90, '{"en":"How a replacer is called","uk":"Як викликається replacer"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"const keys = [];\nJSON.stringify({ a: 1, b: { c: 2 } }, (key, value) => {\n  keys.push(key);\n  return value;\n});\nconsole.log(keys);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ '''', ''a'', ''b'', ''c'' ]`","uk":"`[ '''', ''a'', ''b'', ''c'' ]`"}},{"id":"b","text":{"en":"`[ ''a'', ''b'', ''c'' ]`","uk":"`[ ''a'', ''b'', ''c'' ]`"}},{"id":"c","text":{"en":"`[ ''a'', ''b'' ]`","uk":"`[ ''a'', ''b'' ]`"}},{"id":"d","text":{"en":"`[ ''c'', ''b'', ''a'', '''' ]`","uk":"`[ ''c'', ''b'', ''a'', '''' ]`"}}]}'::jsonb, null::jsonb),
  ('json-replacer-array', 'quiz', 2, 75, '{"en":"A replacer array","uk":"Масив replacer"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"const record = { id: 1, name: \"Ada\", secret: \"x\", meta: { id: 2, secret: \"y\" } };\nconsole.log(JSON.stringify(record, [\"id\", \"meta\"]));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`{\"id\":1,\"meta\":{\"id\":2}}`","uk":"`{\"id\":1,\"meta\":{\"id\":2}}`"}},{"id":"b","text":{"en":"`{\"id\":1,\"meta\":{\"id\":2,\"secret\":\"y\"}}`","uk":"`{\"id\":1,\"meta\":{\"id\":2,\"secret\":\"y\"}}`"}},{"id":"c","text":{"en":"`{\"id\":1,\"meta\":{}}`","uk":"`{\"id\":1,\"meta\":{}}`"}},{"id":"d","text":{"en":"`{\"name\":\"Ada\",\"secret\":\"x\"}`","uk":"`{\"name\":\"Ada\",\"secret\":\"x\"}`"}}]}'::jsonb, null::jsonb),
  ('json-reviver-order', 'quiz', 3, 90, '{"en":"How a reviver is called","uk":"Як викликається reviver"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"const order = [];\nJSON.parse(''{\"a\":{\"b\":1},\"c\":2}'', (key, value) => {\n  order.push(key);\n  return value;\n});\nconsole.log(order);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''b'', ''a'', ''c'', '''' ]`","uk":"`[ ''b'', ''a'', ''c'', '''' ]`"}},{"id":"b","text":{"en":"`[ '''', ''a'', ''b'', ''c'' ]`","uk":"`[ '''', ''a'', ''b'', ''c'' ]`"}},{"id":"c","text":{"en":"`[ ''a'', ''b'', ''c'' ]`","uk":"`[ ''a'', ''b'', ''c'' ]`"}},{"id":"d","text":{"en":"`[ ''c'', ''b'', ''a'', '''' ]`","uk":"`[ ''c'', ''b'', ''a'', '''' ]`"}}]}'::jsonb, null::jsonb),
  ('json-big-number', 'quiz', 3, 75, '{"en":"A 64-bit id in JSON","uk":"64-бітний ідентифікатор у JSON"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"console.log(JSON.parse(''{\"id\": 9007199254740993}'').id);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`9007199254740992`","uk":"`9007199254740992`"}},{"id":"b","text":{"en":"`9007199254740993`","uk":"`9007199254740993`"}},{"id":"c","text":{"en":"`9007199254740993n`","uk":"`9007199254740993n`"}},{"id":"d","text":{"en":"A `SyntaxError`: number too large","uk":"`SyntaxError`: занадто велике число"}}]}'::jsonb, null::jsonb),
  ('json-prototype-pollution', 'quiz', 4, 150, '{"en":"Merging parsed JSON","uk":"Злиття розібраного JSON"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"const payload = JSON.parse(''{\"__proto__\": {\"isAdmin\": true}}'');\nfunction merge(target, source) {\n  for (const key in source) {\n    if (typeof source[key] === \"object\") {\n      target[key] ??= {};\n      merge(target[key], source[key]);\n    } else {\n      target[key] = source[key];\n    }\n  }\n  return target;\n}\nmerge({}, payload);\nconsole.log(Object.keys(payload), {}.isAdmin);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''__proto__'' ] true`","uk":"`[ ''__proto__'' ] true`"}},{"id":"b","text":{"en":"`[] undefined`","uk":"`[] undefined`"}},{"id":"c","text":{"en":"`[ ''__proto__'' ] undefined`","uk":"`[ ''__proto__'' ] undefined`"}},{"id":"d","text":{"en":"A `SyntaxError`: __proto__ isn''t allowed in JSON","uk":"`SyntaxError`: __proto__ заборонено в JSON"}}]}'::jsonb, null::jsonb),
  ('json-circular', 'quiz', 2, 60, '{"en":"A circular reference","uk":"Циклічне посилання"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'json-serialization', '{"mode":"single","code":"const a = {};\na.self = a;\ntry {\n  console.log(JSON.stringify(a));\n} catch (e) {\n  console.log(e.name);\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`TypeError`","uk":"`TypeError`"}},{"id":"b","text":{"en":"`{\"self\":{}}`","uk":"`{\"self\":{}}`"}},{"id":"c","text":{"en":"`{\"self\":\"[Circular]\"}`","uk":"`{\"self\":\"[Circular]\"}`"}},{"id":"d","text":{"en":"`RangeError`","uk":"`RangeError`"}}]}'::jsonb, null::jsonb),
  ('json-typed-codec', 'practice', 4, 1500, '{"en":"JSON that keeps its types","uk":"JSON, що зберігає типи"}'::jsonb, '{"en":"Write `serialize(value, space?)` and `deserialize(text)` in `src/codec.ts`, so that a round trip restores `Date` (including invalid dates), `BigInt`, `Map`, `Set`, `NaN`, `±Infinity` and `-0`, at any depth, including inside Maps and Sets.\n\n- Encode those values as tag objects like `{ \"$type\": \"Date\", \"value\": \"2024-03-10T09:00:00.000Z\" }`, using a **replacer** and a **reviver**. Plain data must stay ordinary JSON.\n- User objects that happen to have their own `\"$type\"` key must round-trip unchanged too, so escape them.\n- Other objects'' `toJSON` still applies, `undefined` behaves as in plain JSON, and cycles still throw.\n\nHint: by the time a replacer sees a `Date`, its `toJSON` has already turned it into a string. Read the original from `this[key]`.","uk":"Напишіть у `src/codec.ts` функції `serialize(value, space?)` і `deserialize(text)` так, щоб перетворення туди й назад відновлювало `Date` (зокрема некоректні дати), `BigInt`, `Map`, `Set`, `NaN`, `±Infinity` і `-0` на будь-якій глибині, зокрема всередині Map і Set.\n\n- Кодуйте ці значення як об''єкти-мітки на кшталт `{ \"$type\": \"Date\", \"value\": \"2024-03-10T09:00:00.000Z\" }`, використовуючи **replacer** і **reviver**. Звичайні дані мають лишатися звичайним JSON.\n- Об''єкти користувача, що випадково мають власний ключ `\"$type\"`, теж мають проходити туди й назад без змін, тож екрануйте їх.\n- `toJSON` інших об''єктів і далі застосовується, `undefined` поводиться як у звичайному JSON, а цикли й далі кидають помилку.\n\nПідказка: коли replacer бачить `Date`, його `toJSON` уже перетворив її на рядок. Читайте оригінал із `this[key]`."}'::jsonb, 'json-serialization', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/codec.ts":"/**\n * JSON that round-trips Date, BigInt, Map, Set, NaN, ±Infinity and -0, by encoding them as\n * { \"$type\": \"...\", \"value\": ... } objects. Plain data stays plain JSON.\n */\nexport function serialize(value: unknown, space?: number): string {\n  return JSON.stringify(value, null, space); // TODO\n}\n\nexport function deserialize(text: string): unknown {\n  return JSON.parse(text); // TODO\n}\n","/index.ts":"import \"./styles.css\";\nimport { deserialize, serialize } from \"./src/codec\";\n\nconst original = {\n  createdAt: new Date(\"2024-03-10T09:00:00Z\"),\n  id: 9007199254740993n,\n  tags: new Set([\"a\", \"b\"]),\n  scores: new Map([[\"ada\", 10]]),\n  ratio: NaN,\n};\nlet output: string;\ntry {\n  const text = serialize(original, 2);\n  const copy: any = deserialize(text);\n  output = text + \"\\n\\nrestored types: \" + [copy.createdAt instanceof Date, typeof copy.id, copy.tags instanceof Set, copy.scores instanceof Map, Number.isNaN(copy.ratio)].join(\", \");\n} catch (e) {\n  output = \"error: \" + (e as Error).message;\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Typed JSON</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = output;\n"},"visibleFiles":["/src/codec.ts","/index.ts"],"activeFile":"/src/codec.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { deserialize, serialize } from \"../src/codec\";\n\nconst roundTrip = (v) => deserialize(serialize(v));\n\ndescribe(\"serialize / deserialize\", () => {\n  it(\"keeps plain data as plain JSON\", () => {\n    const data = { a: 1, b: \"x\", c: [true, null], d: { e: 2 } };\n    expect(JSON.parse(serialize(data))).toEqual(data);\n    expect(roundTrip(data)).toEqual(data);\n  });\n  it(\"restores dates, including invalid ones\", () => {\n    const result = roundTrip({ at: new Date(\"2024-03-10T09:00:00Z\"), bad: new Date(\"nope\") });\n    expect(result.at).toBeInstanceOf(Date);\n    expect(result.at.toISOString()).toBe(\"2024-03-10T09:00:00.000Z\");\n    expect(Number.isNaN(result.bad.getTime())).toBe(true);\n  });\n  it(\"restores BigInt, Map and Set, including nested values\", () => {\n    const result = roundTrip({\n      id: 9007199254740993n,\n      map: new Map([[\"when\", new Date(0)], [\"ids\", new Set([1n, 2n])]]),\n    });\n    expect(result.id).toBe(9007199254740993n);\n    expect(result.map).toBeInstanceOf(Map);\n    expect(result.map.get(\"when\")).toBeInstanceOf(Date);\n    expect([...result.map.get(\"ids\")]).toEqual([1n, 2n]);\n  });\n  it(\"restores NaN, Infinity and -0\", () => {\n    const result = roundTrip([NaN, Infinity, -Infinity, -0, 0]);\n    expect(Number.isNaN(result[0])).toBe(true);\n    expect(result[1]).toBe(Infinity);\n    expect(result[2]).toBe(-Infinity);\n    expect(Object.is(result[3], -0)).toBe(true);\n    expect(Object.is(result[4], 0)).toBe(true);\n  });\n  it(\"doesn''t confuse user data that has a $type key with a tag\", () => {\n    const data = { item: { $type: \"Map\", value: [[\"a\", 1]] }, other: { $type: \"custom\" } };\n    expect(roundTrip(data)).toEqual(data);\n  });\n  it(\"still uses toJSON on other objects, and drops undefined like JSON\", () => {\n    class Money {\n      constructor(cents) { this.cents = cents; }\n      toJSON() { return (this.cents / 100).toFixed(2); }\n    }\n    expect(roundTrip({ price: new Money(1999), gone: undefined })).toEqual({ price: \"19.99\" });\n  });\n  it(\"throws on cycles\", () => {\n    const a = {};\n    a.self = a;\n    expect(() => serialize(a)).toThrow(TypeError);\n  });\n});\n","testCount":7}'::jsonb),
  ('json-safe-parse', 'practice', 3, 1320, '{"en":"Parse and validate untrusted JSON","uk":"Розбір і валідація ненадійного JSON"}'::jsonb, '{"en":"Implement `safeParse(text, schema)` in `src/safe-parse.ts`, a tiny Zod-like validator for request bodies. It **never throws** and returns `{ ok: true, value }` or `{ ok: false, errors }`, where each error is `{ path, message }`:\n\n- Invalid JSON gives `[{ path: \"\", message: \"Invalid JSON\" }]`.\n- Types are checked strictly (`\"Expected string\"`, `\"Expected number\"`, `\"Expected integer\"`, `\"Expected boolean\"`, `\"Expected array\"`, `\"Expected object\"`), together with the constraints `minLength`/`maxLength` (`\"Too short\"`/`\"Too long\"`), `enum` (`\"Must be one of: a, b\"`), `min`/`max` (`\"Too small\"`/`\"Too large\"`) and `maxItems` (`\"Too many items\"`). Missing required keys give `\"Required\"`, and only **own** properties count as present.\n- Report **every** error, with paths like `items[1].qty`, in document order.\n- The returned value contains **only the schema''s keys**, so unknown keys and `__proto__` payloads are dropped and can''t pollute prototypes.","uk":"Реалізуйте у `src/safe-parse.ts` функцію `safeParse(text, schema)`, крихітний валідатор у стилі Zod для тіл запитів. Вона **ніколи не кидає помилку** й повертає `{ ok: true, value }` чи `{ ok: false, errors }`, де кожна помилка має вигляд `{ path, message }`:\n\n- Некоректний JSON дає `[{ path: \"\", message: \"Invalid JSON\" }]`.\n- Типи перевіряються суворо (`\"Expected string\"`, `\"Expected number\"`, `\"Expected integer\"`, `\"Expected boolean\"`, `\"Expected array\"`, `\"Expected object\"`) разом з обмеженнями `minLength`/`maxLength` (`\"Too short\"`/`\"Too long\"`), `enum` (`\"Must be one of: a, b\"`), `min`/`max` (`\"Too small\"`/`\"Too large\"`) і `maxItems` (`\"Too many items\"`). Відсутні обов''язкові ключі дають `\"Required\"`, і присутніми вважаються лише **власні** властивості.\n- Повідомляйте про **кожну** помилку зі шляхами на кшталт `items[1].qty` у порядку документа.\n- Повернене значення містить **лише ключі схеми**, тож невідомі ключі й дані в `__proto__` відкидаються й не можуть забруднити прототипи."}'::jsonb, 'json-serialization', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/safe-parse.ts":"export type Schema =\n  | { type: \"string\"; minLength?: number; maxLength?: number; enum?: string[] }\n  | { type: \"number\"; integer?: boolean; min?: number; max?: number }\n  | { type: \"boolean\" }\n  | { type: \"array\"; items: Schema; maxItems?: number }\n  | { type: \"object\"; properties: Record<string, Schema>; required?: string[] };\n\nexport type Issue = { path: string; message: string };\nexport type Result = { ok: true; value: unknown } | { ok: false; errors: Issue[] };\n\n/** Parses untrusted JSON and validates it against schema. Never throws. */\nexport function safeParse(text: string, schema: Schema): Result {\n  // TODO: throws on bad JSON, validates nothing, keeps unknown keys\n  return { ok: true, value: JSON.parse(text) };\n}\n","/index.ts":"import \"./styles.css\";\nimport { safeParse, type Schema } from \"./src/safe-parse\";\n\nconst userSchema: Schema = {\n  type: \"object\",\n  required: [\"name\", \"age\"],\n  properties: {\n    name: { type: \"string\", minLength: 1 },\n    age: { type: \"number\", integer: true, min: 0 },\n    role: { type: \"string\", enum: [\"user\", \"admin\"] },\n  },\n};\nconst inputs = [''{\"name\":\"Ada\",\"age\":36}'', ''{\"name\":\"\",\"age\":\"ten\",\"role\":\"root\"}'', \"{name: Ada}\", ''{\"name\":\"Eve\",\"age\":1,\"__proto__\":{\"isAdmin\":true}}''];\nconst lines: string[] = [];\nfor (const text of inputs) {\n  try {\n    lines.push(text + \"\\n  → \" + JSON.stringify(safeParse(text, userSchema)));\n  } catch (e) {\n    lines.push(text + \"\\n  → threw \" + (e as Error).name);\n  }\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Safe parse</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\\n\");\n"},"visibleFiles":["/src/safe-parse.ts","/index.ts"],"activeFile":"/src/safe-parse.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { safeParse } from \"../src/safe-parse\";\n\nconst order = {\n  type: \"object\",\n  required: [\"id\", \"items\"],\n  properties: {\n    id: { type: \"string\", minLength: 3 },\n    status: { type: \"string\", enum: [\"new\", \"paid\"] },\n    items: {\n      type: \"array\",\n      maxItems: 3,\n      items: {\n        type: \"object\",\n        required: [\"sku\", \"qty\"],\n        properties: { sku: { type: \"string\" }, qty: { type: \"number\", integer: true, min: 1, max: 99 }, gift: { type: \"boolean\" } },\n      },\n    },\n  },\n};\n\ndescribe(\"safeParse\", () => {\n  it(\"returns valid data\", () => {\n    const text = JSON.stringify({ id: \"A-1\", status: \"paid\", items: [{ sku: \"x\", qty: 2, gift: true }] });\n    expect(safeParse(text, order)).toEqual({ ok: true, value: { id: \"A-1\", status: \"paid\", items: [{ sku: \"x\", qty: 2, gift: true }] } });\n  });\n  it(\"never throws on invalid JSON\", () => {\n    expect(safeParse(\"{id: 1}\", order)).toEqual({ ok: false, errors: [{ path: \"\", message: \"Invalid JSON\" }] });\n    expect(safeParse(\"\", order).ok).toBe(false);\n  });\n  it(\"reports every problem with its path\", () => {\n    const text = JSON.stringify({ id: \"A\", status: \"shipped\", items: [{ sku: 5, qty: 1.5 }, { qty: 0 }] });\n    const result = safeParse(text, order);\n    expect(result.ok).toBe(false);\n    expect(result.errors).toEqual([\n      { path: \"id\", message: \"Too short\" },\n      { path: \"status\", message: \"Must be one of: new, paid\" },\n      { path: \"items[0].sku\", message: \"Expected string\" },\n      { path: \"items[0].qty\", message: \"Expected integer\" },\n      { path: \"items[1].sku\", message: \"Required\" },\n      { path: \"items[1].qty\", message: \"Too small\" },\n    ]);\n  });\n  it(\"checks types strictly\", () => {\n    const result = safeParse(JSON.stringify({ id: 123, items: {} }), order);\n    expect(result.errors).toEqual([\n      { path: \"id\", message: \"Expected string\" },\n      { path: \"items\", message: \"Expected array\" },\n    ]);\n    expect(safeParse(\"[]\", order).errors).toEqual([{ path: \"\", message: \"Expected object\" }]);\n  });\n  it(\"enforces limits and required fields\", () => {\n    const many = JSON.stringify({ id: \"A-1\", items: [1, 2, 3, 4] });\n    expect(safeParse(many, order).errors).toEqual([{ path: \"items\", message: \"Too many items\" }]);\n    expect(safeParse(\"{}\", order).errors).toEqual([\n      { path: \"id\", message: \"Required\" },\n      { path: \"items\", message: \"Required\" },\n    ]);\n  });\n  it(\"drops unknown keys and blocks prototype pollution\", () => {\n    const text = ''{\"id\":\"A-1\",\"items\":[],\"extra\":1,\"__proto__\":{\"isAdmin\":true},\"constructor\":{\"prototype\":{\"x\":1}}}'';\n    const result = safeParse(text, order);\n    expect(result).toEqual({ ok: true, value: { id: \"A-1\", items: [] } });\n    expect(result.value.isAdmin).toBeUndefined();\n    expect({}.isAdmin).toBeUndefined();\n    expect(Object.getPrototypeOf(result.value)).toBe(Object.prototype);\n  });\n  it(\"doesn''t treat inherited properties as present\", () => {\n    const schema = { type: \"object\", required: [\"toString\"], properties: { toString: { type: \"string\" } } };\n    expect(safeParse(\"{}\", schema).errors).toEqual([{ path: \"toString\", message: \"Required\" }]);\n  });\n});\n","testCount":7}'::jsonb),
  ('jwt-decode-is-not-verify', 'quiz', 2, 75, '{"en":"Decoding is not verifying","uk":"Декодування не є перевіркою"}'::jsonb, '{"en":"Which statement about the payload of a JWT is true?","uk":"Яке твердження про payload JWT правильне?"}'::jsonb, null, '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Anyone holding the token can read the payload, so it must never contain secrets; only the signature proves it wasn''t changed","uk":"Будь-хто, хто має токен, може прочитати payload, тож він ніколи не повинен містити секретів; лише підпис доводить, що його не змінили"}},{"id":"b","text":{"en":"The payload is encrypted, so only the server can read it","uk":"Payload зашифрований, тож лише сервер може його прочитати"}},{"id":"c","text":{"en":"Changing the payload is harmless, because the server reads claims from the database instead","uk":"Зміна payload безпечна, бо сервер бере claims з бази даних"}},{"id":"d","text":{"en":"A token whose payload decodes correctly is always trustworthy","uk":"Токен, чий payload правильно декодується, завжди надійний"}}]}'::jsonb, null::jsonb),
  ('jwt-claims-scope', 'quiz', 3, 90, '{"en":"Why `aud` and `exp` matter","uk":"Навіщо потрібні `aud` і `exp`"}'::jsonb, '{"en":"A valid, signed token issued for the mobile app is presented to the admin API. Which claim should the admin API have checked to reject it?","uk":"Дійсний підписаний токен, виданий для мобільного застосунку, пред''явлено до адмін-API. Яку claim адмін-API мав перевірити, щоб відхилити його?"}'::jsonb, null, '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`aud`, the audience the token was issued for","uk":"`aud`, аудиторію, для якої видано токен"}},{"id":"b","text":{"en":"`sub`, the user id","uk":"`sub`, id користувача"}},{"id":"c","text":{"en":"`iat`, the time of issue","uk":"`iat`, час видачі"}},{"id":"d","text":{"en":"Nothing: a valid signature is enough","uk":"Нічого: достатньо дійсного підпису"}}]}'::jsonb, null::jsonb),
  ('jwt-claims-check', 'practice', 4, 1200, '{"en":"Decode and check JWT claims","uk":"Декодуйте і перевіряйте claims JWT"}'::jsonb, '{"en":"Implement two functions in `src/jwt.ts`. This is the claims half of JWT handling: **the signature must be verified separately, with the key, before you trust anything you read here**.\n\n- `decodePayload(token)` reads the middle segment: base64url (with `-` and `_`, and optional padding) decoded as **UTF-8** JSON. Throw `Malformed token` for anything that isn''t three segments with a JSON object as payload.\n- `checkClaims(token, { now, issuer, audience, clockSkew = 30 })` returns `{ valid: true, claims }` or `{ valid: false, reason }` with these reasons, checked in this order: `malformed`, `missing exp`, `expired` (when `now >= exp + clockSkew`), `not yet valid` (when `now + clockSkew < nbf`), `wrong issuer`, `wrong audience`. `aud` may be a string or a list.\n- All times are in seconds, like the claims.","uk":"Реалізуйте дві функції в `src/jwt.ts`. Це частина роботи з claims у JWT: **підпис треба перевіряти окремо, з ключем, перш ніж довіряти чомусь із прочитаного тут**.\n\n- `decodePayload(token)` читає середній сегмент: base64url (з `-` і `_`, із необов''язковим доповненням), декодований як **UTF-8** JSON. Кидайте `Malformed token` для всього, що не є трьома сегментами з JSON-об''єктом як payload.\n- `checkClaims(token, { now, issuer, audience, clockSkew = 30 })` повертає `{ valid: true, claims }` або `{ valid: false, reason }` з цими причинами, у такому порядку перевірки: `malformed`, `missing exp`, `expired` (коли `now >= exp + clockSkew`), `not yet valid` (коли `now + clockSkew < nbf`), `wrong issuer`, `wrong audience`. `aud` може бути рядком або списком.\n- Усі часи в секундах, як у claims."}'::jsonb, null, null::jsonb, '{"framework":"vanilla-ts","files":{"/src/jwt.ts":"export type Claims = {\n  iss?: string;\n  sub?: string;\n  aud?: string | string[];\n  exp?: number;\n  nbf?: number;\n  iat?: number;\n  [key: string]: unknown;\n};\n\n/** Reads the payload of a JWT. It does NOT verify the signature, which needs the key. */\nexport function decodePayload(token: string): Claims {\n  // TODO: base64url-decode the middle segment, decode UTF-8, parse JSON. Throw \"Malformed token\" on anything wrong.\n  return {};\n}\n\nexport type CheckOptions = { now: number; issuer?: string; audience?: string; clockSkew?: number };\nexport type CheckResult = { valid: true; claims: Claims } | { valid: false; reason: string };\n\n/** Checks the claims of a token whose signature has already been verified. */\nexport function checkClaims(token: string, options: CheckOptions): CheckResult {\n  // TODO: malformed, missing exp, expired, not yet valid, wrong issuer, wrong audience\n  return { valid: true, claims: {} };\n}\n","/index.ts":"import \"./styles.css\";\nimport { checkClaims } from \"./src/jwt\";\n\nconst b64 = (obj) => btoa(JSON.stringify(obj)).replace(/=+$/, \"\");\nconst token = [\"eyJhbGciOiJIUzI1NiJ9\", b64({ sub: \"u1\", iss: \"auth.example\", exp: 2000 }), \"signature\"].join(\".\");\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>JWT claims</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = JSON.stringify(checkClaims(token, { now: 1000, issuer: \"auth.example\" }), null, 2);\n"},"visibleFiles":["/src/jwt.ts"],"activeFile":"/src/jwt.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { checkClaims, decodePayload } from \"../src/jwt\";\n\n// btoa only handles Latin-1, so encode UTF-8 first (the same trick a real decoder has to undo).\nconst utf8 = (s) => btoa(encodeURIComponent(s).replace(/%([0-9A-F]{2})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16))));\nconst b64url = (obj) => utf8(JSON.stringify(obj)).replace(/\\+/g, \"-\").replace(/\\//g, \"_\").replace(/=+$/, \"\");\nconst token = (payload) => [\"eyJhbGciOiJIUzI1NiJ9\", b64url(payload), \"signature\"].join(\".\");\n\ndescribe(\"decodePayload\", () => {\n  it(\"reads the payload, including UTF-8 text\", () => {\n    expect(decodePayload(token({ sub: \"u1\", name: \"Оля\" }))).toEqual({ sub: \"u1\", name: \"Оля\" });\n  });\n  it(\"rejects malformed tokens\", () => {\n    expect(() => decodePayload(\"abc\")).toThrow(\"Malformed token\");\n    expect(() => decodePayload(\"a.@@@.c\")).toThrow(\"Malformed token\");\n    expect(() => decodePayload([\"h\", utf8(\"not json\"), \"s\"].join(\".\"))).toThrow(\"Malformed token\");\n    expect(() => decodePayload([\"h\", utf8(\"[1,2]\"), \"s\"].join(\".\"))).toThrow(\"Malformed token\");\n  });\n});\n\ndescribe(\"checkClaims\", () => {\n  it(\"accepts a token within its lifetime\", () => {\n    expect(checkClaims(token({ exp: 2000 }), { now: 1000 }).valid).toBe(true);\n  });\n  it(\"expires at exp plus the clock skew (30 seconds by default)\", () => {\n    expect(checkClaims(token({ exp: 1000 }), { now: 1029 }).valid).toBe(true);\n    expect(checkClaims(token({ exp: 1000 }), { now: 1030 })).toEqual({ valid: false, reason: \"expired\" });\n    expect(checkClaims(token({ exp: 1000 }), { now: 999, clockSkew: 0 }).valid).toBe(true);\n  });\n  it(\"rejects tokens that aren''t valid yet\", () => {\n    expect(checkClaims(token({ exp: 9000, nbf: 1000 }), { now: 960 })).toEqual({ valid: false, reason: \"not yet valid\" });\n    expect(checkClaims(token({ exp: 9000, nbf: 1000 }), { now: 970 }).valid).toBe(true);\n  });\n  it(\"rejects tokens without an exp claim\", () => {\n    expect(checkClaims(token({ sub: \"u1\" }), { now: 1 })).toEqual({ valid: false, reason: \"missing exp\" });\n  });\n  it(\"checks the issuer\", () => {\n    const t = token({ iss: \"auth.example\", exp: 2000 });\n    expect(checkClaims(t, { now: 1000, issuer: \"auth.example\" }).valid).toBe(true);\n    expect(checkClaims(t, { now: 1000, issuer: \"elsewhere\" })).toEqual({ valid: false, reason: \"wrong issuer\" });\n  });\n  it(\"checks the audience, which may be a list\", () => {\n    const t = token({ aud: [\"web\", \"api\"], exp: 2000 });\n    expect(checkClaims(t, { now: 1000, audience: \"api\" }).valid).toBe(true);\n    expect(checkClaims(t, { now: 1000, audience: \"mobile\" })).toEqual({ valid: false, reason: \"wrong audience\" });\n    expect(checkClaims(token({ aud: \"web\", exp: 2000 }), { now: 1000, audience: \"web\" }).valid).toBe(true);\n  });\n  it(\"reports malformed tokens instead of throwing\", () => {\n    expect(checkClaims(\"nope\", { now: 1000 })).toEqual({ valid: false, reason: \"malformed\" });\n  });\n});\n","testCount":9}'::jsonb),
  ('log-structured-fields', 'quiz', 2, 75, '{"en":"Why structured logs","uk":"Навіщо структуровані журнали"}'::jsonb, '{"en":"Why do production services write logs as structured JSON instead of plain sentences?","uk":"Чому сервіси у продакшені пишуть журнали як структурований JSON, а не звичайними реченнями?"}'::jsonb, null, '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Machines can filter and aggregate by named fields, such as every error for one request id, without fragile text matching","uk":"Машини можуть фільтрувати й агрегувати за іменованими полями, наприклад, усі помилки одного запиту, без крихкого пошуку по тексту"}},{"id":"b","text":{"en":"JSON is smaller than text, so logs take less disk space","uk":"JSON менший за текст, тож журнали займають менше місця на диску"}},{"id":"c","text":{"en":"Plain sentences can''t contain numbers","uk":"Звичайні речення не можуть містити числа"}},{"id":"d","text":{"en":"Only JSON logs can be sent over the network","uk":"Лише JSON-журнали можна надсилати мережею"}}]}'::jsonb, null::jsonb),
  ('logging-redacting-logger', 'practice', 3, 1080, '{"en":"A structured logger that redacts secrets","uk":"Структурований логер, що приховує секрети"}'::jsonb, '{"en":"Logs are read by people and machines long after they''re written, so they must be structured and must never leak secrets. Implement `createLogger(options)` in `src/logger.ts`:\n\n- Levels are `debug`, `info`, `warn` and `error`. Entries below the configured `level` (default `info`) are dropped.\n- Each entry is `{ level, message, time, fields }`, where `time` comes from `now()`, and `fields` is a copy, so the caller''s objects are never changed.\n- `child(fields)` returns a logger that adds those fields to every entry it writes; child loggers can have children of their own.\n- Any field whose name is in `redactKeys` is written as `\"[REDACTED]\"`, at any depth and in any array, compared case-insensitively, and this includes fields bound by `child`.\n- An `Error` is written as `{ name, message }` (no stack).","uk":"Журнали читають люди й машини довго після запису, тож вони мають бути структурованими і ніколи не витікати секретів. Реалізуйте `createLogger(options)` у `src/logger.ts`:\n\n- Рівні: `debug`, `info`, `warn` і `error`. Записи нижчі за налаштований `level` (за замовчуванням `info`) відкидаються.\n- Кожен запис — це `{ level, message, time, fields }`, де `time` береться з `now()`, а `fields` — копія, тож об''єкти викликача ніколи не змінюються.\n- `child(fields)` повертає логер, що додає ці поля до кожного свого запису; дочірні логери можуть мати власні дочірні.\n- Будь-яке поле, чия назва є в `redactKeys`, записується як `\"[REDACTED]\"` на будь-якій глибині й у будь-якому масиві, без урахування регістру, і це стосується полів, прив''язаних через `child`.\n- `Error` записується як `{ name, message }` (без стеку)."}'::jsonb, null, null::jsonb, '{"framework":"vanilla-ts","files":{"/src/logger.ts":"export type Level = \"debug\" | \"info\" | \"warn\" | \"error\";\nexport type Entry = { level: Level; message: string; time: string; fields: Record<string, unknown> };\nexport type Sink = (entry: Entry) => void;\n\nexport type Logger = {\n  debug(message: string, fields?: Record<string, unknown>): void;\n  info(message: string, fields?: Record<string, unknown>): void;\n  warn(message: string, fields?: Record<string, unknown>): void;\n  error(message: string, fields?: Record<string, unknown>): void;\n  /** A logger that adds these fields to every entry it writes. */\n  child(fields: Record<string, unknown>): Logger;\n};\n\nexport type LoggerOptions = {\n  level?: Level;\n  sink: Sink;\n  now?: () => string;\n  /** Field names whose values must never be written, at any depth, compared case-insensitively. */\n  redactKeys?: string[];\n};\n\nexport function createLogger(options: LoggerOptions): Logger {\n  // TODO: levels, bound fields, redaction, and errors written as { name, message }\n  return {\n    debug() {},\n    info() {},\n    warn() {},\n    error() {},\n    child() {\n      return this as Logger;\n    },\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createLogger } from \"./src/logger\";\n\nconst lines: string[] = [];\nconst log = createLogger({ level: \"info\", redactKeys: [\"password\"], sink: (e) => lines.push(e.level + \" \" + e.message + \" \" + JSON.stringify(e.fields)) });\nlog.child({ requestId: \"r1\" }).info(\"signed in\", { user: \"ada\", password: \"hunter2\" });\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Logger</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/logger.ts"],"activeFile":"/src/logger.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { createLogger } from \"../src/logger\";\n\nfunction setup(extra = {}) {\n  const entries = [];\n  const log = createLogger({ now: () => \"2026-01-01T00:00:00Z\", sink: (e) => entries.push(e), ...extra });\n  return { log, entries };\n}\n\ndescribe(\"createLogger\", () => {\n  it(\"writes entries with a level, message, time and fields\", () => {\n    const { log, entries } = setup();\n    log.info(\"started\", { port: 3000 });\n    expect(entries).toEqual([{ level: \"info\", message: \"started\", time: \"2026-01-01T00:00:00Z\", fields: { port: 3000 } }]);\n  });\n  it(\"drops entries below the configured level\", () => {\n    const { log, entries } = setup({ level: \"warn\" });\n    log.debug(\"noise\");\n    log.info(\"routine\");\n    log.warn(\"careful\");\n    log.error(\"broken\");\n    expect(entries.map((e) => e.level)).toEqual([\"warn\", \"error\"]);\n  });\n  it(\"child loggers add their fields to every entry\", () => {\n    const { log, entries } = setup();\n    const request = log.child({ requestId: \"r1\" });\n    request.info(\"start\");\n    request.child({ step: 2 }).warn(\"slow\", { ms: 900 });\n    expect(entries[0].fields).toEqual({ requestId: \"r1\" });\n    expect(entries[1].fields).toEqual({ requestId: \"r1\", step: 2, ms: 900 });\n  });\n  it(\"redacts secret keys at any depth, ignoring case\", () => {\n    const { log, entries } = setup({ redactKeys: [\"password\", \"token\"] });\n    log.info(\"login\", { PassWord: \"x\", user: { token: \"t\", name: \"ada\" }, list: [{ token: \"u\" }] });\n    expect(entries[0].fields).toEqual({\n      PassWord: \"[REDACTED]\",\n      user: { token: \"[REDACTED]\", name: \"ada\" },\n      list: [{ token: \"[REDACTED]\" }],\n    });\n  });\n  it(\"redacts bound fields too\", () => {\n    const { log, entries } = setup({ redactKeys: [\"apiKey\"] });\n    log.child({ apiKey: \"secret\" }).info(\"call\");\n    expect(entries[0].fields).toEqual({ apiKey: \"[REDACTED]\" });\n  });\n  it(\"writes errors as name and message, without the stack\", () => {\n    const { log, entries } = setup();\n    log.error(\"failed\", { err: new TypeError(\"bad input\") });\n    expect(entries[0].fields).toEqual({ err: { name: \"TypeError\", message: \"bad input\" } });\n  });\n  it(\"doesn''t change the objects it was given\", () => {\n    const { log } = setup({ redactKeys: [\"password\"] });\n    const fields = { password: \"x\", nested: { ok: 1 } };\n    log.info(\"m\", fields);\n    expect(fields).toEqual({ password: \"x\", nested: { ok: 1 } });\n  });\n});\n","testCount":7}'::jsonb),
  ('sched-long-task', 'quiz', 1, 45, '{"en":"What counts as a long task?","uk":"Що вважається довгою задачею?"}'::jsonb, '{"en":"Browsers report main-thread tasks as \"long tasks\" above which duration?","uk":"Понад яку тривалість браузери позначають задачі головного потоку як «довгі»?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"50 ms","uk":"50 мс"}},{"id":"b","text":{"en":"16.7 ms","uk":"16,7 мс"}},{"id":"c","text":{"en":"200 ms","uk":"200 мс"}},{"id":"d","text":{"en":"1 second","uk":"1 секунда"}}]}'::jsonb, null::jsonb),
  ('sched-inp', 'quiz', 2, 75, '{"en":"What INP measures","uk":"Що вимірює INP"}'::jsonb, '{"en":"Interaction to Next Paint (INP) is high on a product page. What does it measure?","uk":"Interaction to Next Paint (INP) на сторінці товару високий. Що він вимірює?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The time from a user interaction (click, tap, key press) until the next frame is painted, including waiting for busy main-thread tasks, the handlers and rendering","uk":"Час від взаємодії користувача (натискання, дотик, клавіша) до малювання наступного кадру, зокрема очікування зайнятих задач головного потоку, обробники й рендер"}},{"id":"b","text":{"en":"How long the largest image takes to load","uk":"Скільки триває завантаження найбільшого зображення"}},{"id":"c","text":{"en":"How much the layout shifts after loading","uk":"Наскільки зсувається розмітка після завантаження"}},{"id":"d","text":{"en":"The time until the first byte arrives from the server","uk":"Час до отримання першого байта від сервера"}}]}'::jsonb, null::jsonb),
  ('sched-microtasks-dont-yield', 'quiz', 3, 90, '{"en":"\"Yielding\" with a resolved promise","uk":"«Поступка потоку» через розв''язаний проміс"}'::jsonb, '{"en":"A timer is queued, then a loop awaits a resolved promise between chunks. What does this print?","uk":"У чергу ставиться таймер, а потім цикл між частинами чекає на розв''язаний проміс. Що виведе цей код?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","code":"const log = [];\nsetTimeout(() => log.push(\"timer\"), 0);\nfor (let i = 0; i < 3; i++) {\n  log.push(\"chunk \" + i);\n  await Promise.resolve();\n}\nawait new Promise((r) => setTimeout(r, 5));\nconsole.log(log.join(\", \"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`chunk 0, chunk 1, chunk 2, timer`","uk":"`chunk 0, chunk 1, chunk 2, timer`"}},{"id":"b","text":{"en":"`chunk 0, timer, chunk 1, chunk 2`","uk":"`chunk 0, timer, chunk 1, chunk 2`"}},{"id":"c","text":{"en":"`timer, chunk 0, chunk 1, chunk 2`","uk":"`timer, chunk 0, chunk 1, chunk 2`"}},{"id":"d","text":{"en":"`chunk 0, timer, chunk 1, timer, chunk 2`","uk":"`chunk 0, timer, chunk 1, timer, chunk 2`"}}]}'::jsonb, null::jsonb),
  ('sched-timeout-yields', 'quiz', 3, 90, '{"en":"Yielding with a timer","uk":"Поступка потоку через таймер"}'::jsonb, '{"en":"Now the loop waits for a `setTimeout` between chunks. What does this print?","uk":"Тепер цикл між частинами чекає на `setTimeout`. Що виведе цей код?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","code":"const log = [];\nsetTimeout(() => log.push(\"timer\"), 0);\nfor (let i = 0; i < 3; i++) {\n  log.push(\"chunk \" + i);\n  await new Promise((r) => setTimeout(r, 0));\n}\nconsole.log(log.join(\", \"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`chunk 0, timer, chunk 1, chunk 2`","uk":"`chunk 0, timer, chunk 1, chunk 2`"}},{"id":"b","text":{"en":"`chunk 0, chunk 1, chunk 2, timer`","uk":"`chunk 0, chunk 1, chunk 2, timer`"}},{"id":"c","text":{"en":"`timer, chunk 0, chunk 1, chunk 2`","uk":"`timer, chunk 0, chunk 1, chunk 2`"}},{"id":"d","text":{"en":"`chunk 0, timer, chunk 1, timer, chunk 2`","uk":"`chunk 0, timer, chunk 1, timer, chunk 2`"}}]}'::jsonb, null::jsonb),
  ('sched-raf', 'quiz', 2, 60, '{"en":"Animating a progress bar","uk":"Анімація смуги прогресу"}'::jsonb, '{"en":"You animate a progress bar''s width with JavaScript. Which scheduling primitive should drive the updates?","uk":"Ви анімуєте ширину смуги прогресу через JavaScript. Який засіб планування має керувати оновленнями?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`requestAnimationFrame`, computing progress from its timestamp","uk":"`requestAnimationFrame`, обчислюючи прогрес за його часовою позначкою"}},{"id":"b","text":{"en":"`setInterval(update, 16)`","uk":"`setInterval(update, 16)`"}},{"id":"c","text":{"en":"`requestIdleCallback`","uk":"`requestIdleCallback`"}},{"id":"d","text":{"en":"`queueMicrotask` in a loop","uk":"`queueMicrotask` у циклі"}}]}'::jsonb, null::jsonb),
  ('sched-idle-callback', 'quiz', 2, 75, '{"en":"Low-priority work","uk":"Низькопріоритетна робота"}'::jsonb, '{"en":"You want to send batched analytics events without competing with user interactions, but they must be sent within a few seconds. What fits best?","uk":"Ви хочете надсилати згруповані події аналітики, не конкуруючи з взаємодіями користувача, але їх треба надіслати протягом кількох секунд. Що підходить найкраще?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`requestIdleCallback(send, { timeout: 2000 })`, with a fallback where it isn''t supported","uk":"`requestIdleCallback(send, { timeout: 2000 })` із запасним варіантом там, де його немає"}},{"id":"b","text":{"en":"`requestAnimationFrame(send)`","uk":"`requestAnimationFrame(send)`"}},{"id":"c","text":{"en":"Send synchronously inside every click handler","uk":"Надсилати синхронно в кожному обробнику натискання"}},{"id":"d","text":{"en":"`requestIdleCallback(send)` with no timeout","uk":"`requestIdleCallback(send)` без тайм-ауту"}}]}'::jsonb, null::jsonb),
  ('sched-layout-thrashing', 'quiz', 3, 90, '{"en":"Forced synchronous layout","uk":"Примусовий синхронний перерахунок розмітки"}'::jsonb, '{"en":"Which loop forces the browser to recalculate layout on every iteration?","uk":"Який цикл змушує браузер перераховувати розмітку на кожній ітерації?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`for (const el of items) el.style.height = el.offsetWidth / 2 + \"px\";`","uk":"`for (const el of items) el.style.height = el.offsetWidth / 2 + \"px\";`"}},{"id":"b","text":{"en":"`const w = items.map((el) => el.offsetWidth); items.forEach((el, i) => (el.style.height = w[i] / 2 + \"px\"));`","uk":"`const w = items.map((el) => el.offsetWidth); items.forEach((el, i) => (el.style.height = w[i] / 2 + \"px\"));`"}},{"id":"c","text":{"en":"`items.forEach((el) => el.classList.add(\"square\"));`","uk":"`items.forEach((el) => el.classList.add(\"square\"));`"}},{"id":"d","text":{"en":"`items.forEach((el) => (el.style.transform = \"scale(1.1)\"));`","uk":"`items.forEach((el) => (el.style.transform = \"scale(1.1)\"));`"}}]}'::jsonb, null::jsonb),
  ('sched-time-budget', 'quiz', 3, 75, '{"en":"When to yield","uk":"Коли поступатися потоком"}'::jsonb, '{"en":"A loop processes 100,000 items of varying cost. Why yield on a time budget (for example every 5–10 ms) instead of every 1,000 items?","uk":"Цикл обробляє 100 000 елементів різної вартості. Чому варто поступатися потоком за бюджетом часу (наприклад, кожні 5–10 мс), а не кожні 1000 елементів?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Item costs vary and devices differ, so a fixed count can produce long tasks on slow devices and needless yields on fast ones; a time budget adapts","uk":"Вартість елементів різна, і пристрої відрізняються, тож фіксована кількість може створювати довгі задачі на повільних пристроях і зайві поступки на швидких; бюджет часу підлаштовується"}},{"id":"b","text":{"en":"Reading `performance.now()` makes the loop faster","uk":"Читання `performance.now()` пришвидшує цикл"}},{"id":"c","text":{"en":"Browsers reject tasks that process more than 1,000 items","uk":"Браузери відхиляють задачі, що обробляють понад 1000 елементів"}},{"id":"d","text":{"en":"Time budgets avoid the need for `await`","uk":"Бюджет часу прибирає потребу в `await`"}}]}'::jsonb, null::jsonb),
  ('sched-background-tabs', 'quiz', 2, 60, '{"en":"Background tabs","uk":"Фонові вкладки"}'::jsonb, '{"en":"A dashboard polls with `setInterval(refresh, 1000)` and animates with `requestAnimationFrame`. What typically happens when the tab is in the background?","uk":"Дашборд опитує сервер через `setInterval(refresh, 1000)` і анімує через `requestAnimationFrame`. Що зазвичай стається, коли вкладка у фоні?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`requestAnimationFrame` callbacks pause, and timers are throttled (to about once per second, or less often after a while)","uk":"Колбеки `requestAnimationFrame` призупиняються, а таймери пригальмовуються (приблизно до одного разу на секунду, а з часом ще рідше)"}},{"id":"b","text":{"en":"Both keep running at full speed","uk":"Обидва продовжують працювати на повній швидкості"}},{"id":"c","text":{"en":"Both stop permanently until the page reloads","uk":"Обидва зупиняються назавжди до перезавантаження сторінки"}},{"id":"d","text":{"en":"`requestAnimationFrame` keeps running, and timers stop","uk":"`requestAnimationFrame` продовжує працювати, а таймери зупиняються"}}]}'::jsonb, null::jsonb),
  ('sched-worker-or-chunk', 'quiz', 3, 90, '{"en":"Chunking vs a worker","uk":"Розбиття на частини проти воркера"}'::jsonb, '{"en":"An app must `JSON.parse` a 40 MB response, which takes about 600 ms. How do you keep the page responsive?","uk":"Застосунок має виконати `JSON.parse` для відповіді розміром 40 МБ, що займає близько 600 мс. Як зберегти сторінку чутливою?"}'::jsonb, 'main-thread-scheduling', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Parse it in a Web Worker (or stream and process it incrementally), since one `JSON.parse` call can''t be split into chunks","uk":"Розібрати її у Web Worker (чи обробляти потоком поступово), бо один виклик `JSON.parse` не можна розбити на частини"}},{"id":"b","text":{"en":"Wrap `JSON.parse` in `setTimeout`","uk":"Загорнути `JSON.parse` у `setTimeout`"}},{"id":"c","text":{"en":"Call `JSON.parse` inside `requestIdleCallback`","uk":"Викликати `JSON.parse` усередині `requestIdleCallback`"}},{"id":"d","text":{"en":"Make the function that calls `JSON.parse` `async`","uk":"Зробити функцію, що викликає `JSON.parse`, `async`"}}]}'::jsonb, null::jsonb),
  ('sched-chunked-processing', 'practice', 3, 1200, '{"en":"Process big lists without freezing the page","uk":"Обробка великих списків без заморожування сторінки"}'::jsonb, '{"en":"Implement `processInChunks(items, fn, options)` in `src/chunks.ts`. It maps any iterable with `fn(item, index)` and returns the results in order, but never runs for longer than `budgetMs` (default 8) without yielding:\n\n- Check `now()` after each item; once the budget is used up **and items remain**, call `onProgress(done)`, `await yieldToMain()`, then start a new budget. Every chunk processes at least one item, even with a zero budget.\n- Call `onProgress(done)` once more at the end.\n- `signal`: reject with its reason if it''s already aborted (without calling `fn`), or at the next yield after it aborts.\n- `defaultYield()` uses `scheduler.yield()` when available, and falls back to `setTimeout(…, 0)`.\n\n`now` and `yieldToMain` are injectable for tests.","uk":"Реалізуйте `processInChunks(items, fn, options)` у `src/chunks.ts`. Функція перетворює будь-який ітерований об''єкт через `fn(item, index)` і повертає результати по порядку, але ніколи не працює довше за `budgetMs` (за замовчуванням 8) без поступки потоком:\n\n- Перевіряйте `now()` після кожного елемента; щойно бюджет вичерпано **й елементи лишаються**, викличте `onProgress(done)`, `await yieldToMain()` і почніть новий бюджет. Кожна частина обробляє щонайменше один елемент, навіть з нульовим бюджетом.\n- Викличте `onProgress(done)` ще раз у кінці.\n- `signal`: відхиляйтеся з його причиною, якщо він уже скасований (не викликаючи `fn`), або на наступній поступці після його скасування.\n- `defaultYield()` використовує `scheduler.yield()`, якщо він доступний, а інакше `setTimeout(…, 0)`.\n\n`now` і `yieldToMain` можна підмінити в тестах."}'::jsonb, 'main-thread-scheduling', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/chunks.ts":"export type ChunkOptions = {\n  /** Milliseconds of work before yielding. */\n  budgetMs?: number;\n  now?: () => number;\n  /** Gives the browser a chance to handle input and render. */\n  yieldToMain?: () => Promise<void>;\n  signal?: AbortSignal;\n  /** Called after each chunk with the number of items processed so far. */\n  onProgress?: (done: number) => void;\n};\n\nexport function defaultYield(): Promise<void> {\n  return new Promise((resolve) => setTimeout(resolve, 0)); // TODO: prefer scheduler.yield when available\n}\n\n/** Maps items with fn without blocking the main thread for longer than budgetMs at a time. */\nexport async function processInChunks<T, R>(items: Iterable<T>, fn: (item: T, index: number) => R, options: ChunkOptions = {}): Promise<R[]> {\n  // TODO: this blocks until everything is done\n  const results: R[] = [];\n  let i = 0;\n  for (const item of items) results.push(fn(item, i++));\n  options.onProgress?.(results.length);\n  return results;\n}\n","/index.ts":"import \"./styles.css\";\nimport { processInChunks } from \"./src/chunks\";\n\ndocument.getElementById(\"app\")!.innerHTML =\n  ''<h1>Chunked work</h1><button id=\"go\">Process 200,000 items</button> <button id=\"stop\">Stop</button><p id=\"status\">idle</p><p>Type here while it runs: <input /></p>'';\nconst status = document.getElementById(\"status\")!;\nlet controller: AbortController | null = null;\ndocument.getElementById(\"go\")!.addEventListener(\"click\", async () => {\n  controller = new AbortController();\n  const items = Array.from({ length: 200_000 }, (_, i) => i);\n  try {\n    const out = await processInChunks(items, (n) => Math.sqrt(n) * Math.sin(n), {\n      signal: controller.signal,\n      onProgress: (done) => (status.textContent = done + \" / \" + items.length),\n    });\n    status.textContent = \"done: \" + out.length;\n  } catch (e) {\n    status.textContent = \"stopped: \" + (e as Error).name;\n  }\n});\ndocument.getElementById(\"stop\")!.addEventListener(\"click\", () => controller?.abort());\n"},"visibleFiles":["/src/chunks.ts","/index.ts"],"activeFile":"/src/chunks.ts","tests":"import { describe, it, expect, fn } from \"./test-kit\";\nimport { processInChunks } from \"../src/chunks\";\n\nfunction fakeClock(stepPerItem) {\n  const clock = { t: 0 };\n  const work = fn((x) => {\n    clock.t += stepPerItem;\n    return x * 2;\n  });\n  return { clock, work, now: () => clock.t };\n}\n\ndescribe(\"processInChunks\", () => {\n  it(\"returns every result in order\", async () => {\n    const { work, now } = fakeClock(1);\n    const yields = fn(async () => {});\n    expect(await processInChunks([1, 2, 3], work, { now, yieldToMain: yields })).toEqual([2, 4, 6]);\n  });\n  it(\"yields when the time budget is used up\", async () => {\n    const { work, now } = fakeClock(3);\n    const yields = fn(async () => {});\n    const progress = [];\n    await processInChunks([1, 2, 3, 4, 5, 6, 7], work, { budgetMs: 8, now, yieldToMain: yields, onProgress: (d) => progress.push(d) });\n    expect(yields).toHaveBeenCalledTimes(2);\n    expect(progress).toEqual([3, 6, 7]);\n  });\n  it(\"doesn''t yield after the last item\", async () => {\n    const { work, now } = fakeClock(10);\n    const yields = fn(async () => {});\n    await processInChunks([1, 2, 3], work, { budgetMs: 5, now, yieldToMain: yields });\n    expect(yields).toHaveBeenCalledTimes(2);\n  });\n  it(\"still makes progress with a zero budget\", async () => {\n    const { work, now } = fakeClock(0);\n    const yields = fn(async () => {});\n    expect(await processInChunks([1, 2, 3, 4], work, { budgetMs: 0, now, yieldToMain: yields })).toEqual([2, 4, 6, 8]);\n    expect(yields).toHaveBeenCalledTimes(3);\n  });\n  it(\"works with any iterable and passes the index\", async () => {\n    const seen = [];\n    const result = await processInChunks(new Set([\"a\", \"b\"]), (x, i) => { seen.push(i); return x.toUpperCase(); }, { yieldToMain: async () => {} });\n    expect(result).toEqual([\"A\", \"B\"]);\n    expect(seen).toEqual([0, 1]);\n  });\n  it(\"stops at the next yield when aborted\", async () => {\n    const { work, now } = fakeClock(5);\n    const controller = new AbortController();\n    const yields = fn(async () => controller.abort(new Error(\"cancelled\")));\n    let error;\n    try {\n      await processInChunks([1, 2, 3, 4, 5, 6], work, { budgetMs: 8, now, yieldToMain: yields, signal: controller.signal });\n    } catch (e) {\n      error = e;\n    }\n    expect(error.message).toBe(\"cancelled\");\n    expect(work).toHaveBeenCalledTimes(2);\n  });\n  it(\"doesn''t start when already aborted\", async () => {\n    const work = fn((x) => x);\n    const controller = new AbortController();\n    controller.abort();\n    let error;\n    try {\n      await processInChunks([1], work, { signal: controller.signal });\n    } catch (e) {\n      error = e;\n    }\n    expect(error.name).toBe(\"AbortError\");\n    expect(work).toHaveBeenCalledTimes(0);\n  });\n  it(\"uses a real yield by default\", async () => {\n    let i = 0;\n    const result = await processInChunks([1, 2, 3], (x) => x + i++, { budgetMs: 0 });\n    expect(result).toEqual([1, 3, 5]);\n  });\n});\n","testCount":8}'::jsonb),
  ('sched-frame-batcher', 'practice', 3, 1200, '{"en":"A read/write batcher to avoid layout thrashing","uk":"Групування читань і записів проти layout thrashing"}'::jsonb, '{"en":"Implement `createFrameBatcher(requestFrame)` in `src/batcher.ts`, a small version of fastdom. It returns `measure(job)` (for DOM reads) and `mutate(job)` (for DOM writes), and both return a promise of the job''s result:\n\n- Jobs don''t run immediately: the first queued job requests **one** frame, and later jobs join that batch.\n- In the frame, run **all measures first**, then **all mutates**, each group in queue order, so layout is computed at most once.\n- Jobs queued while a frame is running (for example a `mutate` inside a `measure`) go to the **next** frame.\n- A job that throws rejects only its own promise; the rest still run.\n- No frame is requested when nothing is queued.\n\n`requestFrame` defaults to `requestAnimationFrame` and is injectable for tests.","uk":"Реалізуйте `createFrameBatcher(requestFrame)` у `src/batcher.ts`, маленьку версію fastdom. Функція повертає `measure(job)` (для читань DOM) і `mutate(job)` (для записів DOM), і обидва повертають проміс результату задачі:\n\n- Задачі не виконуються одразу: перша задача в черзі запитує **один** кадр, а пізніші приєднуються до цієї групи.\n- У кадрі спершу виконайте **всі measure**, потім **всі mutate**, кожну групу в порядку черги, тож розмітка обчислюється щонайбільше один раз.\n- Задачі, додані під час виконання кадру (наприклад, `mutate` усередині `measure`), переходять у **наступний** кадр.\n- Задача, що кидає помилку, відхиляє лише свій проміс; решта все одно виконується.\n- Коли черга порожня, кадр не запитується.\n\n`requestFrame` за замовчуванням дорівнює `requestAnimationFrame`, і його можна підмінити в тестах."}'::jsonb, 'main-thread-scheduling', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/batcher.ts":"type Job = () => unknown;\n\n/**\n * Batches DOM work per frame: in each frame, run every queued measure (read) first, then every mutate (write).\n * requestFrame defaults to requestAnimationFrame and is injectable for tests.\n */\nexport function createFrameBatcher(requestFrame: (cb: () => void) => void = (cb) => requestAnimationFrame(() => cb())) {\n  // TODO: runs jobs immediately, so reads and writes interleave and force layouts\n  return {\n    measure<T>(job: () => T): Promise<T> {\n      return Promise.resolve().then(job);\n    },\n    mutate<T>(job: () => T): Promise<T> {\n      return Promise.resolve().then(job);\n    },\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createFrameBatcher } from \"./src/batcher\";\n\nconst batcher = createFrameBatcher();\ndocument.getElementById(\"app\")!.innerHTML =\n  ''<h1>Read/write batching</h1><button id=\"go\">Square the boxes</button><div id=\"boxes\"></div><pre id=\"out\"></pre>'';\nconst boxes = document.getElementById(\"boxes\")!;\nfor (let i = 0; i < 20; i++) {\n  const div = document.createElement(\"div\");\n  div.style.cssText = \"display:inline-block;margin:2px;background:#8ab4f8;height:20px;width:\" + (20 + i * 4) + \"px\";\n  boxes.appendChild(div);\n}\ndocument.getElementById(\"go\")!.addEventListener(\"click\", async () => {\n  const start = performance.now();\n  await Promise.all(\n    [...boxes.children].map(async (el) => {\n      const width = await batcher.measure(() => (el as HTMLElement).offsetWidth);\n      await batcher.mutate(() => ((el as HTMLElement).style.height = width + \"px\"));\n    }),\n  );\n  document.getElementById(\"out\")!.textContent = \"done in \" + (performance.now() - start).toFixed(1) + \" ms\";\n});\n"},"visibleFiles":["/src/batcher.ts","/index.ts"],"activeFile":"/src/batcher.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { createFrameBatcher } from \"../src/batcher\";\n\nfunction setup() {\n  const frames = [];\n  const batcher = createFrameBatcher((cb) => frames.push(cb));\n  const nextFrame = async () => {\n    frames.shift()();\n    await Promise.resolve();\n    await Promise.resolve();\n  };\n  return { batcher, frames, nextFrame };\n}\n\ndescribe(\"createFrameBatcher\", () => {\n  it(\"waits for a frame and requests only one per batch\", async () => {\n    const { batcher, frames, nextFrame } = setup();\n    const log = [];\n    batcher.measure(() => log.push(\"read\"));\n    batcher.mutate(() => log.push(\"write\"));\n    batcher.measure(() => log.push(\"read 2\"));\n    await Promise.resolve();\n    expect(log).toEqual([]);\n    expect(frames.length).toBe(1);\n    await nextFrame();\n    expect(log.length).toBe(3);\n  });\n  it(\"runs all reads before all writes, each in order\", async () => {\n    const { batcher, nextFrame } = setup();\n    const log = [];\n    batcher.mutate(() => log.push(\"write A\"));\n    batcher.measure(() => log.push(\"read B\"));\n    batcher.mutate(() => log.push(\"write C\"));\n    batcher.measure(() => log.push(\"read D\"));\n    await nextFrame();\n    expect(log).toEqual([\"read B\", \"read D\", \"write A\", \"write C\"]);\n  });\n  it(\"resolves each job with its result\", async () => {\n    const { batcher, nextFrame } = setup();\n    const width = batcher.measure(() => 120);\n    const done = batcher.mutate(() => \"styled\");\n    await nextFrame();\n    expect(await width).toBe(120);\n    expect(await done).toBe(\"styled\");\n  });\n  it(\"defers jobs queued during a flush to the next frame\", async () => {\n    const { batcher, frames, nextFrame } = setup();\n    const log = [];\n    batcher.measure(() => {\n      log.push(\"read\");\n      batcher.mutate(() => log.push(\"write queued by read\"));\n    });\n    await nextFrame();\n    expect(log).toEqual([\"read\"]);\n    expect(frames.length).toBe(1);\n    await nextFrame();\n    expect(log).toEqual([\"read\", \"write queued by read\"]);\n  });\n  it(\"isolates errors\", async () => {\n    const { batcher, nextFrame } = setup();\n    const bad = batcher.measure(() => { throw new Error(\"layout failed\"); });\n    const good = batcher.mutate(() => \"ok\");\n    const outcome = bad.then(() => \"resolved\", (e) => e.message);\n    await nextFrame();\n    expect(await outcome).toBe(\"layout failed\");\n    expect(await good).toBe(\"ok\");\n  });\n  it(\"doesn''t request frames when idle\", async () => {\n    const { batcher, frames, nextFrame } = setup();\n    batcher.measure(() => 1);\n    await nextFrame();\n    expect(frames.length).toBe(0);\n  });\n});\n","testCount":6}'::jsonb),
  ('mjs-default-null', 'quiz', 1, 45, '{"en":"When do parameter defaults apply?","uk":"Коли застосовуються значення параметрів за замовчуванням?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"function greet(name = \"guest\") {\n  return name;\n}\nconsole.log([greet(undefined), greet(null), greet(\"\")]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''guest'', null, '''' ]`","uk":"`[ ''guest'', null, '''' ]`"}},{"id":"b","text":{"en":"`[ ''guest'', ''guest'', ''guest'' ]`","uk":"`[ ''guest'', ''guest'', ''guest'' ]`"}},{"id":"c","text":{"en":"`[ ''guest'', ''guest'', '''' ]`","uk":"`[ ''guest'', ''guest'', '''' ]`"}},{"id":"d","text":{"en":"`[ undefined, null, '''' ]`","uk":"`[ undefined, null, '''' ]`"}}]}'::jsonb, null::jsonb),
  ('mjs-destructure-defaults', 'quiz', 2, 60, '{"en":"Destructuring defaults","uk":"Значення за замовчуванням у деструктуризації"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const { a = 1, b = 2, c = 3 } = { a: null, b: undefined, c: 0 };\nconsole.log(a, b, c);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`null 2 0`","uk":"`null 2 0`"}},{"id":"b","text":{"en":"`1 2 3`","uk":"`1 2 3`"}},{"id":"c","text":{"en":"`1 2 0`","uk":"`1 2 0`"}},{"id":"d","text":{"en":"`null undefined 0`","uk":"`null undefined 0`"}}]}'::jsonb, null::jsonb),
  ('mjs-nullish-vs-or', 'quiz', 1, 60, '{"en":"`??` vs `||`","uk":"`??` проти `||`"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const s = { volume: 0, title: \"\" };\nconsole.log([s.volume || 50, s.volume ?? 50, s.title || \"Untitled\", s.title ?? \"Untitled\"]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 50, 0, ''Untitled'', '''' ]`","uk":"`[ 50, 0, ''Untitled'', '''' ]`"}},{"id":"b","text":{"en":"`[ 50, 50, ''Untitled'', ''Untitled'' ]`","uk":"`[ 50, 50, ''Untitled'', ''Untitled'' ]`"}},{"id":"c","text":{"en":"`[ 0, 0, '''', '''' ]`","uk":"`[ 0, 0, '''', '''' ]`"}},{"id":"d","text":{"en":"`[ 0, 50, '''', ''Untitled'' ]`","uk":"`[ 0, 50, '''', ''Untitled'' ]`"}}]}'::jsonb, null::jsonb),
  ('mjs-spread-shallow', 'quiz', 2, 60, '{"en":"How deep does spread copy?","uk":"Наскільки глибоко копіює spread?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const base = { tags: [\"a\"], n: 1 };\nconst copy = { ...base };\ncopy.tags.push(\"b\");\ncopy.n = 2;\nconsole.log(base.tags, base.n);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''a'', ''b'' ] 1`","uk":"`[ ''a'', ''b'' ] 1`"}},{"id":"b","text":{"en":"`[ ''a'' ] 1`","uk":"`[ ''a'' ] 1`"}},{"id":"c","text":{"en":"`[ ''a'', ''b'' ] 2`","uk":"`[ ''a'', ''b'' ] 2`"}},{"id":"d","text":{"en":"`[ ''a'' ] 2`","uk":"`[ ''a'' ] 2`"}}]}'::jsonb, null::jsonb),
  ('mjs-spread-undefined-overrides', 'quiz', 2, 75, '{"en":"Merging options with spread","uk":"Злиття опцій через spread"}'::jsonb, '{"en":"A function merges user options over defaults. What does this print?","uk":"Функція зливає опції користувача поверх значень за замовчуванням. Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const defaults = { retries: 3, timeout: 1000 };\nconst user = { retries: undefined };\nconst cfg = { ...defaults, ...user };\nconsole.log(cfg.retries, cfg.timeout);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`undefined 1000`","uk":"`undefined 1000`"}},{"id":"b","text":{"en":"`3 1000`","uk":"`3 1000`"}},{"id":"c","text":{"en":"`undefined undefined`","uk":"`undefined undefined`"}},{"id":"d","text":{"en":"`3 undefined`","uk":"`3 undefined`"}}]}'::jsonb, null::jsonb),
  ('mjs-destructure-iterables', 'quiz', 3, 75, '{"en":"Array destructuring takes any iterable","uk":"Деструктуризація масиву приймає будь-який ітерований об''єкт"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const [a, b] = new Set([\"x\", \"y\", \"x\"]);\nconst [c, ...d] = \"hey\";\nconsole.log(a, b, c, d);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`x y h [ ''e'', ''y'' ]`","uk":"`x y h [ ''e'', ''y'' ]`"}},{"id":"b","text":{"en":"`x x h ey`","uk":"`x x h ey`"}},{"id":"c","text":{"en":"A `TypeError`: a Set isn''t an array","uk":"`TypeError`: Set не є масивом"}},{"id":"d","text":{"en":"`undefined undefined h [ ''e'', ''y'' ]`","uk":"`undefined undefined h [ ''e'', ''y'' ]`"}}]}'::jsonb, null::jsonb),
  ('mjs-default-per-call', 'quiz', 2, 60, '{"en":"Are defaults shared between calls?","uk":"Чи спільні значення за замовчуванням між викликами?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"function add(item, list = []) {\n  list.push(item);\n  return list;\n}\nconsole.log(add(1), add(2));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 1 ] [ 2 ]`","uk":"`[ 1 ] [ 2 ]`"}},{"id":"b","text":{"en":"`[ 1 ] [ 1, 2 ]`","uk":"`[ 1 ] [ 1, 2 ]`"}},{"id":"c","text":{"en":"`[ 1, 2 ] [ 1, 2 ]`","uk":"`[ 1, 2 ] [ 1, 2 ]`"}},{"id":"d","text":{"en":"`undefined undefined`","uk":"`undefined undefined`"}}]}'::jsonb, null::jsonb),
  ('mjs-function-length', 'quiz', 3, 75, '{"en":"`length` with defaults and rest","uk":"`length` зі значеннями за замовчуванням і rest"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"console.log(((a, b = 1, c) => {}).length, ((...args) => {}).length, (({ x }, y) => {}).length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 0 2`","uk":"`1 0 2`"}},{"id":"b","text":{"en":"`3 1 2`","uk":"`3 1 2`"}},{"id":"c","text":{"en":"`2 0 2`","uk":"`2 0 2`"}},{"id":"d","text":{"en":"`1 1 1`","uk":"`1 1 1`"}}]}'::jsonb, null::jsonb),
  ('mjs-optional-chaining-short-circuit', 'quiz', 3, 90, '{"en":"How far does `?.` short-circuit?","uk":"Наскільки далеко обриває ланцюжок `?.`?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"let calls = 0;\nconst next = () => {\n  calls++;\n  return 1;\n};\nconst user = null;\nconst result = user?.profile.name.toUpperCase(next());\nconsole.log(result, calls);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`undefined 0`","uk":"`undefined 0`"}},{"id":"b","text":{"en":"`undefined 1`","uk":"`undefined 1`"}},{"id":"c","text":{"en":"A `TypeError` from reading `.name`","uk":"`TypeError` під час читання `.name`"}},{"id":"d","text":{"en":"`null 0`","uk":"`null 0`"}}]}'::jsonb, null::jsonb),
  ('mjs-default-param-tdz', 'quiz', 4, 90, '{"en":"Defaults that refer to other parameters","uk":"Значення за замовчуванням, що посилаються на інші параметри"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"function f(a = b, b = 2) {\n  return [a, b];\n}\nconst out = [];\ntry {\n  out.push(f(1));\n  out.push(f());\n} catch (e) {\n  out.push(e.constructor.name);\n}\nconsole.log(out);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ [ 1, 2 ], ''ReferenceError'' ]`","uk":"`[ [ 1, 2 ], ''ReferenceError'' ]`"}},{"id":"b","text":{"en":"`[ [ 1, 2 ], [ undefined, 2 ] ]`","uk":"`[ [ 1, 2 ], [ undefined, 2 ] ]`"}},{"id":"c","text":{"en":"`[ [ 1, 2 ], [ 2, 2 ] ]`","uk":"`[ [ 1, 2 ], [ 2, 2 ] ]`"}},{"id":"d","text":{"en":"`[ ''ReferenceError'' ]`","uk":"`[ ''ReferenceError'' ]`"}}]}'::jsonb, null::jsonb),
  ('mjs-tagged-template-raw', 'quiz', 4, 120, '{"en":"Inside a tagged template","uk":"Усередині тегованого шаблону"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"const tag = (strings, ...values) => strings.raw.join(\"|\") + \" \" + values.length;\nconsole.log(tag`a${1}\\nb${2}`);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`a|\\nb| 2`","uk":"`a|\\nb| 2`"}},{"id":"b","text":{"en":"`a|b 2`","uk":"`a|b 2`"}},{"id":"c","text":{"en":"`a|1|\\nb|2 0`","uk":"`a|1|\\nb|2 0`"}},{"id":"d","text":{"en":"`a|\\nb 2`","uk":"`a|\\nb 2`"}}]}'::jsonb, null::jsonb),
  ('mjs-logical-assignment', 'quiz', 4, 120, '{"en":"Logical assignment and setters","uk":"Логічне присвоєння й сетери"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'modern-js-syntax', '{"mode":"single","code":"let sets = 0;\nconst o = {\n  _v: \"x\",\n  get v() { return this._v; },\n  set v(x) { sets++; this._v = x; },\n};\no.v ??= \"y\";\no.v ||= \"z\";\no.v &&= \"w\";\nconsole.log(o.v, sets);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`w 1`","uk":"`w 1`"}},{"id":"b","text":{"en":"`w 3`","uk":"`w 3`"}},{"id":"c","text":{"en":"`z 2`","uk":"`z 2`"}},{"id":"d","text":{"en":"`x 0`","uk":"`x 0`"}}]}'::jsonb, null::jsonb),
  ('mjs-path-get-set', 'practice', 3, 1200, '{"en":"Safe nested reads and immutable writes","uk":"Безпечне вкладене читання й незмінний запис"}'::jsonb, '{"en":"Implement two helpers in `src/path.ts`. A path is a string like `\"users[0].tags[1]\"` (bracketed digits are array indexes) or an array of keys like `[\"users\", 0, \"name\"]`.\n\n- `getPath(obj, path, fallback?)` reads a nested value. It never throws on missing branches, and returns `fallback` **only when the result is `undefined`** (`0`, `\"\"` and `null` are real values).\n- `setPath(obj, path, value)` returns an updated **copy** without mutating `obj`:\n  - Copy only the objects and arrays along the path; every other branch keeps its reference (structural sharing, as Redux and React expect).\n  - Arrays stay arrays.\n  - Missing branches are created: an array when the next key is a number, otherwise an object.\n  - If the value is already there (`Object.is`), return the original `obj`.","uk":"Реалізуйте два помічники в `src/path.ts`. Шлях є рядком на кшталт `\"users[0].tags[1]\"` (цифри в дужках є індексами масиву) або масивом ключів на кшталт `[\"users\", 0, \"name\"]`.\n\n- `getPath(obj, path, fallback?)` читає вкладене значення. Вона ніколи не кидає помилку на відсутніх гілках і повертає `fallback` **лише коли результат `undefined`** (`0`, `\"\"` і `null` є справжніми значеннями).\n- `setPath(obj, path, value)` повертає оновлену **копію**, не змінюючи `obj`:\n  - Копіюйте лише об''єкти й масиви вздовж шляху; кожна інша гілка зберігає своє посилання (структурне спільне використання, як очікують Redux і React).\n  - Масиви лишаються масивами.\n  - Відсутні гілки створюються: масив, коли наступний ключ є числом, інакше об''єкт.\n  - Якщо значення вже таке (`Object.is`), поверніть початковий `obj`."}'::jsonb, 'modern-js-syntax', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/path.ts":"export type Path = string | Array<string | number>;\n\n/** Reads a nested value, e.g. getPath(state, \"users[0].name\", \"anonymous\"). */\nexport function getPath(obj: unknown, path: Path, fallback?: unknown): unknown {\n  // TODO: brackets, array paths, missing branches and the fallback\n  let current: any = obj;\n  for (const key of String(path).split(\".\")) current = current[key];\n  return current;\n}\n\n/** Returns a copy of obj with the value at path replaced. obj must not change. */\nexport function setPath<T>(obj: T, path: Path, value: unknown): T {\n  // TODO: this mutates the original and can''t create missing branches\n  const keys = String(path).split(\".\");\n  let current: any = obj;\n  for (const key of keys.slice(0, -1)) current = current[key];\n  current[keys[keys.length - 1]] = value;\n  return obj;\n}\n","/index.ts":"import \"./styles.css\";\nimport { getPath, setPath } from \"./src/path\";\n\nconst state = { users: [{ name: \"Ada\", tags: [\"admin\"] }], settings: { theme: \"dark\" } };\nconst lines: string[] = [];\ntry {\n  lines.push(\"users[0].name → \" + String(getPath(state, \"users[0].name\")));\n  lines.push(\"users[3].name → \" + String(getPath(state, \"users[3].name\", \"nobody\")));\n  const next = setPath(state, \"users[0].tags[1]\", \"editor\");\n  lines.push(\"new tags: \" + JSON.stringify(getPath(next, \"users[0].tags\")));\n  lines.push(\"old tags: \" + JSON.stringify(state.users[0].tags));\n} catch (e) {\n  lines.push(\"error: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Paths</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/path.ts","/index.ts"],"activeFile":"/src/path.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { getPath, setPath } from \"../src/path\";\n\nconst state = () => ({ users: [{ name: \"Ada\", tags: [\"admin\"] }, { name: \"Bob\", tags: [] }], settings: { theme: \"dark\", volume: 0 } });\n\ndescribe(\"getPath\", () => {\n  it(\"reads dotted and bracketed paths\", () => {\n    expect(getPath(state(), \"users[1].name\")).toBe(\"Bob\");\n    expect(getPath(state(), \"users[0].tags[0]\")).toBe(\"admin\");\n    expect(getPath(state(), [\"settings\", \"theme\"])).toBe(\"dark\");\n  });\n  it(\"returns the fallback for missing branches instead of throwing\", () => {\n    expect(getPath(state(), \"users[5].name\", \"nobody\")).toBe(\"nobody\");\n    expect(getPath(state(), \"profile.address.city\")).toBeUndefined();\n    expect(getPath(null, \"a.b\", 1)).toBe(1);\n  });\n  it(\"only falls back for undefined, not other falsy values\", () => {\n    expect(getPath(state(), \"settings.volume\", 50)).toBe(0);\n    expect(getPath({ a: null }, \"a\", \"x\")).toBeNull();\n  });\n});\n\ndescribe(\"setPath\", () => {\n  it(\"returns an updated copy without mutating the original\", () => {\n    const before = state();\n    const after = setPath(before, \"users[0].name\", \"Ada L.\");\n    expect(getPath(after, \"users[0].name\")).toBe(\"Ada L.\");\n    expect(before.users[0].name).toBe(\"Ada\");\n  });\n  it(\"copies only the changed branch and shares the rest\", () => {\n    const before = state();\n    const after = setPath(before, \"users[0].name\", \"Ada L.\");\n    expect(after).not.toBe(before);\n    expect(after.users).not.toBe(before.users);\n    expect(after.users[1]).toBe(before.users[1]);\n    expect(after.settings).toBe(before.settings);\n  });\n  it(\"keeps arrays as arrays\", () => {\n    const after = setPath(state(), \"users[1].tags[0]\", \"new\");\n    expect(Array.isArray(after.users)).toBe(true);\n    expect(after.users[1].tags).toEqual([\"new\"]);\n  });\n  it(\"creates missing branches: arrays for numeric keys, objects otherwise\", () => {\n    const after = setPath({}, \"a.list[1].b\", 1);\n    expect(Array.isArray(after.a.list)).toBe(true);\n    expect(after.a.list[1]).toEqual({ b: 1 });\n    expect(after.a.list.length).toBe(2);\n  });\n  it(\"returns the same object when nothing changes\", () => {\n    const before = state();\n    expect(setPath(before, \"settings.theme\", \"dark\")).toBe(before);\n  });\n});\n","testCount":8}'::jsonb),
  ('mjs-sql-tag', 'practice', 4, 1320, '{"en":"A safe `sql` tagged template","uk":"Безпечний тегований шаблон `sql`"}'::jsonb, '{"en":"Libraries like `postgres` and `slonik` let you write ``sql`SELECT * FROM users WHERE id = ${id}` `` safely. Implement `sql` and `toQuery(fragment)` in `src/sql.ts`. `toQuery` returns `{ text, values }`, where values become numbered placeholders (`$1`, `$2`, …) and **never** go into the SQL text.\n\n- Fragments created with `sql` can be nested inside other fragments; their text is inlined and numbering continues across the whole query.\n- Arrays expand to a list of placeholders (`IN (${ids})` → `IN ($1, $2, $3)`). An empty array throws a `RangeError`.\n- `undefined` throws a `TypeError` (it''s almost always a bug); `null` and `false` are fine.\n- Only objects created by your `sql` tag count as fragments: a plain object that merely looks like one (for example, parsed from a request body) must be treated as a value.","uk":"Бібліотеки на кшталт `postgres` і `slonik` дають безпечно писати ``sql`SELECT * FROM users WHERE id = ${id}` ``. Реалізуйте `sql` і `toQuery(fragment)` у `src/sql.ts`. `toQuery` повертає `{ text, values }`, де значення стають нумерованими заповнювачами (`$1`, `$2`, …) і **ніколи** не потрапляють у текст SQL.\n\n- Фрагменти, створені через `sql`, можна вкладати в інші фрагменти; їхній текст вбудовується, а нумерація продовжується по всьому запиту.\n- Масиви розгортаються в список заповнювачів (`IN (${ids})` → `IN ($1, $2, $3)`). Порожній масив кидає `RangeError`.\n- `undefined` кидає `TypeError` (це майже завжди помилка); `null` і `false` допустимі.\n- Фрагментами вважаються лише об''єкти, створені вашим тегом `sql`: звичайний об''єкт, що лише схожий на фрагмент (наприклад, розібраний із тіла запиту), треба обробляти як значення."}'::jsonb, 'modern-js-syntax', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/sql.ts":"export type Query = { text: string; values: unknown[] };\n\n/** Tag: sql`SELECT * FROM users WHERE id = ${id}` */\nexport function sql(strings: TemplateStringsArray, ...values: unknown[]) {\n  return { strings, values };\n}\n\n/** Turns a fragment into parameterised SQL: { text: \"… WHERE id = $1\", values: [id] }. */\nexport function toQuery(fragment: { strings: readonly string[]; values: unknown[] }): Query {\n  // TODO: this pastes values into the SQL text (SQL injection!)\n  let text = fragment.strings[0];\n  fragment.values.forEach((value, i) => {\n    text += String(value) + fragment.strings[i + 1];\n  });\n  return { text, values: [] };\n}\n","/index.ts":"import \"./styles.css\";\nimport { sql, toQuery } from \"./src/sql\";\n\nconst name = \"Robert''); DROP TABLE students;--\";\nconst ids = [1, 2, 3];\nconst active = sql`active = ${true}`;\nlet output: string;\ntry {\n  const q = toQuery(sql`SELECT * FROM students WHERE name = ${name} AND id IN (${ids}) AND ${active}`);\n  output = q.text + \"\\n\" + JSON.stringify(q.values);\n} catch (e) {\n  output = \"error: \" + (e as Error).message;\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Parameterised SQL</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = output;\n"},"visibleFiles":["/src/sql.ts","/index.ts"],"activeFile":"/src/sql.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { sql, toQuery } from \"../src/sql\";\n\ndescribe(\"sql tag\", () => {\n  it(\"turns values into numbered placeholders\", () => {\n    const id = 7;\n    const status = \"active\";\n    expect(toQuery(sql`SELECT * FROM users WHERE id = ${id} AND status = ${status}`)).toEqual({\n      text: \"SELECT * FROM users WHERE id = $1 AND status = $2\",\n      values: [7, \"active\"],\n    });\n  });\n  it(\"never puts values into the SQL text\", () => {\n    const evil = \"x''; DROP TABLE users;--\";\n    const q = toQuery(sql`SELECT * FROM users WHERE name = ${evil}`);\n    expect(q.text).toBe(\"SELECT * FROM users WHERE name = $1\");\n    expect(q.values).toEqual([evil]);\n  });\n  it(\"inlines nested fragments and keeps numbering going\", () => {\n    const filter = sql`age > ${18} AND country = ${\"UA\"}`;\n    const q = toQuery(sql`SELECT * FROM users WHERE id <> ${1} AND ${filter} LIMIT ${10}`);\n    expect(q.text).toBe(\"SELECT * FROM users WHERE id <> $1 AND age > $2 AND country = $3 LIMIT $4\");\n    expect(q.values).toEqual([1, 18, \"UA\", 10]);\n  });\n  it(\"expands arrays into a list of placeholders\", () => {\n    const q = toQuery(sql`SELECT * FROM users WHERE id IN (${[4, 5, 6]})`);\n    expect(q.text).toBe(\"SELECT * FROM users WHERE id IN ($1, $2, $3)\");\n    expect(q.values).toEqual([4, 5, 6]);\n  });\n  it(\"rejects empty lists and undefined values\", () => {\n    expect(() => toQuery(sql`SELECT 1 WHERE id IN (${[]})`)).toThrow(RangeError);\n    expect(() => toQuery(sql`SELECT 1 WHERE id = ${undefined}`)).toThrow(TypeError);\n  });\n  it(\"treats look-alike objects from outside as plain values\", () => {\n    const fake = { strings: [\"1=1 OR \"], values: [] };\n    const q = toQuery(sql`SELECT * FROM t WHERE data = ${fake}`);\n    expect(q.text).toBe(\"SELECT * FROM t WHERE data = $1\");\n    expect(q.values).toEqual([fake]);\n  });\n  it(\"keeps null and false as parameters\", () => {\n    expect(toQuery(sql`UPDATE t SET a = ${null}, b = ${false}`).values).toEqual([null, false]);\n  });\n});\n","testCount":7}'::jsonb),
  ('mod-iife-private', 'quiz', 1, 60, '{"en":"State inside an IIFE","uk":"Стан усередині IIFE"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"const counter = (function () {\n  let count = 0;\n  return {\n    inc() {\n      return ++count;\n    },\n  };\n})();\ncounter.inc();\nconsole.log(counter.inc(), typeof count);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`2 undefined`","uk":"`2 undefined`"}},{"id":"b","text":{"en":"`1 number`","uk":"`1 number`"}},{"id":"c","text":{"en":"`2 number`","uk":"`2 number`"}},{"id":"d","text":{"en":"A `ReferenceError`: count is not defined","uk":"`ReferenceError`: count is not defined"}}]}'::jsonb, null::jsonb),
  ('mod-iife-forms', 'quiz', 2, 75, '{"en":"Valid IIFE syntax","uk":"Коректний синтаксис IIFE"}'::jsonb, '{"en":"Which of these are valid immediately invoked function expressions?","uk":"Що з цього є коректними функціональними виразами, що викликаються одразу?"}'::jsonb, 'module-pattern', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`(function () { … })();`","uk":"`(function () { … })();`"}},{"id":"b","text":{"en":"`(function () { … }());`","uk":"`(function () { … }());`"}},{"id":"c","text":{"en":"`!function () { … }();`","uk":"`!function () { … }();`"}},{"id":"d","text":{"en":"`function () { … }();`","uk":"`function () { … }();`"}}]}'::jsonb, null::jsonb),
  ('mod-singleton-vs-factory', 'quiz', 2, 75, '{"en":"A singleton and a factory","uk":"Синглтон і фабрика"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"const shared = (() => {\n  let n = 0;\n  return { inc: () => ++n };\n})();\nconst create = () => {\n  let n = 0;\n  return { inc: () => ++n };\n};\nconst a = create();\nconst b = create();\nshared.inc();\nshared.inc();\na.inc();\nconsole.log(shared.inc(), a.inc(), b.inc());","codeLanguage":"js","options":[{"id":"a","text":{"en":"`3 2 1`","uk":"`3 2 1`"}},{"id":"b","text":{"en":"`3 3 3`","uk":"`3 3 3`"}},{"id":"c","text":{"en":"`1 1 1`","uk":"`1 1 1`"}},{"id":"d","text":{"en":"`3 2 2`","uk":"`3 2 2`"}}]}'::jsonb, null::jsonb),
  ('mod-revealing-patch', 'quiz', 3, 90, '{"en":"Patching a revealing module","uk":"Заміна методу в revealing module"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"const cart = (() => {\n  const items = [];\n  function add(item) {\n    items.push(item);\n    return total();\n  }\n  function total() {\n    return items.length;\n  }\n  return { add, total };\n})();\ncart.total = () => 99;\nconsole.log(cart.add(\"apple\"), cart.total());","codeLanguage":"js","options":[{"id":"a","text":{"en":"`1 99`","uk":"`1 99`"}},{"id":"b","text":{"en":"`99 99`","uk":"`99 99`"}},{"id":"c","text":{"en":"`1 1`","uk":"`1 1`"}},{"id":"d","text":{"en":"A `TypeError`: cannot assign to total","uk":"`TypeError`: cannot assign to total"}}]}'::jsonb, null::jsonb),
  ('mod-leaking-internals', 'quiz', 2, 75, '{"en":"Returning internal state","uk":"Повернення внутрішнього стану"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"function createTodos() {\n  const items = [];\n  return {\n    add(text) {\n      items.push(text);\n    },\n    all() {\n      return items;\n    },\n  };\n}\nconst todos = createTodos();\ntodos.add(\"a\");\ntodos.all().push(\"x\");\nconsole.log(todos.all());","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ ''a'', ''x'' ]`","uk":"`[ ''a'', ''x'' ]`"}},{"id":"b","text":{"en":"`[ ''a'' ]`","uk":"`[ ''a'' ]`"}},{"id":"c","text":{"en":"A `TypeError`: the array is private","uk":"`TypeError`: масив приватний"}},{"id":"d","text":{"en":"`[ ''x'' ]`","uk":"`[ ''x'' ]`"}}]}'::jsonb, null::jsonb),
  ('mod-weakmap-private', 'quiz', 3, 90, '{"en":"Private data in a WeakMap","uk":"Приватні дані у WeakMap"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"const priv = new WeakMap();\nclass Account {\n  constructor(balance) {\n    priv.set(this, { balance });\n  }\n  get balance() {\n    return priv.get(this).balance;\n  }\n}\nconst acc = new Account(10);\nconsole.log(acc.balance, Object.keys(acc), JSON.stringify(acc), Reflect.ownKeys(acc).length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`10 [] {} 0`","uk":"`10 [] {} 0`"}},{"id":"b","text":{"en":"`10 [ ''balance'' ] {\"balance\":10} 1`","uk":"`10 [ ''balance'' ] {\"balance\":10} 1`"}},{"id":"c","text":{"en":"`undefined [] {} 0`","uk":"`undefined [] {} 0`"}},{"id":"d","text":{"en":"`10 [] {} 1`","uk":"`10 [] {} 1`"}}]}'::jsonb, null::jsonb),
  ('mod-symbol-not-private', 'quiz', 2, 60, '{"en":"Are symbol keys private?","uk":"Чи приватні ключі-символи?"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"const secret = Symbol(\"secret\");\nconst obj = { [secret]: 42 };\nconst [key] = Object.getOwnPropertySymbols(obj);\nconsole.log(obj[key], Object.keys(obj).length);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`42 0`","uk":"`42 0`"}},{"id":"b","text":{"en":"`undefined 0`","uk":"`undefined 0`"}},{"id":"c","text":{"en":"`42 1`","uk":"`42 1`"}},{"id":"d","text":{"en":"A `TypeError`: symbols are private","uk":"`TypeError`: символи приватні"}}]}'::jsonb, null::jsonb),
  ('mod-detached-methods', 'quiz', 2, 75, '{"en":"Passing methods around","uk":"Передавання методів"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'module-pattern', '{"mode":"single","code":"function createCounter() {\n  let n = 0;\n  return {\n    inc() {\n      return ++n;\n    },\n  };\n}\nclass Counter {\n  n = 0;\n  inc() {\n    return ++this.n;\n  }\n}\nconst f = createCounter().inc;\nconst c = new Counter().inc;\nconst out = [f()];\ntry {\n  out.push(c());\n} catch (e) {\n  out.push(e.name);\n}\nconsole.log(out);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ 1, ''TypeError'' ]`","uk":"`[ 1, ''TypeError'' ]`"}},{"id":"b","text":{"en":"`[ 1, 1 ]`","uk":"`[ 1, 1 ]`"}},{"id":"c","text":{"en":"`[ ''TypeError'', ''TypeError'' ]`","uk":"`[ ''TypeError'', ''TypeError'' ]`"}},{"id":"d","text":{"en":"`[ 1, NaN ]`","uk":"`[ 1, NaN ]`"}}]}'::jsonb, null::jsonb),
  ('mod-esm-singleton-server', 'quiz', 3, 90, '{"en":"Module-level state on a server","uk":"Стан рівня модуля на сервері"}'::jsonb, '{"en":"A Node.js API has `cart.js` with `const items = []; export function addToCart(item) { items.push(item); } export function getCart() { return items; }`, used by request handlers. What''s wrong?","uk":"API на Node.js має `cart.js` з `const items = []; export function addToCart(item) { items.push(item); } export function getCart() { return items; }`, що використовують обробники запитів. Що не так?"}'::jsonb, 'module-pattern', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A module is evaluated once per process, so every request and every user shares one `items` array: users see each other''s carts","uk":"Модуль обчислюється один раз на процес, тож кожен запит і кожен користувач ділять один масив `items`: користувачі бачать кошики одне одного"}},{"id":"b","text":{"en":"Each import gets its own copy of `items`, so the cart is always empty","uk":"Кожен імпорт отримує власну копію `items`, тож кошик завжди порожній"}},{"id":"c","text":{"en":"ES modules can''t contain mutable state","uk":"ES-модулі не можуть містити змінний стан"}},{"id":"d","text":{"en":"Nothing, as long as the server runs a single process","uk":"Нічого, якщо сервер працює в одному процесі"}}]}'::jsonb, null::jsonb),
  ('mod-cjs-wrapper', 'quiz', 3, 90, '{"en":"What Node does with a CommonJS file","uk":"Що Node робить із файлом CommonJS"}'::jsonb, '{"en":"Why are top-level variables in a CommonJS module private to that file, and where do `require`, `module` and `__dirname` come from?","uk":"Чому змінні верхнього рівня в модулі CommonJS приватні для цього файлу і звідки беруться `require`, `module` і `__dirname`?"}'::jsonb, 'module-pattern', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Node wraps the file''s code in a function `(exports, require, module, __filename, __dirname) => { … }` and calls it once: the module pattern, applied for you","uk":"Node загортає код файлу у функцію `(exports, require, module, __filename, __dirname) => { … }` і викликає її один раз: шаблон модуля, застосований за вас"}},{"id":"b","text":{"en":"They''re globals that Node creates for each file","uk":"Це глобальні змінні, які Node створює для кожного файлу"}},{"id":"c","text":{"en":"The V8 engine gives every file a separate global object","uk":"Рушій V8 дає кожному файлу окремий глобальний об''єкт"}},{"id":"d","text":{"en":"`var` declarations are automatically converted to `let`","uk":"Оголошення `var` автоматично перетворюються на `let`"}}]}'::jsonb, null::jsonb),
  ('mod-session-manager', 'practice', 3, 1200, '{"en":"A tamper-proof session manager","uk":"Менеджер сесій, захищений від втручання"}'::jsonb, '{"en":"Rewrite `createSessionManager({ ttlMs, now, generateId })` in `src/sessions.ts` as a proper module factory. Its state must be private, and nothing it returns may be usable to change that state:\n\n- The returned API object is **frozen** and exposes only the methods `create`, `get`, `touch`, `revoke`, `revokeAll`, `activeCount` and `sessionsFor`. No map or other internals are reachable (`JSON.stringify(api)` is `\"{}\"`).\n- `create(userId)` returns `{ id, userId, createdAt, expiresAt }` using the injected `generateId` and `now`, and throws a `TypeError` for an empty `userId`.\n- Sessions handed out are **frozen copies**: mutating them throws, and `sessionsFor` returns a fresh array each time.\n- Expired sessions (`expiresAt <= now()`) are invisible: `get` returns `undefined`, `touch` returns `false`, `activeCount` doesn''t count them. `touch` extends a live session by `ttlMs` from now.\n- `revoke(id)` returns whether a session was removed; `revokeAll(userId)` returns how many were removed.\n- Separate managers don''t share anything.","uk":"Перепишіть `createSessionManager({ ttlMs, now, generateId })` у `src/sessions.ts` як правильну фабрику модулів. Її стан має бути приватним, і ніщо з того, що вона повертає, не повинно дозволяти змінити цей стан:\n\n- Повернений об''єкт API **заморожений** і показує лише методи `create`, `get`, `touch`, `revoke`, `revokeAll`, `activeCount` і `sessionsFor`. Жодна мапа чи інші внутрішні деталі недосяжні (`JSON.stringify(api)` дорівнює `\"{}\"`).\n- `create(userId)` повертає `{ id, userId, createdAt, expiresAt }`, використовуючи підмінні `generateId` і `now`, і кидає `TypeError` для порожнього `userId`.\n- Видані сесії є **замороженими копіями**: їхня зміна кидає помилку, а `sessionsFor` щоразу повертає новий масив.\n- Прострочені сесії (`expiresAt <= now()`) невидимі: `get` повертає `undefined`, `touch` повертає `false`, `activeCount` їх не рахує. `touch` подовжує живу сесію на `ttlMs` від поточного моменту.\n- `revoke(id)` повертає, чи сесію видалено; `revokeAll(userId)` повертає, скільки сесій видалено.\n- Окремі менеджери нічого не ділять між собою."}'::jsonb, 'module-pattern', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/sessions.ts":"export type Session = Readonly<{ id: string; userId: string; createdAt: number; expiresAt: number }>;\n\nexport type SessionOptions = { ttlMs?: number; now?: () => number; generateId?: () => string };\n\n/**\n * A session store with private state. Only the returned methods can touch the sessions,\n * and nothing returned to callers can be used to change them.\n */\nexport function createSessionManager({ ttlMs = 30 * 60_000, now = () => Date.now(), generateId = () => crypto.randomUUID() }: SessionOptions = {}) {\n  // TODO: the map is public, sessions are returned by reference, and nothing expires\n  const sessions = new Map<string, any>();\n  return {\n    sessions,\n    create(userId: string) {\n      const session = { id: generateId(), userId, createdAt: now(), expiresAt: now() + ttlMs };\n      sessions.set(session.id, session);\n      return session;\n    },\n    get: (id: string) => sessions.get(id),\n    touch: (id: string) => sessions.has(id),\n    revoke: (id: string) => sessions.delete(id),\n    revokeAll: (userId: string) => 0,\n    activeCount: () => sessions.size,\n    sessionsFor: (userId: string) => [...sessions.values()].filter((s) => s.userId === userId),\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createSessionManager } from \"./src/sessions\";\n\nlet t = 0;\nlet n = 0;\nconst manager = createSessionManager({ ttlMs: 1000, now: () => t, generateId: () => \"s\" + ++n });\nconst lines: string[] = [];\ntry {\n  const a = manager.create(\"ada\");\n  manager.create(\"ada\");\n  manager.create(\"bob\");\n  lines.push(\"public keys: \" + Object.keys(manager).join(\", \"));\n  try {\n    (a as any).userId = \"mallory\";\n  } catch {\n    lines.push(\"can''t modify a returned session\");\n  }\n  lines.push(\"stored user: \" + manager.get(a.id)?.userId);\n  t = 1500;\n  lines.push(\"active after expiry: \" + manager.activeCount());\n} catch (e) {\n  lines.push(\"error: \" + (e as Error).message);\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Sessions</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/sessions.ts","/index.ts"],"activeFile":"/src/sessions.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { createSessionManager } from \"../src/sessions\";\n\nfunction setup(ttlMs = 1000) {\n  const clock = { t: 0 };\n  let n = 0;\n  const manager = createSessionManager({ ttlMs, now: () => clock.t, generateId: () => \"s\" + ++n });\n  return { manager, clock };\n}\n\ndescribe(\"createSessionManager\", () => {\n  it(\"creates sessions with injected ids and times\", () => {\n    const { manager, clock } = setup();\n    clock.t = 100;\n    expect(manager.create(\"ada\")).toEqual({ id: \"s1\", userId: \"ada\", createdAt: 100, expiresAt: 1100 });\n    expect(() => manager.create(\"\")).toThrow(TypeError);\n  });\n  it(\"exposes only methods, and nothing else\", () => {\n    const { manager } = setup();\n    manager.create(\"ada\");\n    expect(Object.keys(manager).sort()).toEqual([\"activeCount\", \"create\", \"get\", \"revoke\", \"revokeAll\", \"sessionsFor\", \"touch\"]);\n    expect(JSON.stringify(manager)).toBe(\"{}\");\n    expect(Object.isFrozen(manager)).toBe(true);\n  });\n  it(\"never hands out its internal objects\", () => {\n    const { manager } = setup();\n    const session = manager.create(\"ada\");\n    expect(Object.isFrozen(session)).toBe(true);\n    expect(() => { session.userId = \"mallory\"; }).toThrow(TypeError);\n    const fetched = manager.get(\"s1\");\n    expect(fetched).not.toBe(manager.get(\"s1\"));\n    const list = manager.sessionsFor(\"ada\");\n    list.length = 0;\n    expect(manager.sessionsFor(\"ada\").length).toBe(1);\n  });\n  it(\"expires sessions, and touch extends them\", () => {\n    const { manager, clock } = setup(1000);\n    manager.create(\"ada\");\n    manager.create(\"bob\");\n    clock.t = 800;\n    expect(manager.touch(\"s1\")).toBe(true);\n    clock.t = 1200;\n    expect(manager.get(\"s1\").expiresAt).toBe(1800);\n    expect(manager.get(\"s2\")).toBeUndefined();\n    expect(manager.touch(\"s2\")).toBe(false);\n    expect(manager.activeCount()).toBe(1);\n  });\n  it(\"revokes one or all of a user''s sessions\", () => {\n    const { manager } = setup();\n    manager.create(\"ada\");\n    manager.create(\"ada\");\n    manager.create(\"bob\");\n    expect(manager.revoke(\"s3\")).toBe(true);\n    expect(manager.revoke(\"s3\")).toBe(false);\n    expect(manager.revokeAll(\"ada\")).toBe(2);\n    expect(manager.activeCount()).toBe(0);\n  });\n  it(\"keeps instances independent\", () => {\n    const a = setup().manager;\n    const b = setup().manager;\n    a.create(\"ada\");\n    expect(b.activeCount()).toBe(0);\n  });\n});\n","testCount":6}'::jsonb),
  ('mod-private-account', 'practice', 4, 1500, '{"en":"One account, three privacy techniques","uk":"Один рахунок, три техніки приватності"}'::jsonb, '{"en":"Implement the same bank account three ways in `src/accounts.ts`: `createClosureAccount(initial)` (closure state), `PrivateFieldAccount` (`#private` fields) and `WeakMapAccount` (a module-level `WeakMap`). All three must:\n\n- Support `deposit(amount)` and `withdraw(amount)` (both return the new balance) and `getBalance()`. Amounts must be positive finite numbers, a withdrawal can''t exceed the balance (`\"Insufficient funds\"`), and the initial balance can''t be negative (all `RangeError`s).\n- Keep the balance invisible: no own property (string or symbol key) holds it, `JSON.stringify` doesn''t reveal it, and assigning `acc.balance = …` can''t change it.\n- `transfer(to, amount)` works only with **real accounts of the same implementation**. Look-alike objects and accounts from the other implementations throw a `TypeError`, and a failed transfer changes nothing.","uk":"Реалізуйте той самий банківський рахунок трьома способами в `src/accounts.ts`: `createClosureAccount(initial)` (стан у замиканні), `PrivateFieldAccount` (поля `#private`) і `WeakMapAccount` (`WeakMap` рівня модуля). Усі три мають:\n\n- Підтримувати `deposit(amount)` і `withdraw(amount)` (обидва повертають новий баланс) і `getBalance()`. Суми мають бути додатними скінченними числами, зняття не може перевищувати баланс (`\"Insufficient funds\"`), а початковий баланс не може бути від''ємним (усе це `RangeError`).\n- Тримати баланс невидимим: жодна власна властивість (з рядковим чи символьним ключем) його не містить, `JSON.stringify` його не показує, а присвоєння `acc.balance = …` не може його змінити.\n- `transfer(to, amount)` працює лише зі **справжніми рахунками тієї самої реалізації**. Схожі об''єкти й рахунки інших реалізацій кидають `TypeError`, а невдалий переказ нічого не змінює."}'::jsonb, 'module-pattern', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/accounts.ts":"export interface Account {\n  deposit(amount: number): number;\n  withdraw(amount: number): number;\n  getBalance(): number;\n  /** Moves money to another account of the same implementation. */\n  transfer(to: Account, amount: number): void;\n}\n\n// TODO: the balance is a public property in all three, nothing is validated,\n// and transfer accepts anything with a deposit method.\n\nexport function createClosureAccount(initial = 0): Account & { balance: number } {\n  const account = {\n    balance: initial,\n    deposit(amount: number) { return (account.balance += amount); },\n    withdraw(amount: number) { return (account.balance -= amount); },\n    getBalance() { return account.balance; },\n    transfer(to: Account, amount: number) { account.withdraw(amount); to.deposit(amount); },\n  };\n  return account;\n}\n\nexport class PrivateFieldAccount implements Account {\n  balance: number;\n  constructor(initial = 0) { this.balance = initial; }\n  deposit(amount: number) { return (this.balance += amount); }\n  withdraw(amount: number) { return (this.balance -= amount); }\n  getBalance() { return this.balance; }\n  transfer(to: Account, amount: number) { this.withdraw(amount); to.deposit(amount); }\n}\n\nexport class WeakMapAccount implements Account {\n  balance: number;\n  constructor(initial = 0) { this.balance = initial; }\n  deposit(amount: number) { return (this.balance += amount); }\n  withdraw(amount: number) { return (this.balance -= amount); }\n  getBalance() { return this.balance; }\n  transfer(to: Account, amount: number) { this.withdraw(amount); to.deposit(amount); }\n}\n","/index.ts":"import \"./styles.css\";\nimport { PrivateFieldAccount, WeakMapAccount, createClosureAccount } from \"./src/accounts\";\n\nconst lines: string[] = [];\nconst make = { closure: () => createClosureAccount(4321), \"#private\": () => new PrivateFieldAccount(4321), WeakMap: () => new WeakMapAccount(4321) };\nfor (const [name, create] of Object.entries(make)) {\n  try {\n    const acc: any = create();\n    lines.push(name.padEnd(9) + \" keys: \" + JSON.stringify(Object.keys(acc)) + \"  json: \" + JSON.stringify(acc) + \"  balance: \" + acc.getBalance());\n  } catch (e) {\n    lines.push(name + \" error: \" + (e as Error).message);\n  }\n}\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Private state</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = lines.join(\"\\n\");\n"},"visibleFiles":["/src/accounts.ts","/index.ts"],"activeFile":"/src/accounts.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { PrivateFieldAccount, WeakMapAccount, createClosureAccount } from \"../src/accounts\";\n\nconst implementations = [\n  [\"closure\", (b) => createClosureAccount(b)],\n  [\"#private\", (b) => new PrivateFieldAccount(b)],\n  [\"WeakMap\", (b) => new WeakMapAccount(b)],\n];\n\nfor (const [name, make] of implementations) {\n  describe(name + \" account\", () => {\n    it(\"deposits and withdraws\", () => {\n      const acc = make(100);\n      expect(acc.deposit(50)).toBe(150);\n      expect(acc.withdraw(30)).toBe(120);\n      expect(acc.getBalance()).toBe(120);\n    });\n    it(\"validates amounts and the initial balance\", () => {\n      const acc = make(10);\n      expect(() => acc.deposit(-5)).toThrow(RangeError);\n      expect(() => acc.deposit(NaN)).toThrow(RangeError);\n      expect(() => acc.withdraw(0)).toThrow(RangeError);\n      expect(() => acc.withdraw(11)).toThrow(\"Insufficient funds\");\n      expect(acc.getBalance()).toBe(10);\n      expect(() => make(-1)).toThrow(RangeError);\n    });\n    it(\"hides the balance from every kind of inspection\", () => {\n      const acc = make(4321);\n      expect(JSON.stringify(acc)).not.toContain(\"4321\");\n      expect(Reflect.ownKeys(acc).some((key) => acc[key] === 4321)).toBe(false);\n      expect(Object.getOwnPropertySymbols(acc).length).toBe(0);\n      try {\n        acc.balance = 1e9;\n      } catch {\n        /* frozen objects throw in strict mode */\n      }\n      expect(acc.getBalance()).toBe(4321);\n    });\n    it(\"transfers between accounts of the same kind, atomically\", () => {\n      const a = make(100);\n      const b = make(5);\n      a.transfer(b, 40);\n      expect([a.getBalance(), b.getBalance()]).toEqual([60, 45]);\n      expect(() => a.transfer(b, 1000)).toThrow(\"Insufficient funds\");\n      expect([a.getBalance(), b.getBalance()]).toEqual([60, 45]);\n    });\n    it(\"refuses look-alike or foreign accounts\", () => {\n      const a = make(100);\n      const fake = { deposit: () => 0, withdraw: () => 0, getBalance: () => 0, transfer() {} };\n      expect(() => a.transfer(fake, 10)).toThrow(TypeError);\n      const other = implementations.find(([n]) => n !== name)[1](0);\n      expect(() => a.transfer(other, 10)).toThrow(TypeError);\n      expect(a.getBalance()).toBe(100);\n    });\n  });\n}\n","testCount":5}'::jsonb),
  ('mon-percentiles-vs-average', 'quiz', 2, 75, '{"en":"Why p95 instead of the average","uk":"Навіщо p95, а не середнє"}'::jsonb, '{"en":"Why do dashboards show the 95th percentile latency next to the average?","uk":"Чому дашборди показують 95-й перцентиль затримки поруч із середнім?"}'::jsonb, null, '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"An average hides slow outliers: if 5% of requests take ten seconds, the mean can still look healthy, while p95 shows what the slowest users experience","uk":"Середнє приховує повільні викиди: якщо 5% запитів тривають десять секунд, середнє все одно може виглядати добре, а p95 показує, що відчувають найповільніші користувачі"}},{"id":"b","text":{"en":"Percentiles are always lower than averages, so they look better","uk":"Перцентилі завжди нижчі за середні, тож виглядають краще"}},{"id":"c","text":{"en":"The average can''t be computed from histograms","uk":"Середнє не можна обчислити з гістограм"}},{"id":"d","text":{"en":"p95 is the number of requests per second","uk":"p95 — це кількість запитів на секунду"}}]}'::jsonb, null::jsonb),
  ('mon-latency-histogram', 'practice', 3, 1080, '{"en":"A latency histogram with percentiles","uk":"Гістограма затримок із перцентилями"}'::jsonb, '{"en":"Monitoring systems don''t store every request''s latency: they count observations into buckets and estimate percentiles from the counts, which works across many servers. Implement `createHistogram(bounds)` in `src/histogram.ts`:\n\n- Each bound is an inclusive upper limit (`le`). A value equal to a bound counts in that bound''s bucket. Values above the last bound go to an overflow bucket whose bound is `Infinity`.\n- `observe(value)` records a value; `count` and `mean()` describe everything observed so far (`mean()` is `NaN` before any observation).\n- `buckets()` returns **cumulative** counts: each bucket counts everything at or below its bound, and the last one equals `count`.\n- `percentile(p)` returns the bound of the first bucket holding at least `ceil(p × count)` observations (at least 1), and `Infinity` if that lands in the overflow bucket.\n- Bounds must be strictly ascending, or a `RangeError`.","uk":"Системи моніторингу не зберігають затримку кожного запиту: вони рахують виміри по коробках і оцінюють перцентилі за підрахунками, а це працює на багатьох серверах. Реалізуйте `createHistogram(bounds)` у `src/histogram.ts`:\n\n- Кожна межа — це включна верхня границя (`le`). Значення, що дорівнює межі, рахується в коробці цієї межі. Значення понад останню межу потрапляють у коробку переповнення з межею `Infinity`.\n- `observe(value)` записує значення; `count` і `mean()` описують усе спостережене (`mean()` дорівнює `NaN` до першого спостереження).\n- `buckets()` повертає **накопичувальні** підрахунки: кожна коробка рахує все, що не перевищує її межу, а остання дорівнює `count`.\n- `percentile(p)` повертає межу першої коробки, де є щонайменше `ceil(p × count)` спостережень (принаймні 1), а `Infinity`, якщо це потрапило в коробку переповнення.\n- Межі мають бути строго зростаючими, інакше `RangeError`."}'::jsonb, null, null::jsonb, '{"framework":"vanilla-ts","files":{"/src/histogram.ts":"/**\n * A latency histogram with fixed buckets. Each bound is an upper limit (le), inclusive;\n * anything above the last bound goes to an overflow bucket with bound Infinity.\n */\nexport function createHistogram(bounds: number[]) {\n  return {\n    observe(value: number): void {\n      // TODO\n    },\n    get count(): number {\n      return 0; // TODO\n    },\n    mean(): number {\n      return NaN; // TODO\n    },\n    /** Cumulative counts per bucket, the last one (Infinity) equal to count. */\n    buckets(): Array<{ le: number; count: number }> {\n      return []; // TODO\n    },\n    /** Estimated percentile: the upper bound of the first bucket that holds ceil(p × count) observations. */\n    percentile(p: number): number {\n      return NaN; // TODO\n    },\n  };\n}\n","/index.ts":"import \"./styles.css\";\nimport { createHistogram } from \"./src/histogram\";\n\nconst latency = createHistogram([10, 50, 100, 500]);\n[12, 35, 48, 90, 120, 800].forEach((ms) => latency.observe(ms));\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Latency</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = \"p50 ≤ \" + latency.percentile(0.5) + \" ms, p95 ≤ \" + latency.percentile(0.95) + \" ms, mean \" + latency.mean().toFixed(1) + \" ms\";\n"},"visibleFiles":["/src/histogram.ts"],"activeFile":"/src/histogram.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { createHistogram } from \"../src/histogram\";\n\nfunction filled() {\n  const h = createHistogram([1, 2, 5, 10]);\n  [1, 2, 3, 10].forEach((v) => h.observe(v));\n  return h;\n}\n\ndescribe(\"createHistogram\", () => {\n  it(\"counts observations and computes the mean\", () => {\n    const h = filled();\n    expect(h.count).toBe(4);\n    expect(h.mean()).toBe(4);\n  });\n  it(\"keeps cumulative counts per bucket, with the overflow bucket last\", () => {\n    expect(filled().buckets()).toEqual([\n      { le: 1, count: 1 },\n      { le: 2, count: 2 },\n      { le: 5, count: 3 },\n      { le: 10, count: 4 },\n      { le: Infinity, count: 4 },\n    ]);\n  });\n  it(\"counts a value equal to a bound in that bound''s bucket\", () => {\n    expect(filled().buckets()[1].count).toBe(2);\n  });\n  it(\"estimates percentiles from the bucket bounds\", () => {\n    const h = filled();\n    expect(h.percentile(0.5)).toBe(2);\n    expect(h.percentile(0.75)).toBe(5);\n    expect(h.percentile(0.95)).toBe(10);\n    expect(h.percentile(1)).toBe(10);\n  });\n  it(\"reports overflow values as Infinity\", () => {\n    const h = createHistogram([10]);\n    h.observe(50);\n    expect(h.percentile(1)).toBe(Infinity);\n    expect(h.mean()).toBe(50);\n  });\n  it(\"is NaN before any observation\", () => {\n    const h = createHistogram([10]);\n    expect(h.percentile(0.5)).toBeNaN();\n    expect(h.mean()).toBeNaN();\n  });\n  it(\"needs strictly ascending bounds\", () => {\n    expect(() => createHistogram([2, 1])).toThrow(RangeError);\n    expect(() => createHistogram([])).toThrow(RangeError);\n  });\n});\n","testCount":7}'::jsonb),
  ('net-http-request-parser', 'practice', 4, 1320, '{"en":"Parse a raw HTTP request","uk":"Розберіть сирий HTTP-запит"}'::jsonb, '{"en":"A server receives bytes from a socket, and before any framework runs, something must split them into a request. Implement `parseRequest(raw)` in `src/http.ts` for HTTP/1.x text, where lines end with `\\r\\n` and the head ends with an empty line:\n\n- The request line is `METHOD target HTTP/1.1` (or `HTTP/1.0`). Anything else is `Bad request line`, and other versions are `Unsupported HTTP version`.\n- The query string after `?` is split on `&` and decoded: `+` means a space, and percent-escapes are decoded. A key without `=` gets the empty string.\n- Header names are lowercased and values trimmed. A header without a colon is `Bad header: …`. A repeated header is joined with `, `.\n- Without a head that ends in an empty line the request is `Incomplete request head`.\n- The body is read by `content-length`: no header means an empty body, a non-numeric value is `Bad content-length`, and fewer bytes than declared is `Truncated body`. Bytes after the declared length are ignored.","uk":"Сервер отримує байти із сокета, і до будь-якого фреймворку хтось має розбити їх на запит. Реалізуйте `parseRequest(raw)` у `src/http.ts` для тексту HTTP/1.x, де рядки закінчуються на `\\r\\n`, а заголовки завершуються порожнім рядком:\n\n- Рядок запиту має вигляд `METHOD target HTTP/1.1` (або `HTTP/1.0`). Інше — це `Bad request line`, а інші версії — `Unsupported HTTP version`.\n- Рядок запиту після `?` ділиться по `&` і декодується: `+` означає пробіл, а відсоткове кодування декодується. Ключ без `=` отримує порожній рядок.\n- Назви заголовків переводяться в нижній регістр, значення обрізаються. Заголовок без двокрапки — це `Bad header: …`. Повторюваний заголовок з''єднується через `, `.\n- Без заголовків, що закінчуються порожнім рядком, запит — це `Incomplete request head`.\n- Тіло читається за `content-length`: без заголовка тіло порожнє, нечислове значення — `Bad content-length`, а байтів менше, ніж оголошено, — `Truncated body`. Байти після оголошеної довжини ігноруються."}'::jsonb, null, null::jsonb, '{"framework":"vanilla-ts","files":{"/src/http.ts":"export type ParsedRequest = {\n  method: string;\n  path: string;\n  query: Record<string, string>;\n  headers: Record<string, string>;\n  body: string;\n};\n\n/** Parses a raw HTTP/1.1 request as it arrives on a socket. */\nexport function parseRequest(raw: string): ParsedRequest {\n  // TODO: request line, query string, headers, and the body from content-length\n  return { method: \"\", path: \"\", query: {}, headers: {}, body: \"\" };\n}\n","/index.ts":"import \"./styles.css\";\nimport { parseRequest } from \"./src/http\";\n\nconst raw = \"GET /search?q=hello+world HTTP/1.1\\r\\nHost: example.com\\r\\n\\r\\n\";\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>HTTP request</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = JSON.stringify(parseRequest(raw), null, 2);\n"},"visibleFiles":["/src/http.ts"],"activeFile":"/src/http.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { parseRequest } from \"../src/http\";\n\ndescribe(\"parseRequest\", () => {\n  it(\"reads the method, path and decoded query string\", () => {\n    const req = parseRequest(\"GET /search?q=hello+world&lang=uk%20ua&flag HTTP/1.1\\r\\nHost: example.com\\r\\n\\r\\n\");\n    expect(req.method).toBe(\"GET\");\n    expect(req.path).toBe(\"/search\");\n    expect(req.query).toEqual({ q: \"hello world\", lang: \"uk ua\", flag: \"\" });\n  });\n  it(\"lowercases header names and trims values\", () => {\n    const req = parseRequest(\"GET / HTTP/1.1\\r\\nHost:   example.com \\r\\nAccept-Language: uk\\r\\n\\r\\n\");\n    expect(req.headers).toEqual({ host: \"example.com\", \"accept-language\": \"uk\" });\n  });\n  it(\"combines repeated headers with a comma\", () => {\n    const req = parseRequest(\"GET / HTTP/1.1\\r\\nAccept: text/html\\r\\nAccept: application/json\\r\\n\\r\\n\");\n    expect(req.headers.accept).toBe(\"text/html, application/json\");\n  });\n  it(\"reads the body by content-length and ignores what follows it\", () => {\n    const req = parseRequest(\"POST /items HTTP/1.1\\r\\nContent-Length: 5\\r\\n\\r\\nhelloEXTRA\");\n    expect(req.method).toBe(\"POST\");\n    expect(req.body).toBe(\"hello\");\n  });\n  it(\"has an empty body without content-length\", () => {\n    expect(parseRequest(\"POST /x HTTP/1.1\\r\\n\\r\\nabc\").body).toBe(\"\");\n  });\n  it(\"rejects a truncated body\", () => {\n    expect(() => parseRequest(\"POST /x HTTP/1.1\\r\\nContent-Length: 10\\r\\n\\r\\nabc\")).toThrow(\"Truncated body\");\n  });\n  it(\"rejects a bad request line and unsupported versions\", () => {\n    expect(() => parseRequest(\"GET/HTTP/1.1\\r\\n\\r\\n\")).toThrow(\"Bad request line\");\n    expect(() => parseRequest(\"GET / HTTP/2.0\\r\\n\\r\\n\")).toThrow(\"Unsupported HTTP version\");\n  });\n  it(\"rejects an incomplete head and a header without a colon\", () => {\n    expect(() => parseRequest(\"GET / HTTP/1.1\\r\\nHost: example.com\")).toThrow(\"Incomplete request head\");\n    expect(() => parseRequest(\"GET / HTTP/1.1\\r\\nBrokenHeader\\r\\n\\r\\n\")).toThrow(\"Bad header\");\n  });\n});\n","testCount":8}'::jsonb),
  ('next-page-file', 'quiz', 1, 45, '{"en":"Which file is the page?","uk":"Який файл є сторінкою?"}'::jsonb, '{"en":"In the App Router, which file renders the UI for the URL `/dashboard`?","uk":"Який файл в App Router рендерить інтерфейс для URL `/dashboard`?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`app/dashboard/page.tsx`","uk":"`app/dashboard/page.tsx`"}},{"id":"b","text":{"en":"`app/dashboard.tsx`","uk":"`app/dashboard.tsx`"}},{"id":"c","text":{"en":"`app/dashboard/index.tsx`","uk":"`app/dashboard/index.tsx`"}},{"id":"d","text":{"en":"`app/dashboard/route.tsx`","uk":"`app/dashboard/route.tsx`"}}]}'::jsonb, null::jsonb),
  ('next-use-client', 'quiz', 2, 60, '{"en":"Hooks in the App Router","uk":"Хуки в App Router"}'::jsonb, '{"en":"`app/components/Counter.tsx` uses `useState` and an `onClick` handler, and the build fails saying `useState` only works in Client Components. What''s the fix?","uk":"`app/components/Counter.tsx` використовує `useState` та обробник `onClick`, і збірка падає з повідомленням, що `useState` працює лише в клієнтських компонентах. Як виправити?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Add `\"use client\"` at the top of `Counter.tsx`","uk":"Додати `\"use client\"` на початку `Counter.tsx`"}},{"id":"b","text":{"en":"Add `\"use client\"` to the root `layout.tsx`","uk":"Додати `\"use client\"` у кореневий `layout.tsx`"}},{"id":"c","text":{"en":"Make `Counter` an `async` function","uk":"Зробити `Counter` функцією `async`"}},{"id":"d","text":{"en":"Rename the file to `Counter.client.tsx`","uk":"Перейменувати файл на `Counter.client.tsx`"}}]}'::jsonb, null::jsonb),
  ('next-async-params', 'quiz', 2, 90, '{"en":"Reading route params","uk":"Читання параметрів маршруту"}'::jsonb, '{"en":"In a recent Next.js version, how should `app/blog/[slug]/page.tsx` read the slug?","uk":"Як у свіжій версії Next.js файлу `app/blog/[slug]/page.tsx` прочитати slug?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`export default async function Page({ params }) { const { slug } = await params; … }`","uk":"`export default async function Page({ params }) { const { slug } = await params; … }`"}},{"id":"b","text":{"en":"`export default function Page({ params }) { const { slug } = params; … }`","uk":"`export default function Page({ params }) { const { slug } = params; … }`"}},{"id":"c","text":{"en":"`const slug = useParams().slug` in the Server Component","uk":"`const slug = useParams().slug` у серверному компоненті"}},{"id":"d","text":{"en":"`const slug = window.location.pathname.split(\"/\")[2]`","uk":"`const slug = window.location.pathname.split(\"/\")[2]`"}}]}'::jsonb, null::jsonb),
  ('next-env-secret', 'quiz', 3, 90, '{"en":"Secrets and the client bundle","uk":"Секрети й клієнтський бандл"}'::jsonb, '{"en":"A Client Component calls Stripe with `process.env.STRIPE_SECRET_KEY`, and the key is empty in the browser. What''s going on, and what should you do?","uk":"Клієнтський компонент викликає Stripe з `process.env.STRIPE_SECRET_KEY`, а в браузері ключ порожній. Що відбувається і що робити?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Only `NEXT_PUBLIC_` variables are inlined into client code; keep the call on the server (Server Component, Server Action or Route Handler)","uk":"У клієнтський код вбудовуються лише змінні `NEXT_PUBLIC_`; виконуйте виклик на сервері (серверний компонент, Server Action чи Route Handler)"}},{"id":"b","text":{"en":"Rename it to `NEXT_PUBLIC_STRIPE_SECRET_KEY`","uk":"Перейменувати на `NEXT_PUBLIC_STRIPE_SECRET_KEY`"}},{"id":"c","text":{"en":"Read it in `useEffect`, where `process.env` is available","uk":"Читати її в `useEffect`, де `process.env` доступний"}},{"id":"d","text":{"en":"Restart the dev server; client env vars load lazily","uk":"Перезапустити dev-сервер; змінні для клієнта завантажуються ліниво"}}]}'::jsonb, null::jsonb),
  ('next-loading-streaming', 'quiz', 3, 90, '{"en":"What `loading.tsx` does","uk":"Що робить `loading.tsx`"}'::jsonb, '{"en":"You add `app/dashboard/loading.tsx` next to a page that awaits a slow query. What changes?","uk":"Ви додаєте `app/dashboard/loading.tsx` поруч зі сторінкою, що чекає на повільний запит. Що зміниться?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The page is wrapped in a Suspense boundary: the layout and the loading UI stream immediately, and the page content streams in when the query finishes","uk":"Сторінку обгорнуто межею Suspense: макет і UI завантаження передаються одразу, а вміст сторінки надходить, коли запит завершиться"}},{"id":"b","text":{"en":"The query is cached for 60 seconds","uk":"Запит кешується на 60 секунд"}},{"id":"c","text":{"en":"The page becomes a Client Component that fetches in `useEffect`","uk":"Сторінка стає клієнтським компонентом, що отримує дані в `useEffect`"}},{"id":"d","text":{"en":"Nothing until you also add `export const dynamic = \"force-static\"`","uk":"Нічого, поки не додати ще й `export const dynamic = \"force-static\"`"}}]}'::jsonb, null::jsonb),
  ('next-server-action-auth', 'quiz', 4, 120, '{"en":"Securing a Server Action","uk":"Захист Server Action"}'::jsonb, '{"en":"The delete button is rendered only for admins. Is `deletePost` secure?","uk":"Кнопку видалення показують лише адміністраторам. Чи безпечний `deletePost`?"}'::jsonb, 'nextjs', '{"mode":"single","code":"async function deletePost(id: string) {\n  \"use server\";\n  await db.post.delete({ where: { id } });\n}\n\n{isAdmin && (\n  <form action={deletePost.bind(null, post.id)}>\n    <button>Delete</button>\n  </form>\n)}","codeLanguage":"tsx","options":[{"id":"a","text":{"en":"No: a Server Action is a public POST endpoint; check the user''s role and validate `id` inside the action","uk":"Ні: Server Action є публічним POST-ендпоінтом; перевіряйте роль користувача й валідуйте `id` всередині дії"}},{"id":"b","text":{"en":"Yes: Server Actions can only be called from components that render them","uk":"Так: Server Actions можна викликати лише з компонентів, які їх рендерять"}},{"id":"c","text":{"en":"Yes, because the action ID is secret and random","uk":"Так, бо ідентифікатор дії секретний і випадковий"}},{"id":"d","text":{"en":"No, but adding `\"use client\"` to the button fixes it","uk":"Ні, але додавання `\"use client\"` до кнопки це виправить"}}]}'::jsonb, null::jsonb),
  ('next-revalidate-after-write', 'quiz', 4, 120, '{"en":"Stale data after a mutation","uk":"Застарілі дані після зміни"}'::jsonb, '{"en":"A Server Action renames a product, but `/products` still shows the old name because the page is cached. What should the action do after the write?","uk":"Server Action перейменовує товар, але `/products` показує стару назву, бо сторінку закешовано. Що має зробити дія після запису?"}'::jsonb, 'nextjs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Call `revalidatePath(\"/products\")` (or `updateTag`/`revalidateTag` for tagged data)","uk":"Викликати `revalidatePath(\"/products\")` (або `updateTag`/`revalidateTag` для даних з тегами)"}},{"id":"b","text":{"en":"Call `router.refresh()` inside the Server Action","uk":"Викликати `router.refresh()` всередині Server Action"}},{"id":"c","text":{"en":"Set `export const revalidate = 0` in the root layout","uk":"Встановити `export const revalidate = 0` у кореневому макеті"}},{"id":"d","text":{"en":"Return `{ cache: \"no-store\" }` from the action","uk":"Повернути `{ cache: \"no-store\" }` з дії"}}]}'::jsonb, null::jsonb),
  ('next-boundary-props', 'quiz', 5, 150, '{"en":"Crossing the client boundary","uk":"Перетин клієнтської межі"}'::jsonb, '{"en":"A Server Component renders `<Filters … />`, a Client Component. Which props can it pass? (Select all that apply.)","uk":"Серверний компонент рендерить `<Filters … />`, клієнтський компонент. Які пропси він може передати? (Оберіть усі.)"}'::jsonb, 'nextjs', '{"mode":"multi","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`options={[{ id: 1, label: \"New\" }]}`","uk":"`options={[{ id: 1, label: \"New\" }]}`"}},{"id":"b","text":{"en":"`onChange={(v) => console.log(v)}`","uk":"`onChange={(v) => console.log(v)}`"}},{"id":"c","text":{"en":"`children={<ServerRenderedList />}`","uk":"`children={<ServerRenderedList />}`"}},{"id":"d","text":{"en":"`onSave={saveFilters}`, where `saveFilters` is a Server Action","uk":"`onSave={saveFilters}`, де `saveFilters` є Server Action"}},{"id":"e","text":{"en":"`formatter={new Intl.NumberFormat(\"en\")}`","uk":"`formatter={new Intl.NumberFormat(\"en\")}`"}}]}'::jsonb, null::jsonb),
  ('next-route-matcher', 'practice', 4, 1200, '{"en":"An App Router route matcher","uk":"Зіставлення маршрутів App Router"}'::jsonb, '{"en":"Implement `matchRoute(routes, pathname)` in `src/router.ts`, the way the Next.js App Router resolves URLs. It returns `{ route, params }` for the best match or `null`.\n\n- `[slug]` matches one segment: `params.slug = \"hello\"`.\n- `[...path]` (catch-all) matches **one or more** segments: `params.path = [\"a\", \"b\"]`.\n- `[[...slug]]` (optional catch-all) also matches **zero** segments, leaving the param out.\n- `(group)` folders are route groups and aren''t part of the URL.\n- Specificity decides, segment by segment, regardless of the order of `routes`: static > dynamic > catch-all > optional catch-all.\n- Ignore trailing slashes, the query string and the hash; decode percent-encoded segments.","uk":"Реалізуйте `matchRoute(routes, pathname)` у `src/router.ts` так, як App Router у Next.js розпізнає URL. Функція повертає `{ route, params }` для найкращого збігу або `null`.\n\n- `[slug]` відповідає одному сегменту: `params.slug = \"hello\"`.\n- `[...path]` (catch-all) відповідає **одному чи більше** сегментам: `params.path = [\"a\", \"b\"]`.\n- `[[...slug]]` (необов''язковий catch-all) відповідає також **нулю** сегментів, і тоді параметра немає.\n- Папки `(group)` є групами маршрутів і не входять в URL.\n- Перевагу визначає специфічність, сегмент за сегментом, незалежно від порядку `routes`: статичний > динамічний > catch-all > необов''язковий catch-all.\n- Ігноруйте кінцеві слеші, рядок запиту й хеш; декодуйте сегменти з процентним кодуванням."}'::jsonb, 'nextjs', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/router.ts":"export type Params = Record<string, string | string[]>;\nexport type Match = { route: string; params: Params };\n\n/**\n * Matches a pathname against App Router route patterns such as\n * \"/blog/[slug]\", \"/shop/[...path]\", \"/docs/[[...slug]]\" and \"/(marketing)/about\".\n */\nexport function matchRoute(routes: string[], pathname: string): Match | null {\n  // TODO: only exact static matches work so far\n  return routes.includes(pathname) ? { route: pathname, params: {} } : null;\n}\n","/index.ts":"import \"./styles.css\";\nimport { matchRoute } from \"./src/router\";\n\nconst routes = [\"/\", \"/blog/[slug]\", \"/blog/new\", \"/shop/[...path]\", \"/docs/[[...slug]]\", \"/(marketing)/about\"];\nconst paths = [\"/\", \"/blog/new\", \"/blog/hello-world\", \"/shop/shoes/red\", \"/docs\", \"/about\", \"/missing\"];\n\ndocument.getElementById(\"app\")!.innerHTML =\n  \"<h1>App Router matcher</h1><table><tr><th>Path</th><th>Route</th><th>Params</th></tr>\" +\n  paths\n    .map((p) => {\n      const m = matchRoute(routes, p);\n      return \"<tr><td>\" + p + \"</td><td>\" + (m ? m.route : \"404\") + \"</td><td>\" + (m ? JSON.stringify(m.params) : \"\") + \"</td></tr>\";\n    })\n    .join(\"\") +\n  \"</table>\";\n"},"visibleFiles":["/src/router.ts","/index.ts"],"activeFile":"/src/router.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { matchRoute } from \"../src/router\";\n\nconst routes = [\n  \"/\",\n  \"/blog\",\n  \"/blog/[slug]\",\n  \"/blog/new\",\n  \"/users/[id]/posts/[postId]\",\n  \"/shop/[...path]\",\n  \"/docs/[[...slug]]\",\n  \"/(marketing)/about\",\n];\n\ndescribe(\"matchRoute\", () => {\n  it(\"matches static routes\", () => {\n    expect(matchRoute(routes, \"/\")).toEqual({ route: \"/\", params: {} });\n    expect(matchRoute(routes, \"/blog\")).toEqual({ route: \"/blog\", params: {} });\n  });\n  it(\"fills dynamic segments\", () => {\n    expect(matchRoute(routes, \"/blog/hello-world\")).toEqual({ route: \"/blog/[slug]\", params: { slug: \"hello-world\" } });\n    expect(matchRoute(routes, \"/users/7/posts/42\")).toEqual({ route: \"/users/[id]/posts/[postId]\", params: { id: \"7\", postId: \"42\" } });\n  });\n  it(\"prefers static segments over dynamic ones, whatever the order\", () => {\n    expect(matchRoute(routes, \"/blog/new\")).toEqual({ route: \"/blog/new\", params: {} });\n  });\n  it(\"collects catch-all segments, which need at least one part\", () => {\n    expect(matchRoute(routes, \"/shop/shoes/red/42\")).toEqual({ route: \"/shop/[...path]\", params: { path: [\"shoes\", \"red\", \"42\"] } });\n    expect(matchRoute(routes, \"/shop\")).toBe(null);\n  });\n  it(\"lets optional catch-alls match zero parts\", () => {\n    expect(matchRoute(routes, \"/docs\")).toEqual({ route: \"/docs/[[...slug]]\", params: {} });\n    expect(matchRoute(routes, \"/docs/getting-started/install\")).toEqual({\n      route: \"/docs/[[...slug]]\",\n      params: { slug: [\"getting-started\", \"install\"] },\n    });\n  });\n  it(\"ignores route groups in the URL\", () => {\n    expect(matchRoute(routes, \"/about\")).toEqual({ route: \"/(marketing)/about\", params: {} });\n  });\n  it(\"ignores trailing slashes, query strings and hashes, and decodes segments\", () => {\n    expect(matchRoute(routes, \"/blog/hello/?ref=home#top\")).toEqual({ route: \"/blog/[slug]\", params: { slug: \"hello\" } });\n    expect(matchRoute(routes, \"/blog/caf%C3%A9\")).toEqual({ route: \"/blog/[slug]\", params: { slug: \"café\" } });\n  });\n  it(\"returns null when nothing matches\", () => {\n    expect(matchRoute(routes, \"/missing\")).toBe(null);\n    expect(matchRoute(routes, \"/blog/a/b\")).toBe(null);\n  });\n});\n","testCount":8}'::jsonb),
  ('node-type-module', 'quiz', 2, 60, '{"en":"ESM or CommonJS?","uk":"ESM чи CommonJS?"}'::jsonb, '{"en":"`package.json` contains `\"type\": \"module\"`. How does Node.js treat `server.js` in that package?","uk":"`package.json` містить `\"type\": \"module\"`. Як Node.js трактує `server.js` у цьому пакеті?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"As CommonJS; `.js` is always CommonJS","uk":"Як CommonJS; `.js` завжди CommonJS"}},{"id":"b","text":{"en":"As an ES module, so `require` and `__dirname` are not defined","uk":"Як ES-модуль, тож `require` і `__dirname` не визначені"}},{"id":"c","text":{"en":"As both, depending on the first import","uk":"Як обидва, залежно від першого імпорту"}},{"id":"d","text":{"en":"It refuses to run `.js` files","uk":"Відмовляється запускати файли `.js`"}}]}'::jsonb, null::jsonb),
  ('node-backpressure', 'quiz', 4, 90, '{"en":"Stream backpressure","uk":"Протитиск у потоках"}'::jsonb, '{"en":"A script copies a fast source into a slow writable with a `data` handler that calls `writable.write(chunk)`. Memory keeps growing. What is the correct fix?","uk":"Скрипт копіює швидке джерело в повільний записуваний потік через обробник `data`, що викликає `writable.write(chunk)`. Пам''ять постійно зростає. Яке правильне виправлення?"}'::jsonb, 'nodejs', '{"mode":"single","code":"source.on(\"data\", (chunk) => {\n  writable.write(chunk);\n});","codeLanguage":"js","options":[{"id":"a","text":{"en":"Increase `highWaterMark` on the writable","uk":"Збільшити `highWaterMark` записуваного потоку"}},{"id":"b","text":{"en":"Use `await pipeline(source, writable)` from `node:stream/promises`, which respects `write()` returning `false`","uk":"Використати `await pipeline(source, writable)` з `node:stream/promises`, що враховує повернення `false` з `write()`"}},{"id":"c","text":{"en":"Call `global.gc()` after every chunk","uk":"Викликати `global.gc()` після кожного фрагмента"}},{"id":"d","text":{"en":"Wrap `write` in `setImmediate`","uk":"Обгорнути `write` у `setImmediate`"}}]}'::jsonb, null::jsonb),
  ('node-immediate-vs-timeout', 'quiz', 5, 120, '{"en":"setImmediate inside an I/O callback","uk":"setImmediate усередині I/O-колбека"}'::jsonb, '{"en":"What does this log, and is the order guaranteed?","uk":"Що це виведе і чи гарантовано порядок?"}'::jsonb, 'nodejs', '{"mode":"single","code":"import { readFile } from \"node:fs\";\n\nreadFile(import.meta.filename, () => {\n  setTimeout(() => console.log(\"timeout\"), 0);\n  setImmediate(() => console.log(\"immediate\"));\n});","codeLanguage":"js","options":[{"id":"a","text":{"en":"`timeout`, then `immediate`; guaranteed","uk":"`timeout`, потім `immediate`; гарантовано"}},{"id":"b","text":{"en":"`immediate`, then `timeout`; guaranteed","uk":"`immediate`, потім `timeout`; гарантовано"}},{"id":"c","text":{"en":"Either order; it depends on system load","uk":"Будь-який порядок; залежить від навантаження системи"}},{"id":"d","text":{"en":"Only `immediate`","uk":"Лише `immediate`"}}]}'::jsonb, null::jsonb),
  ('node-promisify', 'practice', 2, 600, '{"en":"Implement promisify","uk":"Реалізуйте promisify"}'::jsonb, '{"en":"Older Node.js APIs use error-first callbacks: `fn(...args, (err, value) => {})`. Implement `promisify(fn)` like `util.promisify`:\n\n- The returned function passes its arguments plus a callback to `fn` and returns a Promise.\n- Reject with `err` when it is truthy; otherwise resolve with `value`.\n- If `fn` throws synchronously, reject instead of throwing.\n- Keep `this`, so methods still work: `obj.read = promisify(obj.read)`.","uk":"Старі API Node.js використовують колбеки з помилкою першим аргументом: `fn(...args, (err, value) => {})`. Реалізуйте `promisify(fn)`, як `util.promisify`:\n\n- Повернена функція передає в `fn` свої аргументи плюс колбек і повертає Promise.\n- Відхиляйте з `err`, якщо він істинний; інакше виконуйте зі значенням `value`.\n- Якщо `fn` синхронно кидає помилку, відхиляйте проміс замість кидання.\n- Зберігайте `this`, щоб методи працювали: `obj.read = promisify(obj.read)`."}'::jsonb, 'nodejs', null::jsonb, '{"framework":"vanilla-js","files":{"/src/promisify.js":"export function promisify(fn) {\n  // TODO: call fn with an error-first callback and settle the promise from it\n  return (...args) => Promise.resolve(undefined);\n}\n","/index.js":"import \"./styles.css\";\nimport { promisify } from \"./src/promisify\";\n\nfunction readConfig(name, callback) {\n  setTimeout(() => (name ? callback(null, { name, debug: true }) : callback(new Error(\"missing name\"))), 100);\n}\n\nconst app = document.getElementById(\"app\");\napp.innerHTML = \"<h1>promisify</h1><p id=\\\"out\\\">loading…</p>\";\nconst out = document.getElementById(\"out\");\nPromise.resolve()\n  .then(() => promisify(readConfig)(\"app\"))\n  .then((config) => (out.textContent = JSON.stringify(config)))\n  .catch((error) => (out.textContent = \"error: \" + error.message));\n"},"visibleFiles":["/src/promisify.js","/index.js"],"activeFile":"/src/promisify.js","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { promisify } from \"../src/promisify\";\n\nconst add = (a, b, cb) => setTimeout(() => cb(null, a + b), 5);\nconst fail = (cb) => setTimeout(() => cb(new Error(\"boom\")), 5);\n\ndescribe(\"promisify\", () => {\n  it(\"returns a promise that resolves with the value\", async () => {\n    const result = promisify(add)(2, 3);\n    expect(result instanceof Promise).toBe(true);\n    expect(await result).toBe(5);\n  });\n  it(\"rejects with the callback error\", async () => {\n    await expect(promisify(fail)()).rejects.toThrow(\"boom\");\n  });\n  it(\"resolves falsy values\", async () => {\n    expect(await promisify((cb) => cb(null, 0))()).toBe(0);\n  });\n  it(\"turns synchronous throws into rejections\", async () => {\n    const thrower = () => {\n      throw new Error(\"sync\");\n    };\n    let threw = false;\n    let promise;\n    try {\n      promise = promisify(thrower)();\n    } catch (error) {\n      threw = true;\n    }\n    expect(threw).toBe(false);\n    await expect(promise).rejects.toThrow(\"sync\");\n  });\n  it(\"keeps this\", async () => {\n    const db = {\n      rows: [\"a\", \"b\"],\n      count(cb) {\n        cb(null, this.rows.length);\n      },\n    };\n    db.countAsync = promisify(db.count);\n    expect(await db.countAsync()).toBe(2);\n  });\n});\n","testCount":5}'::jsonb),
  ('node-blocking', 'quiz', 1, 60, '{"en":"Blocking the event loop","uk":"Блокування циклу подій"}'::jsonb, '{"en":"An Express route runs a CPU-heavy loop for 2 seconds. What happens to other incoming requests meanwhile?","uk":"Маршрут Express виконує CPU-важкий цикл 2 секунди. Що в цей час відбувається з іншими вхідними запитами?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"They wait: the single JavaScript thread is busy","uk":"Вони чекають: єдиний потік JavaScript зайнятий"}},{"id":"b","text":{"en":"Node automatically runs them on other threads","uk":"Node автоматично виконує їх в інших потоках"}},{"id":"c","text":{"en":"They are rejected with 503","uk":"Їх відхиляють з кодом 503"}},{"id":"d","text":{"en":"Nothing, async/await prevents blocking","uk":"Нічого, async/await запобігає блокуванню"}}]}'::jsonb, null::jsonb),
  ('node-microtask-order', 'quiz', 3, 120, '{"en":"nextTick and promises","uk":"nextTick і проміси"}'::jsonb, '{"en":"What do the first two lines printed by this script say?","uk":"Що виведуть перші два рядки цього скрипта?"}'::jsonb, 'nodejs', '{"mode":"single","code":"setTimeout(() => console.log(\"timeout\"), 0);\nsetImmediate(() => console.log(\"immediate\"));\nPromise.resolve().then(() => console.log(\"promise\"));\nprocess.nextTick(() => console.log(\"nextTick\"));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`nextTick` then `promise`","uk":"`nextTick`, потім `promise`"}},{"id":"b","text":{"en":"`promise` then `nextTick`","uk":"`promise`, потім `nextTick`"}},{"id":"c","text":{"en":"`timeout` then `nextTick`","uk":"`timeout`, потім `nextTick`"}},{"id":"d","text":{"en":"The order is random","uk":"Порядок випадковий"}}]}'::jsonb, null::jsonb),
  ('node-streams', 'quiz', 2, 90, '{"en":"Large files","uk":"Великі файли"}'::jsonb, '{"en":"You need to gzip a 5 GB log file on a server with 1 GB of RAM. What''s the right approach?","uk":"Треба стиснути gzip-ом файл журналу на 5 ГБ на сервері з 1 ГБ пам''яті. Який підхід правильний?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Stream it: `pipeline(createReadStream, createGzip(), createWriteStream)`","uk":"Обробити потоково: `pipeline(createReadStream, createGzip(), createWriteStream)`"}},{"id":"b","text":{"en":"`fs.readFile` the whole file, then `zlib.gzipSync`","uk":"Прочитати весь файл через `fs.readFile`, потім `zlib.gzipSync`"}},{"id":"c","text":{"en":"Split it into 5 `readFileSync` calls","uk":"Розбити на 5 викликів `readFileSync`"}},{"id":"d","text":{"en":"Increase the Node heap to 6 GB","uk":"Збільшити купу Node до 6 ГБ"}}]}'::jsonb, null::jsonb),
  ('node-unhandled-rejection', 'quiz', 3, 120, '{"en":"Unhandled rejections","uk":"Необроблені відхилення"}'::jsonb, '{"en":"In current Node.js versions, what happens by default when a promise rejects and nobody handles it?","uk":"Що за замовчуванням відбувається в сучасних версіях Node.js, коли проміс відхиляється й ніхто цього не обробляє?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"The process logs the error and exits with a non-zero code","uk":"Процес записує помилку в журнал і завершується з ненульовим кодом"}},{"id":"b","text":{"en":"Nothing, the rejection is silently ignored","uk":"Нічого, відхилення тихо ігнорується"}},{"id":"c","text":{"en":"The promise is retried automatically","uk":"Проміс автоматично повторюється"}},{"id":"d","text":{"en":"Only a deprecation warning is printed","uk":"Друкується лише попередження про застарілість"}}]}'::jsonb, null::jsonb),
  ('node-scaling-cores', 'quiz', 4, 150, '{"en":"Using all cores","uk":"Використання всіх ядер"}'::jsonb, '{"en":"A Node API runs on an 8-core machine but CPU usage never exceeds ~12%. What''s the standard way to use the whole machine?","uk":"Node API працює на 8-ядерній машині, але завантаження CPU не перевищує ~12%. Який стандартний спосіб використати всю машину?"}'::jsonb, 'nodejs', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Run several stateless processes (cluster, PM2 or containers) behind a load balancer","uk":"Запустити кілька процесів без стану (cluster, PM2 або контейнери) за балансувальником навантаження"}},{"id":"b","text":{"en":"Set `UV_THREADPOOL_SIZE=8`","uk":"Встановити `UV_THREADPOOL_SIZE=8`"}},{"id":"c","text":{"en":"Use more `async` functions","uk":"Використати більше `async`-функцій"}},{"id":"d","text":{"en":"Switch to `setImmediate` everywhere","uk":"Скрізь перейти на `setImmediate`"}}]}'::jsonb, null::jsonb),
  ('npm-ci-vs-install', 'quiz', 2, 75, '{"en":"npm ci versus npm install","uk":"npm ci проти npm install"}'::jsonb, '{"en":"Which command should a CI pipeline run to install dependencies, and why?","uk":"Яку команду має запускати CI-конвеєр для встановлення залежностей і чому?"}'::jsonb, null, '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`npm install`, because it updates the lockfile to the latest versions","uk":"`npm install`, бо він оновлює lock-файл до останніх версій"}},{"id":"b","text":{"en":"`npm ci`, because it installs exactly what package-lock.json records and fails if it disagrees with package.json","uk":"`npm ci`, бо він встановлює рівно те, що записано в package-lock.json, і падає, якщо це не збігається з package.json"}},{"id":"c","text":{"en":"`npm start`, because it installs and runs the project","uk":"`npm start`, бо він встановлює і запускає проєкт"}},{"id":"d","text":{"en":"`npm update`, because it keeps every dependency current","uk":"`npm update`, бо він тримає кожну залежність актуальною"}}]}'::jsonb, null::jsonb),
  ('npm-semver-range', 'practice', 4, 1200, '{"en":"Check versions against npm ranges","uk":"Перевірте версії за діапазонами npm"}'::jsonb, '{"en":"When `package.json` says `\"lodash\": \"^4.17.0\"`, npm decides which installed versions match. Implement `satisfies(version, range)` in `src/semver.ts` for the common cases:\n\n- A full version is `MAJOR.MINOR.PATCH`; anything else is a `SyntaxError` (\"Invalid version: …\").\n- `*` matches everything, and an exact version matches only itself.\n- Comparators `>=`, `<=`, `>`, `<` and `=`. Several comparators separated by spaces must all hold, so `>=1.2.0 <2.0.0` is a range.\n- `^` allows changes that don''t alter the first non-zero part: `^1.2.3` is `>=1.2.3 <2.0.0`, `^0.2.3` is `<0.3.0`, `^0.0.3` is `<0.0.4`. A partial such as `^1` means `^1.0.0`.\n- `~` allows patch-level changes: `~1.2.3` is `<1.3.0`, and `~1` is `<2.0.0`.","uk":"Коли в `package.json` написано `\"lodash\": \"^4.17.0\"`, npm вирішує, які встановлені версії підходять. Реалізуйте `satisfies(version, range)` у `src/semver.ts` для поширених випадків:\n\n- Повна версія — це `MAJOR.MINOR.PATCH`; усе інше — це `SyntaxError` (\"Invalid version: …\").\n- `*` підходить для всього, а точна версія — лише для себе.\n- Оператори `>=`, `<=`, `>`, `<` і `=`. Кілька операторів через пробіл мають виконуватися всі разом, тож `>=1.2.0 <2.0.0` — це діапазон.\n- `^` дозволяє зміни, що не змінюють першу ненульову частину: `^1.2.3` — це `>=1.2.3 <2.0.0`, `^0.2.3` — це `<0.3.0`, `^0.0.3` — це `<0.0.4`. Неповна версія на кшталт `^1` означає `^1.0.0`.\n- `~` дозволяє зміни на рівні патча: `~1.2.3` — це `<1.3.0`, а `~1` — це `<2.0.0`."}'::jsonb, null, null::jsonb, '{"framework":"vanilla-ts","files":{"/src/semver.ts":"/**\n * Does a version satisfy an npm-style range? Supports *, exact versions, the comparators\n * >= <= > < =, several comparators separated by spaces (all must hold), and ^ and ` ranges.\n */\nexport function satisfies(version: string, range: string): boolean {\n  // TODO\n  return false;\n}\n","/index.ts":"import \"./styles.css\";\nimport { satisfies } from \"./src/semver\";\n\ndocument.getElementById(\"app\")!.innerHTML = ''<h1>Semver</h1><pre id=\"out\"></pre>'';\ndocument.getElementById(\"out\")!.textContent = [\"1.4.2\", \"2.0.0\"].map((v) => v + \" ^1.2.3 → \" + satisfies(v, \"^1.2.3\")).join(\"\\n\");\n"},"visibleFiles":["/src/semver.ts"],"activeFile":"/src/semver.ts","tests":"import { describe, it, expect } from \"./test-kit\";\nimport { satisfies } from \"../src/semver\";\n\ndescribe(\"satisfies\", () => {\n  it(\"caret ranges allow changes that keep the major version\", () => {\n    expect(satisfies(\"1.4.2\", \"^1.2.3\")).toBe(true);\n    expect(satisfies(\"2.0.0\", \"^1.2.3\")).toBe(false);\n    expect(satisfies(\"1.2.2\", \"^1.2.3\")).toBe(false);\n  });\n  it(\"caret ranges below 1.0 lock the minor version, and below 0.1 the patch\", () => {\n    expect(satisfies(\"0.2.9\", \"^0.2.3\")).toBe(true);\n    expect(satisfies(\"0.3.0\", \"^0.2.3\")).toBe(false);\n    expect(satisfies(\"0.0.3\", \"^0.0.3\")).toBe(true);\n    expect(satisfies(\"0.0.4\", \"^0.0.3\")).toBe(false);\n  });\n  it(\"caret with only a major accepts any minor and patch\", () => {\n    expect(satisfies(\"1.0.0\", \"^1\")).toBe(true);\n    expect(satisfies(\"1.9.9\", \"^1\")).toBe(true);\n    expect(satisfies(\"2.0.0\", \"^1\")).toBe(false);\n  });\n  it(\"tilde ranges allow patch changes\", () => {\n    expect(satisfies(\"1.2.9\", \"`1.2.3\")).toBe(true);\n    expect(satisfies(\"1.3.0\", \"`1.2.3\")).toBe(false);\n    expect(satisfies(\"1.2.0\", \"`1.2\")).toBe(true);\n    expect(satisfies(\"1.3.0\", \"`1.2\")).toBe(false);\n  });\n  it(\"tilde with only a major accepts any minor\", () => {\n    expect(satisfies(\"1.9.9\", \"`1\")).toBe(true);\n    expect(satisfies(\"2.0.0\", \"`1\")).toBe(false);\n  });\n  it(\"combines comparators separated by spaces\", () => {\n    expect(satisfies(\"1.5.0\", \">=1.2.0 <2.0.0\")).toBe(true);\n    expect(satisfies(\"2.0.0\", \">=1.2.0 <2.0.0\")).toBe(false);\n    expect(satisfies(\"1.1.9\", \">=1.2.0 <2.0.0\")).toBe(false);\n  });\n  it(\"matches exact versions and anything with *\", () => {\n    expect(satisfies(\"1.2.3\", \"1.2.3\")).toBe(true);\n    expect(satisfies(\"1.2.4\", \"1.2.3\")).toBe(false);\n    expect(satisfies(\"0.0.1\", \"*\")).toBe(true);\n  });\n  it(\"rejects invalid versions\", () => {\n    expect(() => satisfies(\"1.2\", \"^1\")).toThrow(\"Invalid version\");\n  });\n});\n","testCount":8}'::jsonb),
  ('oop-four-pillars', 'quiz', 1, 45, '{"en":"The four pillars","uk":"Чотири принципи"}'::jsonb, '{"en":"Which of these is **not** one of the four pillars of OOP?","uk":"Що з цього **не** є одним із чотирьох принципів ООП?"}'::jsonb, 'oop', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Encapsulation","uk":"Інкапсуляція"}},{"id":"b","text":{"en":"Polymorphism","uk":"Поліморфізм"}},{"id":"c","text":{"en":"Memoisation","uk":"Мемоізація"}},{"id":"d","text":{"en":"Inheritance","uk":"Успадкування"}}]}'::jsonb, null::jsonb),
  ('oop-private-fields', 'quiz', 2, 90, '{"en":"`#private` vs `private`","uk":"`#private` чи `private`"}'::jsonb, '{"en":"What is the difference between these two fields at **runtime**?","uk":"Яка різниця між цими двома полями **під час виконання**?"}'::jsonb, 'oop', '{"mode":"single","code":"class Card {\n  #pin = \"1234\";\n  private token = \"abc\";\n}\nconst card = new Card();","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`#pin` can''t be read outside the class; `private token` is erased by TypeScript and is readable via `(card as any).token`","uk":"`#pin` не можна прочитати поза класом; `private token` TypeScript стирає, і його можна прочитати через `(card as any).token`"}},{"id":"b","text":{"en":"Both are inaccessible outside the class","uk":"Обидва недоступні поза класом"}},{"id":"c","text":{"en":"Both are ordinary public properties at runtime","uk":"Обидва під час виконання є звичайними публічними властивостями"}},{"id":"d","text":{"en":"`private` is enforced at runtime; `#` is only a naming convention","uk":"`private` забезпечується під час виконання; `#` лише домовленість щодо назв"}}]}'::jsonb, null::jsonb),
  ('oop-super-before-this', 'quiz', 2, 60, '{"en":"`this` before `super()`","uk":"`this` до `super()`"}'::jsonb, '{"en":"What happens when `new Admin(\"Ada\")` runs?","uk":"Що станеться під час виконання `new Admin(\"Ada\")`?"}'::jsonb, 'oop', '{"mode":"single","code":"class User {\n  constructor(name) { this.name = name; }\n}\nclass Admin extends User {\n  constructor(name) {\n    this.role = \"admin\";\n    super(name);\n  }\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`ReferenceError`: `this` can''t be used before `super()` in a derived class","uk":"`ReferenceError`: у похідному класі не можна використовувати `this` до `super()`"}},{"id":"b","text":{"en":"It works; `role` is set and then `name`","uk":"Працює: спершу встановлюється `role`, потім `name`"}},{"id":"c","text":{"en":"`name` is `undefined` but no error is thrown","uk":"`name` дорівнює `undefined`, але помилки немає"}},{"id":"d","text":{"en":"`TypeError`: classes can''t have constructors with parameters","uk":"`TypeError`: класи не можуть мати конструктори з параметрами"}}]}'::jsonb, null::jsonb),
  ('oop-detached-method', 'quiz', 3, 90, '{"en":"A detached method","uk":"Відірваний метод"}'::jsonb, '{"en":"Clicking the button throws `TypeError: Cannot read properties of undefined (reading ''count'')`. Why?","uk":"Натискання кнопки кидає `TypeError: Cannot read properties of undefined (reading ''count'')`. Чому?"}'::jsonb, 'oop', '{"mode":"single","code":"class Counter {\n  count = 0;\n  increment() {\n    this.count++;\n    console.log(this.count);\n  }\n}\nconst counter = new Counter();\nbutton.addEventListener(\"click\", counter.increment);","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`counter.increment` is passed without its object, so `this` is not `counter` when it runs; bind it or use an arrow wrapper","uk":"`counter.increment` передано без об''єкта, тож під час виклику `this` не є `counter`; прив''яжіть його або використайте стрілочну обгортку"}},{"id":"b","text":{"en":"Class fields can''t be numbers","uk":"Поля класу не можуть бути числами"}},{"id":"c","text":{"en":"`addEventListener` only accepts arrow functions","uk":"`addEventListener` приймає лише стрілочні функції"}},{"id":"d","text":{"en":"`count` must be declared `static`","uk":"`count` треба оголосити як `static`"}}]}'::jsonb, null::jsonb),
  ('oop-polymorphic-dispatch', 'quiz', 3, 90, '{"en":"Overrides and `super`","uk":"Перевизначення і `super`"}'::jsonb, '{"en":"What does this log?","uk":"Що виведе цей код?"}'::jsonb, 'oop', '{"mode":"single","code":"class Animal {\n  speak() { return this.sound() + \"!\"; }\n  sound() { return \"...\"; }\n}\nclass Cat extends Animal {\n  sound() { return \"meow\"; }\n}\nclass Kitten extends Cat {\n  speak() { return super.speak().toUpperCase(); }\n}\nconsole.log([new Animal(), new Cat(), new Kitten()].map((a) => a.speak()));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[\"...!\", \"meow!\", \"MEOW!\"]`","uk":"`[\"...!\", \"meow!\", \"MEOW!\"]`"}},{"id":"b","text":{"en":"`[\"...!\", \"...!\", \"...!\"]`","uk":"`[\"...!\", \"...!\", \"...!\"]`"}},{"id":"c","text":{"en":"`[\"...!\", \"meow!\", \"meow!\"]`","uk":"`[\"...!\", \"meow!\", \"meow!\"]`"}},{"id":"d","text":{"en":"`[\"...!\", \"meow!\", \"...!\"]`","uk":"`[\"...!\", \"meow!\", \"...!\"]`"}}]}'::jsonb, null::jsonb),
  ('oop-composition', 'quiz', 3, 120, '{"en":"Penguins can''t fly","uk":"Пінгвіни не літають"}'::jsonb, '{"en":"`Bird` has a `fly()` method. `Penguin extends Bird` overrides `fly()` to throw. Code that loops over `Bird[]` and calls `fly()` now crashes. What is the best fix?","uk":"`Bird` має метод `fly()`. `Penguin extends Bird` перевизначає `fly()` так, що він кидає помилку. Код, що перебирає `Bird[]` і викликає `fly()`, тепер падає. Яке виправлення найкраще?"}'::jsonb, 'oop', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"Model abilities separately (e.g. a `Flyer` interface or a composed movement object) so only flying birds promise `fly()`","uk":"Моделювати здібності окремо (наприклад, інтерфейс `Flyer` або вкладений об''єкт руху), щоб лише птахи, які літають, обіцяли `fly()`"}},{"id":"b","text":{"en":"Wrap every `fly()` call in `try/catch`","uk":"Обгорнути кожен виклик `fly()` у `try/catch`"}},{"id":"c","text":{"en":"Add `if (bird instanceof Penguin)` checks wherever `fly()` is called","uk":"Додати перевірки `if (bird instanceof Penguin)` всюди, де викликається `fly()`"}},{"id":"d","text":{"en":"Make `Penguin.fly()` silently do nothing","uk":"Зробити так, щоб `Penguin.fly()` мовчки нічого не робив"}}]}'::jsonb, null::jsonb),
  ('oop-own-keys', 'quiz', 4, 120, '{"en":"Where methods and fields live","uk":"Де живуть методи й поля"}'::jsonb, '{"en":"What does `Object.keys(new Dog(\"Rex\"))` return?","uk":"Що повертає `Object.keys(new Dog(\"Rex\"))`?"}'::jsonb, 'oop', '{"mode":"single","code":"class Dog {\n  wag = () => \"wag\";\n  constructor(name) {\n    this.name = name;\n  }\n  bark() {\n    return \"woof\";\n  }\n}","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[\"wag\", \"name\"]`","uk":"`[\"wag\", \"name\"]`"}},{"id":"b","text":{"en":"`[\"name\", \"bark\", \"wag\"]`","uk":"`[\"name\", \"bark\", \"wag\"]`"}},{"id":"c","text":{"en":"`[\"name\"]`","uk":"`[\"name\"]`"}},{"id":"d","text":{"en":"`[\"name\", \"wag\"]`","uk":"`[\"name\", \"wag\"]`"}}]}'::jsonb, null::jsonb),
  ('oop-fragile-base', 'quiz', 5, 150, '{"en":"The fragile base class","uk":"Крихкий базовий клас"}'::jsonb, '{"en":"What is `list.count` after this runs?","uk":"Чому дорівнює `list.count` після виконання?"}'::jsonb, 'oop', '{"mode":"single","code":"class List {\n  items = [];\n  add(x) { this.items.push(x); }\n  addAll(xs) { xs.forEach((x) => this.add(x)); }\n}\nclass CountingList extends List {\n  count = 0;\n  add(x) { this.count++; super.add(x); }\n  addAll(xs) { this.count += xs.length; super.addAll(xs); }\n}\nconst list = new CountingList();\nlist.addAll([1, 2, 3]);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`6`","uk":"`6`"}},{"id":"b","text":{"en":"`3`","uk":"`3`"}},{"id":"c","text":{"en":"`0`","uk":"`0`"}},{"id":"d","text":{"en":"`4`","uk":"`4`"}}]}'::jsonb, null::jsonb),
  ('oop-bank-account', 'practice', 3, 1080, '{"en":"Encapsulated bank accounts","uk":"Інкапсульовані банківські рахунки"}'::jsonb, '{"en":"Refactor `src/account.ts` so accounts protect their own invariants:\n\n**`Account`**\n- Keep the balance and history in `#private` fields. `balance` is a **read-only** getter; `history` returns a **copy** of the entries.\n- `deposit` / `withdraw` throw a `RangeError` unless the amount is a positive, finite number.\n- `withdraw` throws (and changes nothing) when there isn''t enough money.\n- Give subclasses two `protected` hooks: `canWithdraw(amount)` and a single method that changes the balance and records the entry.\n\n**`SavingsAccount(owner, rate)`**: `addInterest()` adds `balance × rate`, rounded to cents, as an `\"interest\"` entry.\n\n**`CheckingAccount(owner, overdraft)`**: may go negative, down to `-overdraft`, by overriding `canWithdraw`.\n\nRound balances to cents to avoid floating-point noise.","uk":"Переробіть `src/account.ts`, щоб рахунки самі захищали свої інваріанти:\n\n**`Account`**\n- Зберігайте баланс та історію в полях `#private`. `balance` є гетером **лише для читання**; `history` повертає **копію** записів.\n- `deposit` / `withdraw` кидають `RangeError`, якщо сума не є додатним скінченним числом.\n- `withdraw` кидає помилку (і нічого не змінює), коли грошей недостатньо.\n- Дайте підкласам два `protected` хуки: `canWithdraw(amount)` і єдиний метод, що змінює баланс і записує операцію.\n\n**`SavingsAccount(owner, rate)`**: `addInterest()` додає `balance × rate`, округлене до копійок, як запис `\"interest\"`.\n\n**`CheckingAccount(owner, overdraft)`**: може йти в мінус до `-overdraft`, перевизначаючи `canWithdraw`.\n\nОкруглюйте баланс до копійок, щоб уникнути похибок чисел з рухомою комою."}'::jsonb, 'oop', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/account.ts":"export type Entry = { type: \"deposit\" | \"withdraw\" | \"interest\"; amount: number };\n\nexport class Account {\n  // TODO: encapsulate. Anyone can currently write balance and history directly.\n  balance = 0;\n  history: Entry[] = [];\n\n  constructor(readonly owner: string) {}\n\n  deposit(amount: number): void {\n    this.balance += amount;\n    this.history.push({ type: \"deposit\", amount });\n  }\n\n  withdraw(amount: number): void {\n    this.balance -= amount;\n    this.history.push({ type: \"withdraw\", amount });\n  }\n}\n\nexport class SavingsAccount extends Account {\n  constructor(owner: string, readonly rate: number) {\n    super(owner);\n  }\n\n  addInterest(): void {\n    // TODO\n  }\n}\n\nexport class CheckingAccount extends Account {\n  constructor(owner: string, readonly overdraft: number) {\n    super(owner);\n  }\n}\n","/index.ts":"import \"./styles.css\";\nimport { CheckingAccount, SavingsAccount } from \"./src/account\";\n\nconst savings = new SavingsAccount(\"Ada\", 0.1);\nsavings.deposit(200);\nsavings.addInterest();\nconst checking = new CheckingAccount(\"Bob\", 50);\nchecking.deposit(20);\ntry {\n  checking.withdraw(60);\n} catch (e) {\n  console.warn(e);\n}\ndocument.getElementById(\"app\")!.innerHTML =\n  ''<h1>Accounts</h1><p>Savings: <output id=\"savings\">'' + savings.balance + ''</output></p><p>Checking: <output id=\"checking\">'' + checking.balance + \"</output></p>\";\n"},"visibleFiles":["/src/account.ts","/index.ts"],"activeFile":"/src/account.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { Account, CheckingAccount, SavingsAccount } from \"../src/account\";\n\ndescribe(\"Account\", () => {\n  it(\"deposits and withdraws\", () => {\n    const acc = new Account(\"Ada\");\n    acc.deposit(100);\n    acc.withdraw(30);\n    expect(acc.balance).toBe(70);\n    expect(acc.history).toEqual([\n      { type: \"deposit\", amount: 100 },\n      { type: \"withdraw\", amount: 30 },\n    ]);\n  });\n  it(\"rejects non-positive or invalid amounts\", () => {\n    const acc = new Account(\"Ada\");\n    expect(() => acc.deposit(0)).toThrow();\n    expect(() => acc.deposit(-5)).toThrow();\n    expect(() => acc.deposit(Number.NaN)).toThrow();\n    expect(() => acc.withdraw(Infinity)).toThrow();\n    expect(acc.balance).toBe(0);\n  });\n  it(\"refuses to overdraw and leaves the balance unchanged\", () => {\n    const acc = new Account(\"Ada\");\n    acc.deposit(10);\n    expect(() => acc.withdraw(11)).toThrow();\n    expect(acc.balance).toBe(10);\n    expect(acc.history).toHaveLength(1);\n  });\n  it(\"keeps the balance private and read-only\", () => {\n    const acc = new Account(\"Ada\");\n    acc.deposit(5);\n    expect(Reflect.set(acc, \"balance\", 1000000)).toBe(false);\n    expect(acc.balance).toBe(5);\n    expect(Object.getOwnPropertyNames(acc)).not.toContain(\"balance\");\n  });\n  it(\"returns a copy of the history\", () => {\n    const acc = new Account(\"Ada\");\n    acc.deposit(5);\n    acc.history.push({ type: \"deposit\", amount: 999 });\n    acc.history[0].amount = 999;\n    expect(acc.history).toEqual([{ type: \"deposit\", amount: 5 }]);\n  });\n});\n\ndescribe(\"subclasses\", () => {\n  it(\"adds interest to savings, rounded to cents\", () => {\n    const s = new SavingsAccount(\"Ada\", 0.035);\n    s.deposit(100.1);\n    s.addInterest();\n    expect(s.balance).toBe(103.6);\n    expect(s.history[1]).toEqual({ type: \"interest\", amount: 3.5 });\n    expect(s instanceof Account).toBe(true);\n  });\n  it(\"lets checking accounts use the overdraft, but no further\", () => {\n    const c = new CheckingAccount(\"Bob\", 50);\n    c.deposit(20);\n    c.withdraw(60);\n    expect(c.balance).toBe(-40);\n    expect(() => c.withdraw(11)).toThrow();\n    c.withdraw(10);\n    expect(c.balance).toBe(-50);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"220\")).id).toBe(\"savings\");\n    expect((await screen.findByText(\"-40\")).id).toBe(\"checking\");\n  });\n});\n","testCount":8}'::jsonb),
  ('oop-shapes', 'practice', 2, 900, '{"en":"Polymorphic shapes","uk":"Поліморфні фігури"}'::jsonb, '{"en":"Complete the shape hierarchy in `src/shapes.ts`:\n\n- `Circle`, `Rectangle` and `Square` compute `area()` and `perimeter()`. `Square(side)` **is a** `Rectangle`.\n- Constructors throw a `RangeError` for dimensions that aren''t positive finite numbers.\n- `describe()` is implemented **once**, in `Shape`, and returns `\"<ClassName> area=<area> perimeter=<perimeter>\"` with 2 decimals, e.g. `\"Square area=4.00 perimeter=8.00\"`.\n- `Shape` is abstract: `new Shape()` must throw even when TypeScript is bypassed with a cast.\n- `largest(shapes)` returns the shape with the biggest area, or `undefined` for an empty list.","uk":"Допишіть ієрархію фігур у `src/shapes.ts`:\n\n- `Circle`, `Rectangle` і `Square` обчислюють `area()` і `perimeter()`. `Square(side)` **є** `Rectangle`.\n- Конструктори кидають `RangeError` для розмірів, що не є додатними скінченними числами.\n- `describe()` реалізовано **один раз**, у `Shape`, і він повертає `\"<ClassName> area=<area> perimeter=<perimeter>\"` з 2 знаками після коми, наприклад `\"Square area=4.00 perimeter=8.00\"`.\n- `Shape` абстрактний: `new Shape()` має кидати помилку, навіть якщо TypeScript обійдено приведенням типу.\n- `largest(shapes)` повертає фігуру з найбільшою площею або `undefined` для порожнього списку."}'::jsonb, 'oop', null::jsonb, '{"framework":"vanilla-ts","files":{"/src/shapes.ts":"export abstract class Shape {\n  abstract area(): number;\n  abstract perimeter(): number;\n\n  describe(): string {\n    // TODO: \"<ClassName> area=<2 decimals> perimeter=<2 decimals>\"\n    return \"\";\n  }\n}\n\nexport class Circle extends Shape {\n  constructor(readonly radius: number) {\n    super();\n  }\n  area() {\n    return 0;\n  }\n  perimeter() {\n    return 0;\n  }\n}\n\nexport class Rectangle extends Shape {\n  constructor(readonly width: number, readonly height: number) {\n    super();\n  }\n  area() {\n    return 0;\n  }\n  perimeter() {\n    return 0;\n  }\n}\n\nexport class Square extends Rectangle {\n  constructor(side: number) {\n    super(side, side);\n  }\n}\n\n/** The shape with the biggest area, or undefined for an empty list. */\nexport function largest(shapes: Shape[]): Shape | undefined {\n  return shapes[0];\n}\n","/index.ts":"import \"./styles.css\";\nimport { Circle, Rectangle, Square, largest } from \"./src/shapes\";\n\nconst shapes = [new Square(2), new Circle(1), new Rectangle(3, 4)];\ndocument.getElementById(\"app\")!.innerHTML =\n  \"<h1>Shapes</h1><ul>\" +\n  shapes.map((s) => \"<li>\" + s.describe() + \"</li>\").join(\"\") +\n  ''</ul><p>Largest: <output id=\"largest\">'' + (largest(shapes)?.describe() ?? \"none\") + \"</output></p>\";\n"},"visibleFiles":["/src/shapes.ts","/index.ts"],"activeFile":"/src/shapes.ts","tests":"import { describe, it, expect, screen } from \"./test-kit\";\nimport { Circle, Rectangle, Shape, Square, largest } from \"../src/shapes\";\n\ndescribe(\"shapes\", () => {\n  it(\"computes area and perimeter\", () => {\n    expect(new Rectangle(2, 3).area()).toBe(6);\n    expect(new Rectangle(2, 3).perimeter()).toBe(10);\n    expect(new Square(4).area()).toBe(16);\n    expect(new Circle(1).area()).toBeCloseTo(Math.PI);\n    expect(new Circle(2).perimeter()).toBeCloseTo(4 * Math.PI);\n  });\n  it(\"describes every shape with one shared method\", () => {\n    expect(new Square(2).describe()).toBe(\"Square area=4.00 perimeter=8.00\");\n    expect(new Circle(1).describe()).toBe(\"Circle area=3.14 perimeter=6.28\");\n    expect(Object.prototype.hasOwnProperty.call(Circle.prototype, \"describe\")).toBe(false);\n    expect(Object.prototype.hasOwnProperty.call(Square.prototype, \"describe\")).toBe(false);\n  });\n  it(\"models a square as a rectangle\", () => {\n    const sq = new Square(3);\n    expect(sq instanceof Rectangle).toBe(true);\n    expect(sq instanceof Shape).toBe(true);\n    expect(sq.width).toBe(3);\n    expect(sq.height).toBe(3);\n  });\n  it(\"rejects invalid dimensions\", () => {\n    expect(() => new Circle(0)).toThrow();\n    expect(() => new Rectangle(2, -1)).toThrow();\n    expect(() => new Square(Number.NaN)).toThrow();\n  });\n  it(\"refuses to instantiate the abstract Shape at runtime\", () => {\n    const AnyShape = Shape as any;\n    expect(() => new AnyShape()).toThrow();\n  });\n  it(\"finds the largest shape\", () => {\n    const shapes = [new Square(2), new Circle(2), new Rectangle(3, 4)];\n    expect(largest(shapes)).toBe(shapes[1]);\n    expect(largest([])).toBe(undefined);\n  });\n  it(\"renders the demo\", async () => {\n    expect((await screen.findByText(\"Rectangle area=12.00 perimeter=14.00\", { selector: \"output\" })).id).toBe(\"largest\");\n  });\n});\n","testCount":7}'::jsonb),
  ('pw-locators-autowait', 'quiz', 2, 75, '{"en":"Locators versus element handles","uk":"Локатори проти дескрипторів елементів"}'::jsonb, '{"en":"Why does Playwright recommend locators such as `page.getByRole(...)` over element handles from `page.$()`?","uk":"Чому Playwright рекомендує локатори на кшталт `page.getByRole(...)`, а не дескриптори елементів з `page.$()`?"}'::jsonb, 'playwright', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"A locator re-finds the element and waits until it''s visible, enabled and stable before acting, while a handle is a snapshot that can go stale","uk":"Локатор знову знаходить елемент і чекає, доки він стане видимим, активним і стабільним, перш ніж діяти, а дескриптор — це знімок, який може застаріти"}},{"id":"b","text":{"en":"Handles are slower to type, but locators run in the browser''s native process","uk":"Дескриптори повільніше набирати, а локатори працюють у нативному процесі браузера"}},{"id":"c","text":{"en":"Locators are the only way to take screenshots","uk":"Локатори — єдиний спосіб робити знімки екрана"}},{"id":"d","text":{"en":"Handles can''t click buttons","uk":"Дескриптори не можуть клікати кнопки"}}]}'::jsonb, null::jsonb),
  ('pw-resilient-selectors', 'quiz', 3, 90, '{"en":"The most resilient selector","uk":"Найстійкіший селектор"}'::jsonb, '{"en":"A form has a button labelled \"Save\". Which selector survives the most markup refactors?","uk":"У формі є кнопка з написом \"Save\". Який селектор переживе найбільше змін розмітки?"}'::jsonb, 'playwright', '{"mode":"single","codeLanguage":"ts","options":[{"id":"a","text":{"en":"`page.locator(\"div > div:nth-child(3) > button\")`","uk":"`page.locator(\"div > div:nth-child(3) > button\")`"}},{"id":"b","text":{"en":"`page.getByRole(\"button\", { name: \"Save\" })`","uk":"`page.getByRole(\"button\", { name: \"Save\" })`"}},{"id":"c","text":{"en":"`page.locator(\"//button[2]\")`","uk":"`page.locator(\"//button[2]\")`"}},{"id":"d","text":{"en":"`page.locator(\".btn-primary-x7\")`","uk":"`page.locator(\".btn-primary-x7\")`"}}]}'::jsonb, null::jsonb),
