  ('regex-lookahead', 'quiz', 4, 120, '{"en":"Lookaheads for password rules","uk":"Перевірки вперед для правил пароля"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'regex', '{"mode":"single","code":"const strong = /^(?=.*\\d)(?=.*[a-z])(?=.*[A-Z]).{8,}$/;\nconsole.log([\"password\", \"Password1\", \"PASSWORD1\", \"Pass1\"].map((p) => strong.test(p)));","codeLanguage":"js","options":[{"id":"a","text":{"en":"`[ false, true, false, false ]`","uk":"`[ false, true, false, false ]`"}},{"id":"b","text":{"en":"`[ false, true, true, false ]`","uk":"`[ false, true, true, false ]`"}},{"id":"c","text":{"en":"`[ true, true, false, false ]`","uk":"`[ true, true, false, false ]`"}},{"id":"d","text":{"en":"`[ false, true, false, true ]`","uk":"`[ false, true, false, true ]`"}}]}'::jsonb, null::jsonb),
