  ('coerce-null-comparisons', 'quiz', 2, 90, '{"en":"`null` in comparisons","uk":"`null` у порівняннях"}'::jsonb, '{"en":"What does this print?","uk":"Що виведе цей код?"}'::jsonb, 'type-coercion', '{"mode":"single","code":"console.log(null == 0, null >= 0, null == undefined, undefined == 0);","codeLanguage":"js","options":[{"id":"a","text":{"en":"`false true true false`","uk":"`false true true false`"}},{"id":"b","text":{"en":"`true true true true`","uk":"`true true true true`"}},{"id":"c","text":{"en":"`false false true false`","uk":"`false false true false`"}},{"id":"d","text":{"en":"`true true false false`","uk":"`true true false false`"}}]}'::jsonb, null::jsonb),
