  ('csharp', 'tarot', null::jsonb, ('"5: The Hierophant | Death | The Empress\n10: Wheel of Fortune | The Emperor | The Hanged Man\n21: The World | The Devil | The Magician\n"'::jsonb #>> '{}'), ('"using System;\n\nclass Program\n{\n    static string[] GetDeck()\n    {\n        return new[]\n        {\n            \"The Fool\", \"The Magician\", \"The High Priestess\", \"The Empress\",\n            \"The Emperor\", \"The Hierophant\", \"The Lovers\", \"The Chariot\",\n            \"Strength\", \"The Hermit\", \"Wheel of Fortune\", \"Justice\",\n            \"The Hanged Man\", \"Death\", \"Temperance\", \"The Devil\",\n            \"The Tower\", \"The Star\", \"The Moon\", \"The Sun\",\n            \"Judgement\", \"The World\",\n        };\n    }\n\n    // Three cards for the number n: indexes n % 22, n * 7 % 22 and n * n % 22\n    static string[] Spread(int n)\n    {\n        string[] deck = GetDeck();\n        return new[]\n        {\n            deck[n % deck.Length],\n            deck[n * 7 % deck.Length],\n            deck[n * n % deck.Length],\n        };\n    }\n\n    static void Main()\n    {\n        foreach (int n in new[] { 5, 10, 21 })\n        {\n            string[] cards = Spread(n);\n            Console.WriteLine(n + \": \" + cards[0] + \" | \" + cards[1] + \" | \" + cards[2]);\n        }\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'power-array', null::jsonb, ('"1 8 27 64\n4 9 0 25\n1 1\n\n2 3\n8 27\n"'::jsonb #>> '{}'), ('"using System;\n\nclass Program\n{\n    static void Show(int[] numbers)\n    {\n        for (int i = 0; i < numbers.Length; i++)\n        {\n            if (i > 0) Console.Write(\" \");\n            Console.Write(numbers[i]);\n        }\n        Console.WriteLine();\n    }\n\n    // Raises every element to the given power, IN PLACE (power 0 gives 1)\n    static void RaiseToPower(int[] numbers, int power)\n    {\n        for (int i = 0; i < numbers.Length; i++)\n        {\n            int result = 1;\n            for (int k = 0; k < power; k++)\n            {\n                result *= numbers[i];\n            }\n            numbers[i] = result;\n        }\n    }\n\n    // Returns a NEW array of the powers; the original stays unchanged\n    static int[] Powers(int[] numbers, int power)\n    {\n        int[] copy = (int[])numbers.Clone();\n        RaiseToPower(copy, power);\n        return copy;\n    }\n\n    static void Main()\n    {\n        int[] a = { 1, 2, 3, 4 };\n        RaiseToPower(a, 3);\n        Show(a);\n\n        int[] b = { 2, -3, 0, 5 };\n        RaiseToPower(b, 2);\n        Show(b);\n\n        int[] c = { 7, 8 };\n        RaiseToPower(c, 0);\n        Show(c);\n\n        int[] d = new int[0];\n        RaiseToPower(d, 5);\n        Show(d);\n\n        int[] original = { 2, 3 };\n        int[] cubes = Powers(original, 3);\n        Show(original);\n        Show(cubes);\n    }\n}\n"'::jsonb #>> '{}')),
