  ('csharp', 'ini-parser', null::jsonb, ('"links.url = http://x.org/?a=b\nname = Assay\nserver.host = localhost\nserver.port = 8080\nuser.lang = uk\nuser.name = Ann\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\nusing System.IO;\n\nclass Program\n{\n    // Reads INI-style text line by line and returns the settings.\n    // Keys inside a [section] are stored as \"section.key\".\n    static Dictionary<string, string> Parse(string text)\n    {\n        var settings = new Dictionary<string, string>();\n        string section = \"\";\n        var reader = new StringReader(text);\n        string line;\n        while ((line = reader.ReadLine()) != null)\n        {\n            line = line.Trim();\n            if (line.Length == 0 || line.StartsWith(\"#\") || line.StartsWith(\";\"))\n            {\n                continue;\n            }\n            if (line.StartsWith(\"[\") && line.EndsWith(\"]\"))\n            {\n                section = line.Substring(1, line.Length - 2).Trim();\n                continue;\n            }\n            int equals = line.IndexOf(''='');\n            if (equals < 0)\n            {\n                continue;\n            }\n            string key = line.Substring(0, equals).Trim();\n            string value = line.Substring(equals + 1).Trim();\n            if (section.Length > 0)\n            {\n                key = section + \".\" + key;\n            }\n            settings[key] = value;\n        }\n        return settings;\n    }\n\n    static void Main()\n    {\n        string text = \"# settings\\n\" +\n                      \"name = Assay\\n\" +\n                      \"[server]\\n\" +\n                      \"host = localhost\\n\" +\n                      \"port = 8080\\n\" +\n                      \"\\n\" +\n                      \"[user]\\n\" +\n                      \"name = Ann\\n\" +\n                      \"; a comment\\n\" +\n                      \" lang = uk \\n\" +\n                      \"oops, this line has no equals sign\\n\" +\n                      \"[links]\\n\" +\n                      \"url = http://x.org/?a=b\\n\";\n\n        var settings = Parse(text);\n        var keys = new List<string>(settings.Keys);\n        keys.Sort(StringComparer.Ordinal);\n        foreach (string key in keys)\n        {\n            Console.WriteLine(key + \" = \" + settings[key]);\n        }\n    }\n}\n"'::jsonb #>> '{}')),
