  ('csharp', 'limited-size-stack', null::jsonb, ('"True\nfull\n2\n1\n1\nempty\nba\n"'::jsonb #>> '{}'), ('"using System;\n\nclass LimitedStack<T>\n{\n    private readonly T[] items;\n    private int count;\n\n    public LimitedStack(int capacity)\n    {\n        items = new T[capacity];\n    }\n\n    public int Count => count;\n\n    public bool IsFull => count == items.Length;\n\n    public void Push(T item)\n    {\n        if (IsFull)\n        {\n            throw new InvalidOperationException(\"The stack is full\");\n        }\n        items[count] = item;\n        count++;\n    }\n\n    public T Pop()\n    {\n        if (count == 0)\n        {\n            throw new InvalidOperationException(\"The stack is empty\");\n        }\n        count--;\n        T item = items[count];\n        items[count] = default(T);\n        return item;\n    }\n\n    public T Peek()\n    {\n        if (count == 0)\n        {\n            throw new InvalidOperationException(\"The stack is empty\");\n        }\n        return items[count - 1];\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        var s = new LimitedStack<int>(2);\n        s.Push(1);\n        s.Push(2);\n        Console.WriteLine(s.IsFull);\n        try\n        {\n            s.Push(3);\n        }\n        catch (InvalidOperationException)\n        {\n            Console.WriteLine(\"full\");\n        }\n        Console.WriteLine(s.Pop());\n        Console.WriteLine(s.Peek());\n        Console.WriteLine(s.Count);\n        s.Pop();\n        try\n        {\n            s.Pop();\n        }\n        catch (InvalidOperationException)\n        {\n            Console.WriteLine(\"empty\");\n        }\n        var names = new LimitedStack<string>(3);\n        names.Push(\"a\");\n        names.Push(\"b\");\n        Console.WriteLine(names.Pop() + names.Pop());\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'undo-practice', null::jsonb, ('"hello world\nhello\nhello world\nhello\n[]\n[]\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\n\nclass TextEditor\n{\n    private string text = \"\";\n    private readonly Stack<string> history = new Stack<string>();\n\n    public string Text => text;\n\n    // Saves the text, then adds s to the end\n    public void Type(string s)\n    {\n        history.Push(text);\n        text += s;\n    }\n\n    // If the text is not empty: saves the text, then removes the last n characters\n    public void Erase(int n)\n    {\n        if (text.Length == 0)\n        {\n            return;\n        }\n        history.Push(text);\n        int remove = Math.Min(n, text.Length);\n        text = text.Substring(0, text.Length - remove);\n    }\n\n    // Restores the text from the history, if there is any\n    public void Undo()\n    {\n        if (history.Count > 0)\n        {\n            text = history.Pop();\n        }\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        var ed = new TextEditor();\n        ed.Type(\"hello\");\n        ed.Type(\" world\");\n        Console.WriteLine(ed.Text);\n        ed.Erase(6);\n        Console.WriteLine(ed.Text);\n        ed.Undo();\n        Console.WriteLine(ed.Text);\n        ed.Undo();\n        Console.WriteLine(ed.Text);\n        ed.Undo();\n        ed.Undo();\n        Console.WriteLine(\"[\" + ed.Text + \"]\");\n        ed.Erase(100);\n        Console.WriteLine(\"[\" + ed.Text + \"]\");\n    }\n}\n"'::jsonb #>> '{}')),
