  ('csharp', 'tuples-deconstruction', null::jsonb, ('"4 42 18\n7 7 7\nLovelace, Ada\n[Plato] []\nThe array is empty\n"'::jsonb #>> '{}'), ('"using System;\n\nclass Program\n{\n    // The minimum, the maximum and the average; throws ArgumentException for an empty array\n    static (int Min, int Max, double Average) Stats(int[] values)\n    {\n        if (values.Length == 0)\n        {\n            throw new ArgumentException(\"The array is empty\");\n        }\n\n        int min = int.MaxValue;\n        int max = int.MinValue;\n        int sum = 0;\n        foreach (int value in values)\n        {\n            if (value < min) min = value;\n            if (value > max) max = value;\n            sum += value;\n        }\n        return (min, max, (double)sum / values.Length);\n    }\n\n    // The part before the first space and the part after it\n    static (string First, string Last) SplitName(string fullName)\n    {\n        int space = fullName.IndexOf('' '');\n        if (space < 0)\n        {\n            return (fullName, \"\");\n        }\n        return (fullName.Substring(0, space), fullName.Substring(space + 1));\n    }\n\n    static void Main()\n    {\n        var (min, max, average) = Stats(new[] { 4, 8, 15, 16, 23, 42 });\n        Console.WriteLine(min + \" \" + max + \" \" + average);\n\n        var stats = Stats(new[] { 7 });\n        Console.WriteLine(stats.Min + \" \" + stats.Max + \" \" + stats.Average);\n\n        var (first, last) = SplitName(\"Ada Lovelace\");\n        Console.WriteLine(last + \", \" + first);\n\n        var (onlyFirst, noLast) = SplitName(\"Plato\");\n        Console.WriteLine(\"[\" + onlyFirst + \"] [\" + noLast + \"]\");\n\n        try\n        {\n            Stats(new int[0]);\n        }\n        catch (ArgumentException e)\n        {\n            Console.WriteLine(e.Message);\n        }\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'modern-csharp-review', '{"records-version":["a"],"hat-index":["a"],"primary-ctor":["a"],"nullable-types":["a"],"bang":["a"],"deconstruct":["a"]}'::jsonb, null::text, null::text),
  ('csharp', 'manual-di', null::jsonb, ('"EMAIL: Order placed: book\nEMAIL: Order placed: pen\nSaved: 2\nFake got: Order placed: lamp\nMissing: repository\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\n\ninterface IOrderRepository\n{\n    void Save(string order);\n    int Count { get; }\n}\n\ninterface INotifier\n{\n    void Notify(string message);\n}\n\nclass InMemoryRepository : IOrderRepository\n{\n    private readonly List<string> orders = new List<string>();\n    public void Save(string order) { orders.Add(order); }\n    public int Count { get { return orders.Count; } }\n}\n\n// Sends real e-mails (here: prints them)\nclass EmailNotifier : INotifier\n{\n    public void Notify(string message) { Console.WriteLine(\"EMAIL: \" + message); }\n}\n\n// For tests: only remembers the messages\nclass FakeNotifier : INotifier\n{\n    public readonly List<string> Sent = new List<string>();\n    public void Notify(string message) { Sent.Add(message); }\n}\n\n// Places orders: saves them and notifies the customer\nclass OrderService\n{\n    private readonly IOrderRepository repository;\n    private readonly INotifier notifier;\n\n    public OrderService(IOrderRepository repository, INotifier notifier)\n    {\n        if (repository == null)\n        {\n            throw new ArgumentNullException(nameof(repository));\n        }\n        if (notifier == null)\n        {\n            throw new ArgumentNullException(nameof(notifier));\n        }\n        this.repository = repository;\n        this.notifier = notifier;\n    }\n\n    public void Place(string order)\n    {\n        if (string.IsNullOrWhiteSpace(order))\n        {\n            throw new ArgumentException(\"The order is empty\");\n        }\n        repository.Save(order);\n        notifier.Notify(\"Order placed: \" + order);\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        // The composition root: the real objects are created and connected here\n        var repository = new InMemoryRepository();\n        var service = new OrderService(repository, new EmailNotifier());\n        service.Place(\"book\");\n        service.Place(\"pen\");\n        Console.WriteLine(\"Saved: \" + repository.Count);\n\n        // What a unit test does: a fake notifier instead of real e-mails\n        var fake = new FakeNotifier();\n        var tested = new OrderService(new InMemoryRepository(), fake);\n        tested.Place(\"lamp\");\n        Console.WriteLine(\"Fake got: \" + string.Join(\"; \", fake.Sent));\n\n        try\n        {\n            new OrderService(null, fake);\n        }\n        catch (ArgumentNullException e)\n        {\n            Console.WriteLine(\"Missing: \" + e.ParamName);\n        }\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'mini-container', null::jsonb, ('"Good morning, Ann\nSame greeter: False\nSame clock: True\nClocks created: 1\nNo registration for ILogger\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\n\ninterface IClock\n{\n    int Hour { get; }\n}\n\nclass FixedClock : IClock\n{\n    public static int Created;\n    public FixedClock() { Created++; }\n    public int Hour { get { return 9; } }\n}\n\ninterface IGreeter\n{\n    string Greet(string name);\n}\n\nclass Greeter : IGreeter\n{\n    private readonly IClock clock;\n    public Greeter(IClock clock) { this.clock = clock; }\n    public string Greet(string name)\n    {\n        return (clock.Hour < 12 ? \"Good morning, \" : \"Good afternoon, \") + name;\n    }\n}\n\ninterface ILogger\n{\n    void Log(string message);\n}\n\n// Creates services from registered factories and keeps singletons\nclass Container\n{\n    private readonly Dictionary<Type, Func<Container, object>> factories = new Dictionary<Type, Func<Container, object>>();\n    private readonly HashSet<Type> singletonTypes = new HashSet<Type>();\n    private readonly Dictionary<Type, object> singletons = new Dictionary<Type, object>();\n\n    public void AddTransient<T>(Func<Container, T> factory) where T : class\n    {\n        factories[typeof(T)] = c => factory(c);\n        singletonTypes.Remove(typeof(T));\n    }\n\n    public void AddSingleton<T>(Func<Container, T> factory) where T : class\n    {\n        factories[typeof(T)] = c => factory(c);\n        singletonTypes.Add(typeof(T));\n    }\n\n    public T Resolve<T>() where T : class\n    {\n        Type type = typeof(T);\n        Func<Container, object> factory;\n        if (!factories.TryGetValue(type, out factory))\n        {\n            throw new InvalidOperationException(\"No registration for \" + type.Name);\n        }\n        if (!singletonTypes.Contains(type))\n        {\n            return (T)factory(this);\n        }\n        object instance;\n        if (!singletons.TryGetValue(type, out instance))\n        {\n            instance = factory(this);\n            singletons[type] = instance;\n        }\n        return (T)instance;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        var container = new Container();\n        container.AddSingleton<IClock>(c => new FixedClock());\n        container.AddTransient<IGreeter>(c => new Greeter(c.Resolve<IClock>()));\n\n        IGreeter first = container.Resolve<IGreeter>();\n        IGreeter second = container.Resolve<IGreeter>();\n        Console.WriteLine(first.Greet(\"Ann\"));\n        Console.WriteLine(\"Same greeter: \" + ReferenceEquals(first, second));\n        Console.WriteLine(\"Same clock: \" + ReferenceEquals(container.Resolve<IClock>(), container.Resolve<IClock>()));\n        Console.WriteLine(\"Clocks created: \" + FixedClock.Created);\n\n        try\n        {\n            container.Resolve<ILogger>();\n        }\n        catch (InvalidOperationException e)\n        {\n            Console.WriteLine(e.Message);\n        }\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'di-quiz', '{"ctor-injection":["a"],"service-locator":["a"],"scoped-meaning":["a"],"captive":["a"],"background-db":["a"],"many-impls":["a","b"]}'::jsonb, null::text, null::text),
  ('csharp', 'middleware-pipeline', null::jsonb, ('"log: start /home\nendpoint: /home\nlog: end /home -> 200\nlog: start /admin/users\nlog: end /admin/users -> 403\nlog: start /boom\nerror: boom\nlog: end /boom -> 500\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\n\n// Stands for HttpContext\nclass Context\n{\n    public string Path;\n    public int Status = 200;\n}\n\n// One step of request handling\ndelegate void RequestDelegate(Context context);\n\n// Collects middleware and builds the pipeline\nclass PipelineBuilder\n{\n    private readonly List<Func<RequestDelegate, RequestDelegate>> middlewares = new List<Func<RequestDelegate, RequestDelegate>>();\n\n    // Remembers a middleware; returns the builder for chaining\n    public PipelineBuilder Use(Action<Context, Action> middleware)\n    {\n        middlewares.Add(next => context => middleware(context, () => next(context)));\n        return this;\n    }\n\n    // Wraps the endpoint into all middleware; the first added is the outermost\n    public RequestDelegate Build(RequestDelegate endpoint)\n    {\n        RequestDelegate app = endpoint;\n        for (int i = middlewares.Count - 1; i >= 0; i--)\n        {\n            app = middlewares[i](app);\n        }\n        return app;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        var builder = new PipelineBuilder();\n        builder\n            .Use((context, next) =>\n            {\n                Console.WriteLine(\"log: start \" + context.Path);\n                next();\n                Console.WriteLine(\"log: end \" + context.Path + \" -> \" + context.Status);\n            })\n            .Use((context, next) =>\n            {\n                if (context.Path.StartsWith(\"/admin\"))\n                {\n                    context.Status = 403;\n                    return;\n                }\n                next();\n            })\n            .Use((context, next) =>\n            {\n                try\n                {\n                    next();\n                }\n                catch (Exception e)\n                {\n                    context.Status = 500;\n                    Console.WriteLine(\"error: \" + e.Message);\n                }\n            });\n\n        RequestDelegate app = builder.Build(context =>\n        {\n            if (context.Path == \"/boom\")\n            {\n                throw new InvalidOperationException(\"boom\");\n            }\n            Console.WriteLine(\"endpoint: \" + context.Path);\n        });\n\n        foreach (string path in new[] { \"/home\", \"/admin/users\", \"/boom\" })\n        {\n            app(new Context { Path = path });\n        }\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'aspnet-quiz', '{"short-circuit":["a"],"auth-order":["a"],"middleware-scoped":["a"],"api-controller":["a"],"401-403":["a"],"created":["a"]}'::jsonb, null::text, null::text),
  ('csharp', 'di-aspnet-review', '{"config-override":["a"],"options-snapshot":["a"],"log-template":["a"],"secrets":["a","b"],"http-client-factory":["a"],"exception-handler-first":["a"]}'::jsonb, null::text, null::text),
  ('csharp', 'test-doubles-quiz', '{"stub-vs-mock":["a"],"fake":["a"],"what-to-replace":["a","b","c"],"moq-virtual":["a"],"over-mocking":["a"]}'::jsonb, null::text, null::text),
  ('csharp', 'mini-xunit', null::jsonb, ('"PASS AddOne_CountIsOne\nPASS AddTwo_CountIsTwo\nPASS Add_ReturnsSum(-1, 1, 0)\nFAIL Add_ReturnsSum(2, 2, 5): expected 5, but was 4\nPASS Add_ReturnsSum(2, 3, 5)\nSKIP Discount_IsApplied: discounts are not ready\nFAIL First_OfEmptyCart: InvalidOperationException: the cart is empty\nFAIL Total_IsWrong: expected 4, but was 5\nPassed: 4, failed: 3, skipped: 1\nInstances created: 7, disposed: 7\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Reflection;\n\n// --- A tiny test framework: attributes and assertions ---\n[AttributeUsage(AttributeTargets.Method)]\nclass FactAttribute : Attribute\n{\n    // When set, the test is not run: it is reported as skipped, with this reason\n    public string Skip { get; set; }\n}\n\n[AttributeUsage(AttributeTargets.Method)]\nclass TheoryAttribute : Attribute\n{\n}\n\n[AttributeUsage(AttributeTargets.Method, AllowMultiple = true)]\nclass InlineDataAttribute : Attribute\n{\n    public readonly object[] Data;\n    public InlineDataAttribute(params object[] data) { Data = data; }\n}\n\nclass AssertException : Exception\n{\n    public AssertException(string message) : base(message) { }\n}\n\nstatic class Assert\n{\n    public static void Equal<T>(T expected, T actual)\n    {\n        if (!EqualityComparer<T>.Default.Equals(expected, actual))\n        {\n            throw new AssertException(\"expected \" + expected + \", but was \" + actual);\n        }\n    }\n}\n\n// --- The tests to run ---\nclass CartTests : IDisposable\n{\n    public static int Created;\n    public static int Disposed;\n\n    // Every test expects to start with an empty cart\n    private readonly List<string> cart = new List<string>();\n\n    public CartTests() { Created++; }\n\n    public void Dispose() { Disposed++; }\n\n    [Fact]\n    public void AddOne_CountIsOne()\n    {\n        cart.Add(\"apple\");\n        Assert.Equal(1, cart.Count);\n    }\n\n    [Fact]\n    public void AddTwo_CountIsTwo()\n    {\n        cart.Add(\"pear\");\n        cart.Add(\"plum\");\n        Assert.Equal(2, cart.Count);\n    }\n\n    [Fact]\n    public void Total_IsWrong()\n    {\n        Assert.Equal(4, 2 + 3);\n    }\n\n    [Fact]\n    public void First_OfEmptyCart()\n    {\n        if (cart.Count == 0)\n        {\n            throw new InvalidOperationException(\"the cart is empty\");\n        }\n    }\n\n    [Fact(Skip = \"discounts are not ready\")]\n    public void Discount_IsApplied()\n    {\n        throw new NotImplementedException();\n    }\n\n    [Theory]\n    [InlineData(2, 3, 5)]\n    [InlineData(-1, 1, 0)]\n    [InlineData(2, 2, 5)]\n    public void Add_ReturnsSum(int a, int b, int sum)\n    {\n        Assert.Equal(sum, a + b);\n    }\n\n    // Not a test: it has no attribute\n    public void Helper()\n    {\n        Console.WriteLine(\"Helper must not run\");\n    }\n}\n\nclass Program\n{\n    // Finds the tests of testClass, runs each of them and prints the report\n    static void Run(Type testClass)\n    {\n        int passed = 0, failed = 0, skipped = 0;\n        foreach (MethodInfo method in testClass.GetMethods().OrderBy(m => m.Name, StringComparer.Ordinal))\n        {\n            var fact = method.GetCustomAttribute<FactAttribute>();\n            var cases = new List<KeyValuePair<string, object[]>>();\n            if (fact != null && fact.Skip != null)\n            {\n                Console.WriteLine(\"SKIP \" + method.Name + \": \" + fact.Skip);\n                skipped++;\n                continue;\n            }\n            if (fact != null)\n            {\n                cases.Add(new KeyValuePair<string, object[]>(method.Name, new object[0]));\n            }\n            else if (method.GetCustomAttribute<TheoryAttribute>() != null)\n            {\n                foreach (var data in method.GetCustomAttributes<InlineDataAttribute>())\n                {\n                    string name = method.Name + \"(\" + string.Join(\", \", data.Data) + \")\";\n                    cases.Add(new KeyValuePair<string, object[]>(name, data.Data));\n                }\n                cases = cases.OrderBy(c => c.Key, StringComparer.Ordinal).ToList();\n            }\n            foreach (var testCase in cases)\n            {\n                string error = RunOne(testClass, method, testCase.Value);\n                if (error == null)\n                {\n                    Console.WriteLine(\"PASS \" + testCase.Key);\n                    passed++;\n                }\n                else\n                {\n                    Console.WriteLine(\"FAIL \" + testCase.Key + \": \" + error);\n                    failed++;\n                }\n            }\n        }\n        Console.WriteLine(\"Passed: \" + passed + \", failed: \" + failed + \", skipped: \" + skipped);\n    }\n\n    // Runs one test on a new instance of the class: null if it passed, otherwise the reason it failed\n    static string RunOne(Type testClass, MethodInfo method, object[] args)\n    {\n        object instance = Activator.CreateInstance(testClass);\n        try\n        {\n            method.Invoke(instance, args);\n            return null;\n        }\n        catch (TargetInvocationException e)\n        {\n            Exception error = e.InnerException;\n            if (error is AssertException)\n            {\n                return error.Message;\n            }\n            return error.GetType().Name + \": \" + error.Message;\n        }\n        finally\n        {\n            var disposable = instance as IDisposable;\n            if (disposable != null)\n            {\n                disposable.Dispose();\n            }\n        }\n    }\n\n    static void Main()\n    {\n        Run(typeof(CartTests));\n        Console.WriteLine(\"Instances created: \" + CartTests.Created + \", disposed: \" + CartTests.Disposed);\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'expiring-cache', null::jsonb, ('"ok: the fake clock shows the start time\nok: Advance moves the fake clock\nok: a fresh value is found\nok: a missing key is not found\nok: a value is still there after 4:59\nok: a value is gone after exactly 5 minutes\nok: Set again restarts the timer\nok: RemoveExpired removes only the expired entries\n"'::jsonb #>> '{}'), ('"using System;\nusing System.Collections.Generic;\n\n// The current time, as a dependency\ninterface IClock\n{\n    DateTime UtcNow { get; }\n}\n\n// The real clock, for production\nclass SystemClock : IClock\n{\n    public DateTime UtcNow { get { return DateTime.UtcNow; } }\n}\n\n// A clock for tests: it stands still until the test moves it\nclass FakeClock : IClock\n{\n    private DateTime now;\n\n    public FakeClock(DateTime start)\n    {\n        now = start;\n    }\n\n    public DateTime UtcNow { get { return now; } }\n\n    public void Advance(TimeSpan time)\n    {\n        now += time;\n    }\n}\n\n// Keeps each value for `ttl` after it was set\nclass ExpiringCache\n{\n    private readonly IClock clock;\n    private readonly TimeSpan ttl;\n    private readonly Dictionary<string, string> values = new Dictionary<string, string>();\n    private readonly Dictionary<string, DateTime> expiresAt = new Dictionary<string, DateTime>();\n\n    public ExpiringCache(IClock clock, TimeSpan ttl)\n    {\n        this.clock = clock;\n        this.ttl = ttl;\n    }\n\n    // The number of stored entries, expired or not\n    public int Count { get { return values.Count; } }\n\n    public void Set(string key, string value)\n    {\n        values[key] = value;\n        expiresAt[key] = clock.UtcNow + ttl;\n    }\n\n    // A value is found until its time is up: at the moment set time + ttl it is already gone\n    public bool TryGet(string key, out string value)\n    {\n        if (values.ContainsKey(key) && clock.UtcNow < expiresAt[key])\n        {\n            value = values[key];\n            return true;\n        }\n        value = null;\n        return false;\n    }\n\n    // Deletes the expired entries and returns how many were deleted\n    public int RemoveExpired()\n    {\n        DateTime now = clock.UtcNow;\n        var expired = new List<string>();\n        foreach (var entry in expiresAt)\n        {\n            if (now >= entry.Value)\n            {\n                expired.Add(entry.Key);\n            }\n        }\n        foreach (string key in expired)\n        {\n            values.Remove(key);\n            expiresAt.Remove(key);\n        }\n        return expired.Count;\n    }\n}\n\nclass Program\n{\n    static void Check(string name, Func<bool> test)\n    {\n        string result;\n        try\n        {\n            result = test() ? \"ok\" : \"FAIL\";\n        }\n        catch (Exception e)\n        {\n            result = \"FAIL (\" + e.GetType().Name + \")\";\n        }\n        Console.WriteLine(result + \": \" + name);\n    }\n\n    static void Main()\n    {\n        var start = new DateTime(2025, 3, 1, 12, 0, 0, DateTimeKind.Utc);\n        var ttl = TimeSpan.FromMinutes(5);\n\n        Check(\"the fake clock shows the start time\", () => new FakeClock(start).UtcNow == start);\n        Check(\"Advance moves the fake clock\", () =>\n        {\n            var clock = new FakeClock(start);\n            clock.Advance(TimeSpan.FromSeconds(90));\n            return clock.UtcNow == start.AddSeconds(90);\n        });\n        Check(\"a fresh value is found\", () =>\n        {\n            var cache = new ExpiringCache(new FakeClock(start), ttl);\n            cache.Set(\"user:1\", \"Ann\");\n            string value;\n            return cache.TryGet(\"user:1\", out value) && value == \"Ann\";\n        });\n        Check(\"a missing key is not found\", () =>\n        {\n            var cache = new ExpiringCache(new FakeClock(start), ttl);\n            string value;\n            return !cache.TryGet(\"user:2\", out value);\n        });\n        Check(\"a value is still there after 4:59\", () =>\n        {\n            var clock = new FakeClock(start);\n            var cache = new ExpiringCache(clock, ttl);\n            cache.Set(\"user:1\", \"Ann\");\n            clock.Advance(new TimeSpan(0, 4, 59));\n            string value;\n            return cache.TryGet(\"user:1\", out value);\n        });\n        Check(\"a value is gone after exactly 5 minutes\", () =>\n        {\n            var clock = new FakeClock(start);\n            var cache = new ExpiringCache(clock, ttl);\n            cache.Set(\"user:1\", \"Ann\");\n            clock.Advance(ttl);\n            string value;\n            return !cache.TryGet(\"user:1\", out value);\n        });\n        Check(\"Set again restarts the timer\", () =>\n        {\n            var clock = new FakeClock(start);\n            var cache = new ExpiringCache(clock, ttl);\n            cache.Set(\"user:1\", \"Ann\");\n            clock.Advance(TimeSpan.FromMinutes(3));\n            cache.Set(\"user:1\", \"Bob\");\n            clock.Advance(TimeSpan.FromMinutes(3));\n            string value;\n            return cache.TryGet(\"user:1\", out value) && value == \"Bob\";\n        });\n        Check(\"RemoveExpired removes only the expired entries\", () =>\n        {\n            var clock = new FakeClock(start);\n            var cache = new ExpiringCache(clock, ttl);\n            cache.Set(\"old\", \"1\");\n            clock.Advance(TimeSpan.FromMinutes(2));\n            cache.Set(\"new\", \"2\");\n            clock.Advance(TimeSpan.FromMinutes(3));\n            int removed = cache.RemoveExpired();\n            string value;\n            return removed == 1 && cache.Count == 1 && cache.TryGet(\"new\", out value);\n        });\n    }\n}\n"'::jsonb #>> '{}')),
  ('csharp', 'testing-advanced-review', '{"xunit-instances":["a"],"class-fixture":["a"],"async-test":["a"],"flaky":["a","b","c"],"httpclient":["a"],"web-app-factory":["a"],"ef-inmemory":["a"],"private-methods":["a"],"pyramid":["a"]}'::jsonb, null::text, null::text)
) as v(course_slug, slide_slug, quiz_answers, expected_output, solution)
join public.courses c on c.slug = v.course_slug
join public.course_slides s on s.course_id = c.id and s.slug = v.slide_slug and s.source = 'seed'
on conflict (slide_id) do update set quiz_answers = excluded.quiz_answers, expected_output = excluded.expected_output,
  solution = excluded.solution;

delete from public.course_slides s using public.courses c where s.course_id = c.id and c.slug = 'databases' and s.source = 'seed' and s.slug not in ('what-is-a-database', 'relational-model', 'meet-postgresql', 'fundamentals-quiz', 'first-query', 'select-basics', 'where-and-null', 'cheap-in-stock', 'contact-gaps', 'order-limit', 'second-page', 'select-quiz', 'postgres-data-types', 'create-alter-table', 'constraints', 'users-table', 'ddl-quiz', 'insert-update-delete', 'upsert-returning', 'restock', 'dml-quiz', 'inner-join', 'order-lines', 'outer-joins', 'never-ordered', 'self-cross-joins', 'who-is-the-boss', 'joins-quiz', 'aggregate-functions', 'revenue-by-category', 'having-filter', 'loyal-customers', 'aggregation-quiz', 'subqueries', 'above-category-average', 'ctes-recursive', 'org-chart', 'subqueries-quiz', 'window-ranking', 'top-two-per-department', 'window-frames', 'running-total', 'windows-quiz', 'normalization', 'modeling-relationships', 'product-tags', 'schema-design-quiz', 'how-indexes-work', 'index-types', 'explain-analyze', 'index-the-feed', 'indexes-quiz', 'acid-transactions', 'savepoint-script', 'isolation-mvcc', 'locking-concurrency', 'optimistic-locking', 'transactions-quiz', 'views-materialized', 'order-totals-view', 'functions-triggers', 'price-history-trigger', 'jsonb-postgres', 'advanced-quiz', 'nosql-landscape', 'mongodb-documents', 'mongodb-basics-quiz', 'mongodb-aggregation', 'mongo-to-jsonb', 'mongodb-modeling', 'mongodb-scaling', 'mongodb-quiz', 'sql-vs-nosql', 'choosing-a-database', 'sql-vs-nosql-quiz', 'monthly-report', 'databases-final-exam');

delete from public.course_modules m using public.courses c where m.course_id = c.id and c.slug = 'databases' and m.source = 'seed' and m.slug not in ('db-fundamentals', 'sql-select', 'ddl-types', 'dml', 'joins', 'aggregation', 'subqueries-ctes', 'window-functions', 'schema-design', 'indexes-performance', 'transactions', 'postgres-advanced', 'nosql-mongodb', 'sql-vs-nosql', 'databases-final') and not exists (select 1 from public.course_slides x where x.module_id = m.id and x.source = 'admin');

