delete from public.course_modules m using public.courses c where m.course_id = c.id and c.slug = 'dynamics-crm' and m.source = 'seed' and m.slug not in ('crm-platform', 'crm-solutions', 'crm-sdk', 'crm-plugins', 'crm-workflows', 'crm-execute', 'crm-plugin-quality', 'crm-extensibility', 'crm-client', 'crm-client-advanced', 'crm-client-best-practices', 'crm-web-resources', 'crm-web-api', 'crm-sample-app', 'crm-security') and not exists (select 1 from public.course_slides x where x.module_id = m.id and x.source = 'admin');

